INSERT INTO work_items VALUES(14,'خطة الربع التالي Task C: استمرار أو تصحيح بناءً على التعلم الموثق','Relaunch','New',1,'Owner','Medium','2026-12-27',0,'','بناء خطة الربع التالي (Task C) على التعلم الموثق من أول 30 يوم: استمرار أو تصحيح','مرحلة 4 — تقييم واستمرار/تصحيح — خطة Relaunch مولّدة من قراءة الويبسايت والسوق، بانتظار تواريخ واعتماد المالك',1795032253661,1795048308829);
INSERT INTO content_items VALUES(1,'ريل سيلوليت: روتين متكامل في البيت — مش كريم واحد وخلاص','Instagram','تعليم — مشكلة السيلوليت','Reel','مسودة','2026-11-21','السيلوليت مش هيتعالج بمنتج واحد سحري… روتين متكامل في البيت: صابونة كولاجين + سكراب بالكافيين + كريم ريتينول وكافيين بالليل، بخطوات ثابتة واستمرارية. (الكريم فيه ريتينول: ممنوع أثناء الحمل، وفي الرضاعة بعد استشارة الدكتور)','70% Proven','75% Deep Problem-Solving','فجوة السوق الموثقة: كلمة «سيلوليت» في مكتبة إعلانات ميتا عيادات وأجهزة بس — صفر معلنين DTC لروتين منزلي (عصر 18-11-2026)','تحديث بريف 19-11-2026 04:29 EET — مسودة للاعتماد، لا نشر إلا بقرار المالك. الجمهور: ست بتدوّر على «علاج السيلوليت في المنزل» و«كريم سيلوليت بعد الولادة» (لغة بحث جوجل مصر) — مناطقها: الأفخاذ/المؤخرة. كلامها: «علاج السيلوليت بالقهوة»، «سيلوليت رول». الاعتراضات: (1) جرّبت كريم واحد قبل كده وما شافتش فرق — الدليل المطلوب: روتين متكامل مش كريم واحد؛ (2) السعر مقابل كريم مفرد — الدليل: 3 قطع بسعر روتين واحد. الروتين الكامل 799 إلزامي 3 قطع (تعليمة المالك 1): صابونة كولاجين + سكراب كافيين + كريم ريتينول بالليل — ممنوع إسقاط الصابونة. زاوية تعليمية جديدة: الفرق بين السيلوليت والليبوديما دخل لغة البحث (ملاحظة 17). رول السيلوليت طلب بحث ظاهر لكنه فرصة قيد الدراسة فقط — لا وعد به. إلزامي تحذير الريتينول: «الكريم فيه ريتينول: ممنوع أثناء الحمل، وفي الرضاعة بعد استشارة الدكتور». صياغة عناية بالمظهر فقط، بلا وعود علاجية، بلا هوك إحراج. الثقة: متوسطة — لغة بحث + عصر منافسين، بلا صوت عميلة مباشر بعد (لا insights مسجلة).',1795048337780,1795055525990);
INSERT INTO content_items VALUES(2,'كاروسيل تعليمي: يعني إيه يوريا 25%؟ وليه التركيز بيفرق','Instagram','تعليم — المكونات والتركيزات','Carousel','مسودة','2026-11-22','لما تشوفي «يوريا 25%» على العلبة… الرقم ده مش ديكور. التركيز هو اللي بيحدد قوة التقشير والترطيب. اسحبي عشان تعرفي الفرق بين التركيزات وإمتى تحتاجي الأعلى.','70% Proven','75% Deep Problem-Solving','لغة البحث: «كريم يوريا ٢٠ للجسم» و«كريم يوريا ٤٠ للجسم» ضمن اقتراحات جوجل مصر + فجوة التركيز: زيرا 25% الأعلى إعلاناً مقابل 10–20% عند المنافسين','تحديث بريف 19-11-2026 04:29 EET — مسودة للاعتماد، لا نشر إلا بقرار المالك. الجمهور: باحثة بتقارن تركيزات اليوريا قبل الشراء («افضل/احسن كريم يوريا للجسم»، «كريم يوريا ٢٠/٤٠ للجسم»، وصيغة لاتينية جديدة «كريم urea للجسم»). كلامها بالأرقام: بتسأل عن التركيز بالاسم. الاعتراضات: (1) «ليه 25% مش 30%؟» — طلب بحث على يوريا 30% ظاهر (فرصة 1 قيد الدراسة)؛ الرد المسموح حالياً: شرح ليه 25% هو التركيز اليومي المناسب — بلا وعد بمنتج 30% وبلا قرار إنتاج من غير المالك؛ (2) براندات منافسة بالاسم في اقتراحات اليوريا (Mixa/Eveline/Alejon/Novera — ملاحظات 19/23)؛ الدليل المطلوب: 25% الأعلى تركيزاً معلناً في السوق مقابل 10–20% عند المنافسين. شرح مبسط لليوريا ودور التركيز في التقشير اللطيف والترطيب، ومقارنة فئات عامة (10% صيانة / 20% / 25% للحالات العنيدة) من غير ذكر أسماء براندات ومن غير ادعاء طبي. منتج زيرا: لوشن جلد الوزة يوريا 25% 360 جنيه. الثقة: متوسطة — لغة بحث + عصر منافسين، بلا صوت عميلة مباشر بعد.',1795048337824,1795055525958);
INSERT INTO content_items VALUES(3,'ريل KP: جلد الوزة بيتحسن بالاستمرارية — روتين خطواته واضحة','Instagram','تعليم — مشكلة جلد الوزة','Reel','مسودة','2026-11-20','جلد الوزة مش مشكلة كريم واحد… هي مشكلة استمرارية، خصوصاً في الشتا مع جفاف الجلد. روتين واضح في البيت بخطوات ثابتة: تقشير لطيف + ترطيب مركز بيوريا 25%، وتكرار من غير استعجال نتيجة. التفاصيل في البايو.','70% Proven','75% Deep Problem-Solving','تحليل إعلان Alejon (زاوية الاستمرارية) + هيمنة Hepta بالفيديوهات التعليمية — عصر المنافسين 18-11-2026','تحديث بريف 19-11-2026 04:29 EET — مسودة للاعتماد، لا نشر إلا بقرار المالك. الجمهور: ست بتدوّر على «علاج جلد الوزة في البيت/في المنزل» (اقتراح جديد 19-11) — بتدور على حل منزلي مش عيادة/ليزر. كلامها: «علاج جلد الوزة والشعر تحت الجلد» (ربط جديد في البحث)، «سعر كريم جلد الوزة» (نية شرائية). الزاوية الموسمية الإلزامية (تعليمة المالك 1): جفاف الشتا — «جلد الوزة وجفاف الجلد في الشتا» زاوية أساسية للموسم. الاعتراضات: (1) السعر 799 مقابل كريم صيدلية مفرد — منافس Melano Uremel 20% بعرض B1G1 بسعر فعّال 175 للوحدة (ملاحظة 22)؛ الدليل المطلوب: روتين متكامل + يوريا 25% الأعلى تركيزاً معلناً؛ (2) «جرّبت كريمات صيدلية» — براندات (Mixa/Eveline/Alejon) دخلت اقتراحات بحث اليوريا بالاسم (ملاحظات 19/23). تنبيه: «جلد الوزة في الوجه» منطقة بحث جديدة لكن روتين KP الحالي للجسم فقط — فرصة قيد الدراسة، لا ادعاء وجه. خطوات الروتين: سكراب جلد الوزة 440 + لوشن يوريا 25% 360 أو الروتين الكامل 799. توقع واقعي بلا وعد علاجي ولا ضمان نتيجة. ممنوع ادعاء الـ1000+ عميلة قبل التوثيق. الثقة: متوسطة — لغة بحث + عصر منافسين، بلا صوت عميلة مباشر بعد.',1795048337851,1795055525976);
