INSERT INTO competitors VALUES(20,'Naturelle','عناية يدوية طبيعية — خلفية سوق، تشابه 33/100','براند مصري يدوي: سكرابات جسم وقدم ويد ولوشن بارز «magic treatment» ولوشنات يد — البيع بالرسائل على إنستجرام/فيسبوك فقط','Body/Foot/Hand Scrubs + Lotion Bars','لا يوجد سعر EGP موثّق في مسح 2026-11-18 — اتساب فاضي بدل التخمين','https://cairo360.com/article/shopping/glowing-skin-healthy-hair-14-local-brands-that-will-elevate-your-body-routine/','تشابه 33/100 (خلفية سوق): تداخل سكرابات يدوية بحجم متناهي الصغر، مفيش متجر ولا تموضع مشاكل. من مسح وترتيب 2026-11-18.',1795036266860,'','','');
INSERT INTO competitors VALUES(21,'Zynah','قناة توزيع (ماركت بليس) — مش براند','ماركت بليس تجميل مصري: +1,500 منتج محلي من +50 براند، والتسوق حسب المشكلة (Shop by Concern) — الرف اللي بيجمع Bubblzz وUrban Ducks وNorshek وغيرهم','قناة بيع واكتشاف منافسين — وبراندات صغيرة جواه: Areej, Dermacy Labs, Meraki, Moisturella, Nude Skin, Queen by Lord, SESH','قناة توزيع — لا ينطبق سعر منتج','https://zynah.me/collections/shop-by-concern','متصنف قناة توزيع مش منافس براند (تشابه كبراند 15/100 لو اتفرض): أهميته إنه فيد اكتشاف منافسين وقناة توزيع محتملة لزيرا. البراندات الصغيرة اللي بيحملها بتتراقب جواه مش كمنافسين منفصلين. من مسح وترتيب 2026-11-18.',1795036266941,'https://zynah.me','','');
INSERT INTO competitors VALUES(22,'Nivea','عناية جسم جماهيرية عالمية — خلفية سوق، تشابه 22/100','براند عالمي جماهيري (Beiersdorf): لوشنات جسم في كل صيدلية وسوبر ماركت — الأكثر مسحًا في فئة العناية بالجسم في مصر (Sagaci حسب جدول المالك)','Body Lotions (mass)','لم يُسحب سعر في مسح 2026-11-18 (أسعار ريتيل متغيرة حسب القناة)','','تشابه 22/100 (خلفية سوق): المعيار الافتراضي للوشن الجسم في ذهن العميلة وسياق إدراك الأسعار، من غير أي تداخل مشاكل/DTC. من مسح وترتيب 2026-11-18.',1795036266958,'','','');
INSERT INTO competitors VALUES(23,'Haven (Haven Body Care)','عناية يدوية طبيعية — خلفية سوق، تشابه 35/100','براند مصري يدوي بقيادة مؤسِّسة: صابون طبيعي وسيرم شعر وماسكات وجه وزبدة جسم وسكراب (Caramel Haze)، مكونات معتمدة من UK Soil Association','Body Butter / Caramel Haze Body Scrub','لا يوجد سعر EGP موثّق في مسح 2026-11-18 — اتساب فاضي بدل التخمين','https://cairo360.com/article/shopping/glowing-skin-healthy-hair-14-local-brands-that-will-elevate-your-body-routine/','تشابه 35/100 (خلفية سوق): تداخل يدوي طبيعي بحجم متناهي الصغر ومن غير تموضع مشاكل/روتينات ظاهر. من مسح وترتيب 2026-11-18.',1795036267031,'','','');
INSERT INTO competitors VALUES(24,'The Bathland','عناية استحمام جماهيرية — خلفية سوق، تشابه 32/100','براند مصري قائم على تشكيلة روائح (bubblegum, blueberry, lavender vanilla): شاور جل ولوشنات وشامبو بيتباع عبر Talabat Mart','Shower Gel 250ml — 120 EGP','شاور جل 120 — لوشن جسم 214.95 (Talabat Mart)','https://www.talabat.com/egypt/grocery/801350/talabat-mart-el-suez/product/ذا-باث-لاند-شاور-جل-الجسم-فانيليا-لافندر-250-مل/s/935122?aid=6968','تشابه 32/100 (خلفية سوق): أساسيات استحمام معطرة من غير قصة طبيعي/مواد فعالة أو مشاكل. من مسح وترتيب 2026-11-18.',1795036267125,'','','');
INSERT INTO competitors VALUES(25,'Estiara (Estiara Passion)','عطور جسم جماهيرية — خلفية سوق، تشابه 28/100','براند عطور جماهيري: فراجرانس ميست 250مل بتشكيلة روائح واسعة وتوزيع ماركت بليس وصيدليات','Fragrance Mist 250ml — 210-248 EGP (noon)','ميست 187-275 EGP (جوميا/نون)','https://www.noon.com/egypt-en/pink-pea-fragrance-mist-250ml/N28534664A/p/?o=fafaa2411d63807f','تشابه 28/100 (خلفية سوق): بيلمس طرف العطور عند زيرا بس (Body Splash 240 والمخمرية) من غير أي تداخل عناية بشرة. من مسح وترتيب 2026-11-18.',1795036267141,'','','');
INSERT INTO competitors VALUES(26,'Mazora','شدّ وسيلوليت — منافس (جانب السيلوليت)','براند مصري لكريمات شدّ الجسم والسيلوليت بيبيع بعروض خصم موسمية قوية','Cell Firming Cream — خصم Black Friday ‏−50%','600 EGP — منشور بتاريخ 2026-11-12 (مسح 2026-11-18)','','منافس جانب السيلوليت: Cell Firming Cream بسعر 600 EGP مع عرض Black Friday بخصم −50% (منشور بتاريخ 2026-11-12). البيانات من مسح السوق العام الموثّق بتاريخ 2026-11-18 (منشورات وصفحات عامة).',1795036423336,'','','');
INSERT INTO competitors VALUES(27,'Soralone','جلد الوزة / يوريا — منافس (جانب KP/اليوريا)','براند مصري بيبيع منتجات يوريا لجلد الوزة بأسعار منخفضة، معتمد على ريلز صانعي المحتوى وقمع شراء عبر واتساب','Urea 15% Gel — بسعر مخفّض ~125 EGP','~125 EGP (سعر تخفيض) — مسح 2026-11-18','','منافس جانب جلد الوزة: جل يوريا 15% بحوالي 125 EGP، وريلز كرييتورز حول «السر المصري لجلد الوزة»، وقمع شراء واتساب — ضغط سعري ومحتوى على لوشن جلد الوزة يوريا 25% من زيرا (360 EGP). البيانات من مسح السوق العام الموثّق بتاريخ 2026-11-18 (منشورات وصفحات عامة).',1795036423365,'','','');
INSERT INTO competitors VALUES(28,'Tetavara','شدّ وسيلوليت DTC — منافس مباشر (جانب السيلوليت)','أقرب منافس DTC لزيرا: براند مصري مباشر للمستهلك متخصص في كريمات الشدّ والسيلوليت، بيبيع أونلاين بنفس قنوات زيرا','Firming Cream — Buy 1 Get 1 بسعر 350 EGP (175 للوحدة) + هدايا متدرجة لسلال الشراء ≥1,000 و≥1,500 EGP','350 EGP لعرض B1G1 (175/وحدة) — مسح 2026-11-18','','أقرب منافس مباشر لروتين سيلوليت زيرا (799 EGP): نفس نموذج DTC ونفس المشكلة، وبيضغط بعرض Buy 1 Get 1 وهدايا متدرجة حسب قيمة السلة، مع دفع Pink Friday قوي أوائل نوفمبر 2026. البيانات من مسح السوق العام الموثّق بتاريخ 2026-11-18 (منشورات وصفحات عامة) — لم تُقرأ مكتبة إعلانات ميتا مباشرة.',1795036423380,'','','');
INSERT INTO competitors VALUES(29,'Kolagra','جلد الوزة / يوريا — منافس (جانب KP/اليوريا)','براند مصري لمنتجات يوريا للجسم بأسعار اقتصادية متوسطة','Urea Body Milk','220–240 EGP — مسح 2026-11-18','','منافس جانب جلد الوزة/اليوريا: حليب جسم باليوريا بسعر 220–240 EGP — أرخص من لوشن جلد الوزة يوريا 25% من زيرا (360 EGP)، ضغط سعري على نفس المشكلة بتركيز/تموضع أبسط. البيانات من مسح السوق العام الموثّق بتاريخ 2026-11-18 (منشورات وصفحات عامة).',1795036423395,'','','');
INSERT INTO competitors VALUES(30,'Centevia','ترطيب وشدّ — منافس (جانب السيلوليت)','براند مصري للعناية بالجسم بتركيز على الترطيب وباقات العرائس، وأقوى توزيع لصانعي المحتوى في المجموعة مع عروض إثبات بجهاز قياس الترطيب (moisture-meter demos)','Nourish-30 Lotion — 400 EGP؛ Bridal Bundle — 888 EGP','لوشن 400 EGP — باقة عروسة 888 EGP — مسح 2026-11-18','','منافس جانب السيلوليت/الترطيب: لوشن Nourish-30 بسعر 400 EGP وباقة عروسة 888 EGP قريبة من نطاق أسعار روتينات زيرا، مع أقوى creator seeding وعروض إثبات مرئية بقياس الترطيب. البيانات من مسح السوق العام الموثّق بتاريخ 2026-11-18 (منشورات وصفحات عامة).',1795036423408,'','','');
INSERT INTO competitors VALUES(31,'Hepta Skin — هيبتا','جلد الوزة / يوريا — منافس مباشر، أولوية قصوى (اكتُشف 2026-11-18)','براند مصري متخصص في جلد الوزة واليوريا: منتج البطل Carbamide Twenty كريم يوريا 20%، وCarbamide Body Wash يوريا 10%، وHepta Panthenol Heels Cream يوريا 10%. مهيمن على بحثَي «جلد الوزة» (~520 نتيجة) و«كريم يوريا» (~270 نتيجة) في مكتبة إعلانات ميتا. هوكات بقيادة أطباء (د. ناردين، روان). البيع عبر الموقع + الصيدليات.','Carbamide Twenty — Urea 20% Cream','','','اكتُشف بتاريخ 2026-11-18 عبر إعلانات الكلمات المفتاحية في Meta Ads Library (مصر، إعلانات نشطة، متصفح المالك). إعلانات فيديو متعددة شغالة من 8–18 ديسمبر 2025 (~335–345 يوم) — أطول إعلانات جلد وزة شوهدت. منافس مباشر جديد من الطراز الأول لروتين جلد الوزة من زيرا (يوريا 25%، 799 EGP) ولم يكن مُتتبَّعًا من قبل.',1795036988532,'https://ehepta.com','','');
INSERT INTO observations VALUES(1,'قراءة ويبسايت zyra-care.com: الكتالوج والسياسات','https://zyra-care.com','2026-11-18','VERIFIED','23 منتج: روتينات حسب المشكلة (سيلوليت 799، جلد الوزة 799، بشرة دهنية/جافة/باهتة 599، كيت الساحل 1300) + مفردات (لوشن يوريا 25% بـ 360، كريم سيلوليت ريتينول/كافيين بـ 350، سكراب ملح سيوة بـ 390). مكونات معلنة: ملح سيوة، يوريا 25%، كافيين، ريتينول، زبدة شيا.',1795032253402);
INSERT INTO observations VALUES(2,'سوق اليوريا/جلد الوزة مزدحم: تركيزات 10–20% وأسعار 149–439 EGP','صفحات منتجات المنافسين (روابطها في بروفايلات المنافسين)','2026-11-18','VERIFIED','لوشن ZYRA يوريا 25% هو الأعلى تركيزاً في المقارنة المرصودة وبسعر 360 EGP — زاوية تمييز موثقة بالأرقام، والمنافسة الأقوى صيدلية القناة (توزيع صيدليات) لا إعلانية فقط.',1795032253485);
INSERT INTO observations VALUES(3,'اقتراح بحث جديد: «زبدة الشيا الاصلية»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — keyword: زبدة الشيا','2026-11-18','SEARCH-LANGUAGE','اقتراح جديد ظهر لأول مرة في مسح 2026-11-18 23:10 EET للكلمة المتبعة «زبدة الشيا»، وحلّ محل «زبدة الشيا للبشرة» في قائمة الاقتراحات العشرة. يدل على اهتمام الباحثات بالتمييز بين زبدة الشيا الأصلية والمقلدة — زاوية ثقة/أصالة يمكن توظيفها في محتوى زبدة الشيا، وليست منتجاً جديداً لا تحمله زيرا (زبدة الشيا مكوّن موجود أصلاً)، لذلك لم تُنشأ فرصة منتج. باقي الكلمات الـ11 بلا اقتراحات جديدة.',1795036327497);
INSERT INTO observations VALUES(4,'Mazora — نشاط إعلاني: ~10 إعلانات، مكملات تخسيس فقط (كريم السيلوليت غير مُعلَن)','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','2026-11-18','VERIFIED','Mazora عنده ~10 إعلانات نشطة لكنها كلها مكملات تخسيس (Fat Burner, Zero Belly, Slim) — كريم Cell Firming Cream للسيلوليت مش مُعلَن عنه حاليًا على ميتا. أقدم إعلانات من 23 سبتمبر 2026 (56 يوم). العروض: Buy 2 Get 1 / القطعة الثانية بخصم 50%.',1795036997898);
INSERT INTO observations VALUES(5,'Alejon — نشاط إعلاني: ~84 إعلان نشط (Meta Ads Library)','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','2026-11-18','VERIFIED','Alejon عنده ~84 إعلان نشط. نمط White Friday: Buy 2 Get 2 Free + هدية سرية (Secret Gift) + شحن مجاني فوق 1,000 EGP. أقدم إعلانات من 19 أغسطس 2026 (91 يوم) لكريمات اليد والقدم والوجه. فيديو مباشر لجلد الوزة (2:37) شغال من 4 نوفمبر 2026 بالهوك: «حل جلد الوزه واثار جلد الوزه قبل اي حاجه هو الاستمرار» — غسول جسم + كريم يوريا، CTA: Get offer.',1795036997913);
INSERT INTO observations VALUES(6,'Soralone — نشاط إعلاني: ~56 إعلان نشط، كلها بدأت نوفمبر 2026','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','2026-11-18','VERIFIED','Soralone عنده ~56 إعلان نشط، وكلها بدأت بين 3–18 نوفمبر 2026 — دفعة Black Friday جديدة بالكامل، ولا إعلان عمره 30+ يوم في الصفحة الأولى. العرض الأساسي: خصم 50% عند شراء 3 منتجات + شحن مجاني فوق 1,500 EGP. المنتجات المعلنة: Urea 15% Cream Gel لجلد الوزة + Urea 5% Shower Gel.',1795036997929);
INSERT INTO observations VALUES(7,'Centevia — نشاط إعلاني: ~7 إعلانات نشطة، فيديو جلد وزة من 15 أكتوبر 2026','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','2026-11-18','VERIFIED','Centevia عنده ~7 إعلانات نشطة. فيديو جلد وزة شغال من 15 أكتوبر 2026 (34 يوم) بـCTA: Send message. عرض Black Friday: Buy 2 Get 2.',1795036997943);
INSERT INTO observations VALUES(8,'صفر إعلانات نشطة على ميتا: Tetavara وEra Care وKolagra وNefertari','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','2026-11-18','VERIFIED','Tetavara وEra Care (الصفحة الرئيسية) وKolagra وNefertari: صفر إعلانات نشطة في مصر في Meta Ads Library بتاريخ 2026-11-18. ملحوظة مهمة: Tetavara مظلم تمامًا على ميتا رغم عرض Pink Friday الشغال على موقعه (كريم شدّ Buy 1 Get 1 بسعر 350 EGP).',1795036997958);
INSERT INTO observations VALUES(9,'Alejon — بيانات الموقع الموثقة: خط اليوريا/جلد الوزة (تصفح مباشر)','alejon.com — تصفح مباشر عبر جهاز المالك، 2026-11-18','2026-11-18','VERIFIED','خط اليوريا/جلد الوزة عند Alejon = منتجات فردية بس، كلها يوريا 10% ما عدا كريم القدم: Urea Cream 10% (+Salicylic 2% + Shea) — 200ml بـ380 EGP و500ml بـ660 (جديد)؛ Urea Body Wash 500ml بـ390 (يوريا 10%)؛ Foot Cream 75ml بـ295 (يوريا 30%، قدم/كالو بس)؛ Whitening Body Milk 200ml بـ360؛ Post-Laser Cream 75ml بـ240. مفيش منتج مخصص لجلد الوزة — «جلد الوزة» ظهرت في 4 صفحات بس على الموقع كله، وادعاء كريم الـ10% هو تقشير لطيف بيحسّن مظهر KP (مقابل يوريا 25% عند زيرا). كل الـ14 باقة نفدت مخزونًا؛ الباقة الوحيدة القابلة للشراء القريبة من KP: Drink Your Water Box من 1,275 لـ890 EGP. عروض الموقع: Buy 2 Get 2 على أغلب الفردي + اشترِ 4 وخد الأرخصين مجانًا + هدية + شحن مجاني فوق 1,000 + بانر White Friday (B2G2 + Secret Gift). الكتالوج ~110 منتج (85 فردي + 14 باقة + 11 بوكس). ادعاء البراند: كوزميسيوتيكالز من تصميم صيدلانيات مصريات. حدود صريحة: قوائم INCI مقصوصة على صفحاتهم، وبعض المقاسات من محتويات البوكسات مش صفحات المنتجات.',1795037036226);
INSERT INTO observations VALUES(10,'TikTok Top Ads — نتائج الكلمات المفتاحية وحدود العرض المجاني (جلد الوزة/سيلوليت/كريم يوريا)','TikTok Creative Center — Top Ads (مصر) — عبر متصفح المالك، 2026-11-18','2026-11-18','VERIFIED','بحث الكلمات المفتاحية في TikTok Top Ads (مصر): آخر 30 يومًا صفر نتائج للكلمات الثلاث («جلد الوزة»، «سيلوليت»، «كريم يوريا»). آخر 180 يومًا: «جلد الوزة» أظهرت 4 إعلانات فيديو للعناية بالجسم — الأقوى براند غير مُعرَّف بعبوة بيضاء بمضخة (الاسم غير مقروء في الصورة المصغرة): ‏12K إعجاب، CTR أعلى 25%، ميزانية عالية، هدف Traffic؛ علبة Glow and Glory ‏(@GlowandGlory): ‏9K إعجاب، CTR أعلى 13%، ميزانية عالية؛ فيديو أنبوب أخضر مزرق بأسلوب صانع محتوى (6 إعجابات)؛ فيديو «الدلكة» للعناية بالجسم (796 إعجابًا، CTR أعلى 33%). «كريم يوريا» (180 يومًا): نتائج معظمها غير ذات صلة، وإعلان عبوة عناية بالبشرة واحد (نفس العبوة البيضاء بالمضخة): ‏9K إعجاب، CTR أعلى 22%، ميزانية عالية. «سيلوليت»: صفر في النافذتين. حدود القياس: العرض المجاني يُظهر أول 4 نتائج فقط لكل بحث قبل جدار «Log in to access all Top Ads» ولم يتم الضغط على تسجيل دخول الأعمال الإضافي؛ وTop Ads عرض مُنتقى للأعلى أداءً لا مكتبة كاملة — غياب نتيجة لا يثبت أن براندًا لا يعلن على TikTok.',1795037151162);
INSERT INTO observations VALUES(11,'Kolagra — المنافس الوحيد الظاهر في TikTok Top Ads: 4 إعلانات فيديو في 180 يومًا','TikTok Creative Center — Top Ads (مصر) — عبر متصفح المالك، 2026-11-18','2026-11-18','VERIFIED','في بحث TikTok Top Ads (مصر، آخر 180 يومًا) ظهرت لـKolagra أربع إعلانات فيديو للعناية بالبشرة واسم البراند ظاهر على صور المنتجات: الأقوى أنبوب «KOLAGRA 50+» — ‏2K إعجاب، CTR ضمن أعلى 28%، ميزانية عالية؛ أنبوب أخضر — ‏1K إعجاب، CTR ضمن أعلى 49%، ميزانية عالية؛ وإعلانان أضعف (54 و51 إعجابًا). في نافذة آخر 30 يومًا لم تظهر أي نتائج لـKolagra. من بين 8 براندات منافسة تم بحثها (Tetavara، Mazora، Alejon، Era Care، Soralone، Kolagra، Centevia، Nefertari)، Kolagra هو الوحيد الذي ظهرت له إعلانات في Top Ads. تنبيه: Top Ads عرض مُنتقى لأفضل الإعلانات أداءً وليس مكتبة إعلانات كاملة.',1795037151176);
INSERT INTO observations VALUES(12,'اقتراح بحث جديد: «زبدة الشيا للبشرة»','Google Egypt autocomplete — suggestqueries.google.com/complete/search?client=firefox&hl=ar&gl=eg — الكلمة: زبدة الشيا','2026-11-19','SEARCH_LANGUAGE','ظهر الاقتراح لأول مرة في مسح 2026-11-19 00:10 EET مقابل لقطة 2026-11-18 23:49 EET؛ وفي نفس المسح اختفى اقتراح «زبدة الشيا الاصلية». باقي الكلمات الـ12 بدون أي اقتراح جديد. الاقتراح الجديد استخدام لمكوّن موجود أصلاً في منتجات زيرا (زبدة الشيا)، وليس منتجاً أو مشكلة جديدة لا تحملها زيرا، لذلك لا يُفتح كفرصة منتج.',1795039863555);
INSERT INTO observations VALUES(13,'اقتراح بحث جديد: «زبدة الشيا الاصلية»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — مسح لغة البحث الدوري كل 20 دقيقة','2026-11-19','SEARCH_LANGUAGE','ظهر الاقتراح «زبدة الشيا الاصلية» لأول مرة في مسح 2026-11-19 00:29 EET تحت الكلمة المفتاحية «زبدة الشيا» (المركز 9 من 10) — لم يكن موجوداً في لقطة 2026-11-18 22:10 UTC. باقي الكلمات الـ11 بدون اقتراحات جديدة تماماً (نفس المجموعات؛ تغييرات ترتيب فقط في «علاج جلد الوزة» و«سيلوليت» و«يوريا» و«مخمرية»). الاقتراح الجديد صفة أصالة على منتج موجود أصلاً (زبدة الشيا مكوّن في منتجات زيرا) وليس منتجاً أو مشكلة جديدة لا تحملها زيرا، فلا فرصة منتج جديدة منه — لكنه إشارة طلب على التمييز بين الأصلي والمقلّد.',1795041054054);
INSERT INTO observations VALUES(14,'اقتراح بحث جديد: «علاج جلد الوزة في منطقة البكيني»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — الكلمة المتتبعة «علاج جلد الوزة» — مسح 2026-11-19 01:29 EET','2026-11-19','SEARCH_LANGUAGE','اقتراح جديد لم يظهر في اللقطة السابقة (2026-11-18 23:11 UTC)؛ حل محل «علاج جلد الوزة في الوجه». إشارة لغة بحث: اهتمام بعلاج جلد الوزة في منطقة البكيني — ضمن نطاق روتين KP الحالي لزيرا (جلد الوزة للجسم)، وليس منتجاً جديداً. يصلح كزاوية محتوى/إعلان حساسة تُدار بحذر.',1795044780872);
INSERT INTO observations VALUES(15,'اقتراح بحث جديد: «زبدة الشيا للبشرة»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — الكلمة المتتبعة «زبدة الشيا» — مسح 2026-11-19 01:29 EET','2026-11-19','SEARCH_LANGUAGE','اقتراح جديد لم يظهر في اللقطة السابقة (2026-11-18 23:11 UTC)؛ حل محل «زبدة الشيا الاصلية». إشارة لغة بحث: طلب على زبدة الشيا للبشرة تحديداً — زبدة الشيا مكوّن موجود أصلاً في منتجات زيرا، وليس منتجاً أو مشكلة جديدة لا تحملها زيرا. يصلح كزاوية محتوى عن فوائد زبدة الشيا للبشرة.',1795044780887);
INSERT INTO observations VALUES(16,'Urban Ducks — سكرابات السيلوليت غائبة من بلوم؛ خصم 15% على المرطبات ولوشن +10 EGP','Bloom Pharmacy — https://www.bloompharmacy.com/collections/urban-ducks (زحف 2026-11-18 23:46 UTC)؛ Zynah — https://zynah.me/collections/shop-by-concern؛ Source Beauty — مقال سكراب القهوة للسيلوليت','2026-11-19','VERIFIED','تشكيلة Urban Ducks على Bloom Pharmacy اليوم 4 منتجات فقط: مرطبا Liquid Silk Body Moisturizer 250مل بـ 255 EGP بدل 300 (−15%)، ولوشن Chocolate Cookies 120مل بـ 180 EGP، وزبدة جسم Strawberry Vanilla Shake 120مل بـ 210 EGP (متاحة). مقارنة باللقطة المسجلة 2026-11-18 (زبدة 210، لوشن 170، سكراب 255، زيت جسم 320): زبدة الجسم ثابتة 210؛ اللوشن +10 EGP؛ وسكرابا القهوة/البرتقال بخطاب السيلوليت وزيت الجسم غائبان تمامًا من تشكيلة بلوم الحالية. الغياب موثّق على بلوم فقط — لم يُتأكد سحب المنتج لأن Zynah لم تُفحص صفحةً صفحةً (صفحتها الأولى من Shop by Concern لا تظهر Urban Ducks). خطاب السيلوليت للقهوة سكراب مؤكد من Source Beauty (مقال 14 نوفمبر 2023). لا منتج جديد ولا روتين ولا عرض موسمي جديد.',1795045685696);
INSERT INTO observations VALUES(17,'الليبوديما واسم «ضياء العوضي» يدخلان لغة بحث السيلوليت','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — كلمات: سيلوليت، علاج السيلوليت','2026-11-19','SEARCH_LANGUAGE','اقتراحات جديدة في مسح 19 نوفمبر 01:51 EET: «سيلوليت و ليبوديما» (التمييز بين السيلوليت والليبوديما دخل لغة البحث) و«علاج السيلوليت ضياء العوضي» (اسم شخص/صانع محتوى ظهر في بحث علاج السيلوليت). إشارة لزاوية محتوى تعليمية: الفرق بين السيلوليت والليبوديما، ومتابعة مين ضياء العوضي وبيقول إيه عن علاج السيلوليت.',1795046088238);
INSERT INTO observations VALUES(18,'نية شرائية: استفسارات سعر «سعر كريم جلد الوزة» و«زبدة الشيا بكام»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — كلمات: كريم جلد الوزة، زبدة الشيا، علاج جلد الوزة','2026-11-19','SEARCH_LANGUAGE','اقتراحات جديدة في مسح 19 نوفمبر 01:51 EET: «سعر كريم جلد الوزة» و«زبدة الشيا بكام» — استفسارات سعر مباشرة على منتجات زيرا الأساسية (كريم/روتين جلد الوزة وزبدة الشيا). نية شرائية صريحة: الباحث بيسأل عن السعر قبل الشراء. كمان «علاج جلد الوزة نهائيا» و«علاج جلد الوزة والشعر تحت الجلد» — نية قوية وزاوية محتوى (جلد الوزة + الشعر تحت الجلد) السكراب بتاع زيرا أصلاً بيغطيها.',1795046088263);
INSERT INTO observations VALUES(19,'براندات منافسة بالاسم في اقتراحات بحث اليوريا: Alejon وMixa وEveline وNovera','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — كلمات: يوريا، كريم يوريا للجسم','2026-11-19','SEARCH_LANGUAGE','اقتراحات جديدة ظهرت في مسح 19 نوفمبر 01:51 EET مقابل لقطة 18 نوفمبر 23:32 UTC: «كريم اليجون يوريا للجسم» (Alejon)، «كريم mixa للجسم يوريا»، «كريم ايفلين للجسم يوريا»، «يوريا لوشن نوفيرا». أسماء منافسين بقت بتظهر جوه اقتراحات جوجل مصر لكلمات اليوريا بتاعت زيرا — المنافسة على كلمة «يوريا» مش بس صيدليات، دي براندات بتتسمّى بالاسم في البحث.',1795046088287);
INSERT INTO observations VALUES(20,'اقتراح بحث جديد: «علاج جلد الوزة في المنزل»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — الكلمة المتتبعة «علاج جلد الوزة» — مسح 2026-11-19 02:12 EET','2026-11-19','SEARCH_LANGUAGE','اقتراح جديد ظهر لأول مرة في مسح 19 نوفمبر 02:12 EET تحت الكلمة المتتبعة «علاج جلد الوزة»، ولم يكن في لقطة 01:51 EET. صيغة «في المنزل» جديدة كلياً في لغة البحث — الباحثون بيدوّروا على علاج منزلي لجلد الوزة، مش عيادة/ليزر. ده مطابق تماماً لتموضع روتين KP بتاع زيرا (روتين منزلي متكامل 799 ج) — يصلح كزاوية محتوى/إعلان: «علاج جلد الوزة في المنزل» كهوك مباشر بلغة الباحث نفسه. ليس منتجاً أو مشكلة جديدة لا تحملها زيرا، فلا فرصة منتج جديدة منه.',1795047348778);
INSERT INTO observations VALUES(21,'صيغ جديدة في بحث كريم اليوريا: «كريم urea للجسم» باللاتينية + متغيرات أرقام/مرادفات','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — الكلمة المتتبعة «كريم يوريا للجسم» — مسح 2026-11-19 02:12 EET','2026-11-19','SEARCH_LANGUAGE','4 صيغ جديدة تحت الكلمة المتتبعة «كريم يوريا للجسم» في مسح 19 نوفمبر 02:12 EET مقابل لقطة 01:51 EET: «كريم urea للجسم» (بحث بحروف لاتينية لكلمة urea — أول ظهور لصيغة لاتينية)، و«كريم يوريا ١٠ للجسم» و«كريم يوريا 20 للجسم» و«احسن كريم يوريا للجسم». تنبيه صدق: التلاتة الأخيرة متغيرات صياغة لنفس النية الموجودة أصلاً («كريم يوريا 10 للجسم»، «كريم يوريا ٢٠ للجسم»، «افضل كريم يوريا للجسم» — أرقام عربية/إنجليزية ومرادف «احسن/افضل») مش طلب جديد. الجديد الحقيقي هو الصيغة اللاتينية «urea» — إشارة إن جزء من الباحثين بيكتب الكلمة بالإنجليزي. كلها ضمن منتج موجود عند زيرا (لوشن يوريا 25%)، فلا فرصة منتج جديدة.',1795047348798);
INSERT INTO observations VALUES(22,'Melano Pharma — عرض Buy 1 Get 1 على Uremel 20% في عروض White Friday (سعر فعّال 175 EGP للوحدة)','Melano Store — https://melanopharma.store/ (الصفحة الرئيسية) + https://melanopharma.store/products/uremel-20 — زحف 2026-11-19 00:30 UTC / 02:30 EET','2026-11-19','VERIFIED','بانر «البيضاء الجمعة عروض SALE 11/11 — لفترة محدودة فقط» على الصفحة الرئيسية، وUremel 20% ظاهر في شبكة العرض بشارة Buy 1 Get 1 بسعر 350 EGP (سعر فعّال 175 EGP للوحدة). في لقطة 2026-11-18 21:32 UTC لم يُرصد أي عرض أو خصم على المنتج نفسه. ملاحظة عدم يقين: صفحة المنتج نفسها لا تذكر B1G1 — التطبيق الفعلي للعرض على Uremel يحتاج تحققًا. السعر الأساسي ثابت 350 EGP، التركيبة نفسها (يوريا 20% + ساليسيليك 2%)، والتقييم 4.9/5 (8 مراجعات). كذلك Uremel 10% ظاهر بـ 220 EGP مع شارة Buy 1 Get 1. لا منتج جديد لجلد الوزة/سيلوليت ولا روتين متكامل.',1795048281127);
INSERT INTO observations VALUES(23,'براندات منافسة تدخل لغة بحث اليوريا: Mixa وEveline في اقتراحات «كريم يوريا للجسم»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — keyword «كريم يوريا للجسم»','2026-11-19','SEARCH','في مسح جوجل مصر 19 نوفمبر 02:30 EET ظهر «كريم mixa للجسم يوريا» و«كريم ايفلين للجسم يوريا» لأول مرة ضمن اقتراحات «كريم يوريا للجسم»، مع صيغ عامة جديدة («كريم ترطيب للجسم يوريا»، «كريم في يوريا للجسم»). باحثون بيدوّروا على كريمات يوريا للجسم بالاسم التجاري (Mixa / Eveline) — إشارة لمنافسة براندات في لغة البحث نفسها، مش بس في الإعلانات. لغة البحث على يوريا 30% («كريم يوريا ٣٠ للجسم») لسه موجودة في القائمة.',1795048393103);
INSERT INTO observations VALUES(24,'اقتراح جديد: «علاج جلد الوزة والشعر تحت الجلد» — ربط علاج KP بالشعر تحت الجلد','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — keyword «علاج جلد الوزة»','2026-11-19','SEARCH','ظهر لأول مرة في مسح جوجل مصر 19 نوفمبر 02:30 EET ضمن اقتراحات «علاج جلد الوزة» (بدل «علاج جلد الوزة في المنزل» اللي خرج من القائمة). الباحثون بيربطوا علاج جلد الوزة بالشعر تحت الجلد — زاوية محتوى محتملة لروتين KP: شرح العلاقة بين التقشير/اليوريا والشعر تحت الجلد.',1795048393121);
INSERT INTO observations VALUES(25,'اقتراح بحث جديد: «علاج جلد الوزة في الوجه»','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — مسح 19 نوفمبر 03:11 EET','2026-11-19','SEARCH-LANGUAGE','اقتراح جديد ظهر لأول مرة في مسح 19 نوفمبر 03:11 EET ضمن «علاج جلد الوزة»، بينما اختفى «علاج جلد الوزة في منطقة البكيني» من القائمة. باقي الكلمات الـ11 بدون تغيير مقابل مسح 02:49 EET.',1795050756134);
INSERT INTO observations VALUES(26,'اقتراح جديد: «زبدة الشيا للبشرة» يظهر في لغة بحث جوجل مصر','Google Egypt autocomplete — مسح لغة البحث 03:49 EET (hl=ar, gl=eg)','2026-11-19','SEARCH_LANGUAGE','اقتراح جديد في مسح جوجل مصر 19 نوفمبر 03:49 EET: «زبدة الشيا للبشرة» ظهر ضمن اقتراحات «زبدة الشيا» بدل «زبدة الشيا الاصلية» اللي خرجت من القايمة — باحثون بيدوّروا على زبدة الشيا لاستخدام البشرة تحديداً. زبدة الشيا مكوّن موجود عند زيرا أصلاً، فده تغيّر في لغة البحث مش منتج جديد ناقص؛ يستاهل متابعة في المحتوى الأورجانيك (زبدة الشيا للبشرة vs للجسم/للشعر).',1795053073518);
INSERT INTO observations VALUES(27,'اقتراح جديد: «زبدة الشيا الاصلية» — باحثون بيدوّروا على زبدة شيا أصلية','Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) — مسح 19 نوفمبر 04:50 EET، كلمة «زبدة الشيا»','2026-11-19','SEARCH','ظهر الاقتراح لأول مرة في مسح 04:50 EET بديلاً عن «زبدة الشيا للبشرة» اللي خرج من القائمة. الإشارة: باحثون بيميزوا بين زبدة شيا أصلية ومغشوشة — قلق أصالة واضح في لغة البحث.',1795056702363);
INSERT INTO observations VALUES(29,'Kyra Naturals — اختفاء كامل من Source Beauty: صفر منتج مدرج (كان 39+ منتجاً في الوصف القديم)','Source Beauty — https://sourcebeauty.com/collections/kyra-naturals — فحص حي 2026-11-19 06:30–06:34 EET + إنستجرام https://www.instagram.com/kyra_naturals/','2026-11-19','VERIFIED','صفحة العلامة على Source Beauty فارغة تماماً («Sorry, there are no products in this collection») وبحث «Kyra» في الكتالوج يعيد 0 منتج؛ البحث داخل الموقع يعيد 10 نتائج كلها مقالات مدونة. دليل الإزالة: وصف الصفحة في نتائج البحث يقول «Shop 39+ products» (قديم)، ورابط منتج قديم «كيرا بيتشى سكراب» أصبح 404. اللقطة المسجلة 2026-11-18 كانت لوشن جوز هند 130مل بـ 110 EGP ولوشنات 110 وشاور جل 85 وباث فيز 100 — كلها غير قابلة للتأكيد اليوم. إنستجرام kyra_naturals ما زال موجوداً (11.1K متابع، «For orders DM») بلا رابط متجر. سبب الإزالة غير معروف من المصادر العامة (انسحاب من المنصة؟ نفاد جماعي؟ إغلاق؟) — يحتاج متابعة الإنستجرام. لا منتج جديد ولا عرض موسمي ولا تموضع KP/سيلوليت من Kyra.',1795063012663);
INSERT INTO financial_snapshots VALUES(1,'Dual Hero — اقتصاديات وحدة محسوبة [EST]','Relaunch — قبل الإطلاق','روتين السيلوليت + روتين جلد الوزة (799 EGP لكل منهما)',0,0,0.0,381.0,0.0,70.0,'محسوب بـ cod_cohort_calc.py: إيراد محصّل 874 ‏(799 + شحن 75) · COGS ‏350 من المالك · افتراضات تشغيلية افتراضية من السكربت: تعبئة 20 / شحن 70 / رسوم مرتجع 50 / COD ‏2% · تسليم صافٍ افتراضي 72%. النتائج: Break-even Placed CPP ‏≈275 EGP · مساهمة قبل الإعلانات ‏≈381 EGP لكل مُسلّم · بوابة Scale ‏(GPT ≥15% AOV) تصمد حتى Placed CPP ‏≈180 · هدف تشغيلي مقترح ≤150–160. ⚠️ رسوم Bosta الفعلية ونسب التأكيد/التسليم الحقيقية غير مؤكدة — الأرقام [EST] لحين تأكيدها.',1795032253687,0.0);
INSERT INTO core_profiles VALUES(1,'Zyra Care','https://zyra-care.com','Egypt','EGP','Egyptian Arabic','','','','روتينات متكاملة لكل مشكلة بشرة/جسم — «مشكلتك ليها روتين» · أكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت)','شحن 75 EGP لكل المحافظات، ومجاني للطلبات من 1000 EGP · الأوردر بيتشحن خلال 3–5 أيام عمل (من الويبسايت)','استبدال واسترجاع خلال 14 يوم من الاستلام (من الويبسايت)','الدفع عند الاستلام + تأكيد الأوردر قبل الشحن وإرسال طريقة الاستخدام بالترتيب (وعود معلنة على الويبسايت)','','نعومة وترطيب من أول أسبوع · تحسّن تدريجي في مظهر السطح مع الانتظام 4–8 أسابيع (صياغات الويبسايت الحذرة: يحسّن الملمس والمظهر)','يعالج/علاج · نهائي · يقضي للأبد · مضمون 100% · تخسيس أو إزالة السيلوليت (الويبسايت نفسه ينفيها) · أي ادعاء طبي','صريح وحذر: بنقولك المتوقع بالظبط وإمتى المنتج مش مناسب ليكي، من غير وعود مبالغ فيها (من صفحة «مين زيرا؟»)',75.0,0.0,2.0,0.0,0.0,'',0.0,3.0,160.0,'GPT<0 ⇒ KILL فوري. للهيرو المزدوج (بافتراضات تشغيلية افتراضية): Placed CPP أعلى من Break-even ‏≈275 EGP يعني خسارة — لا إطلاق.','Scale فقط لو GPT ≥ ‏15% من AOV. للهيرو: تصمد البوابة حتى Placed CPP ‏≈180، والهدف التشغيلي المعتمد ≤150–160 EGP.',1795032253375,0.0,0.0,'','','','','COGS الهيروين = 350 EGP من المالك (مؤكد). لكن: رسوم Bosta الفعلية غير مؤكدة — أرقام Break-even (275) والمساهمة (381/مُسلّم) محسوبة بافتراضات السكربت الافتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD ‏2%) عند تسليم صافٍ 72% افتراضي. نسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية لسه على المالك. COGS باقي المنتجات غير مدخل.');
INSERT INTO products VALUES(1,'روتين البشره الباهته','https://zyra-care.com/products/glow-even-looking-skin',599.0,0.0,'Active','مورينجا، كولاجين','','وشك باين مطفي وتعبان؟ وبتدوّري على «حاجة تنوّر» من غير ما تعرفي هي إيه بالظبط؟ كتير من «البهتان» سببه جفاف وجلد ميت على السطح : البشرة الناشفة سطحها مش مستوي، فبتشتّت الضوء وتبان باهتة، مهما حطيتي. الروتين خطوة بخطوة صابونة المورينجا تنظيف منعش صابونة الكولاجين وبذور العنب تنظيف ناعم تونر الورد والخيار ترطيب وانتعاش ليه بيشتغل؟ صابونة المورينجا لأيام الانتعاش، و صابونة الكولاجين وبذور العنب لأيام النعومة، و تونر الورد والخيار بعدهم يرطّب. البشرة المرطّبة سطحها أملس فبتعكس الضوء أحسن ، وده سر الإحساس بالنضارة. هتكسبي إيه؟ وش منتعش من أول مرة بشرة أنعم ومظهر أحيا مع الاستخدام روتين بسيط الصبح وبالليل روتين كامل بسعر أوفر النتيجة المتوقعة من أول مرة: وش منتعش مع الاستخدام: بشرة أنعم ومظهرها أحيا الروتين ده مش بيفتّح ولا بيشيل بقع ، بيخلي البشرة تبان أكثر انتعاشًا لما الجفاف هو السبب. وواقي الشمس الصبح أهم خطوة لأي وش منوّر. رجّعي النضارة لوش',1795032253088);
INSERT INTO products VALUES(2,'روتين البشرة الدهنية','https://zyra-care.com/products/purifying-blemish-balance',599.0,0.0,'Active','صبار','','وشك بيلمع بعد ساعتين من الغسيل؟ وكل ما تغسلي أكتر، يلمع أسرع وتطلعلك حبوب أكتر؟ دي دايرة مش صدفة: الغسول القوي بيشيل الطبقة الواقية، فالبشرة بتفرز دهون أكتر تعويضًا. فبتغسلي أكتر ← تلمع أسرع ← تغسلي أكتر. الروتين خطوة بخطوة صابونة الصبار والتي تري تنظيف (صباحا) صابونة الفحم والليمون جراس تنظيف (بالليل) تونر الورد والخيار ترطيب وتهدئة ليه بيشتغل؟ الحل تنظيف ألطف + ترطيب على طول : صابونتين، الصبار والتي تري صباحا، و الفحم والليمون جراس بالليل، وبعدهم تونر الورد والخيار بيرجّع الترطيب من غير تقل. هتكسبي إيه؟ وش نضيف ومنتعش من غير شد لمعة أقل خلال اليوم مع الاستخدام صابونة لكل يوم حسب حالة بشرتك روتين كامل بسعر أوفر النتيجة المتوقعة من أول مرة: وش نضيف ومنتعش من غير شد مع الاستخدام: إحساس لمعة أقل خلال اليوم الروتين للتنظيف والعناية، الحبوب الشديدة محتاجة دكتور جلدية . صابونة واحدة بس في كل غسلة. اكسري الدايرة من النهاردة، والدفع عند الاستلام',1795032253110);
INSERT INTO products VALUES(3,'روتين السيلوليت','https://zyra-care.com/products/cellulite-smoothing-routine',799.0,350.0,'Active','ملح سيوة، كافيين، ريتينول، نياسيناميد، كولاجين','','جربتي كريمات سيلوليت كتير وكلها وعدت بحاجات ماحصلتش؟ الكريم لما يتحط على طبقة جلد ميت بيقعد فوقها. وأغلب المنتجات بتوعد بالتخسيس، فتتوقعي حاجة مش هتحصل وتبطّلي. الروتين خطوة بخطوة صابونة الكولاجين وبذور العنب تنضيف الجسم سكراب السيلوليت بالكافيين نجهّز كريم السيلوليت بالريتينول والكافيين نستهدف ليه بيشتغل؟ الروتين بيشتغل على حاجتين بصراحة: سطح أنعم وجلد مرطّب. صابونة الكولاجين وبذور العنب بتنضّف الجسم، و سكراب الكافيين وملح سيوة بيشيل الجلد الميت ويجهّز الجلد، و كريم الريتينول والكافيين والنياسيناميد هو الخطوة الأساسية للملمس والترطيب. هتكسبي إيه؟ ملمس أنعم من أول أسبوع مظهر أكثر تجانس مع الانتظام ٤–٨ أسابيع خطوات واضحة : كل منتج ليه دور أوفر من شراء كل منتج لوحده النتيجة المتوقعة من أول أسبوع: ملمس أنعم وترطيب أحسن بعد ٤–٨ أسابيع: تحسّن تدريجي في مظهر سطح الجلد مع الاستمرار: النتيجة بتتبني بالانتظام الروتين بيحسّن الملمس والمظهر ، مش بيخ',1795032253122);
INSERT INTO products VALUES(4,'Body Splash','https://zyra-care.com/products/zyra-body-splash-mist',240.0,0.0,'Active','','','بترشّي برفان الصبح وبعد ساعة محدش شامّ حاجة؟ أو البرفانات التقيلة بتتعبك في الشغل والجامعة؟ أغلب البادي سبلاش أساسه كحول عالي ، بيطير بسرعة ويسحب رطوبة الجلد معاه، فبتعيدي كل شوية وجلدك ينشف. الحل البادي سبلاش من زيرا فيه زيوت مرطّبة بتساعد الريحة تمسك على الجلد، و نسبة كحول قليلة . ريحة خفيفة للشغل والجامعة والخروجات، و ١٠ روايح تختاري منها. ولو عايزاها تفضل أطول: رشّيه فوق المخمرية من نفس الريحة . هتكسبي إيه؟ ريحة منعشة وواضحة على طول ريحة خفيفة بتفضل لساعات حسب الجلد والجو ١٠ روايح : حلو، فواكه، زهري، دافي، صيفي ثبات أطول فوق المخمرية من نفس الريحة نوتات الروايح كل ريحة ليها طبقات: القمة هي أول إحساس بعد الرش، و القلب بيظهر بعدها، و القاعدة هي اللي بتفضل أطول. ريحة زيرا: جوز هند، فانيليا، حلو، لاكتوني، فواكه، زهري، بودري. كوكونت: جوز هند كريمي ولبني ناعم. دير: مسك أبيض ناعم ونضيف. فانيليا كوست: ريحة دافية وحلوة واستوائية، فانيليا مع جو',1795032253135);
INSERT INTO products VALUES(5,'Creamy Mukhmaria','https://zyra-care.com/products/creamy-mokhmaria',199.0,0.0,'Active','زبدة الشيا','','بتحبي ريحة المخمرية بس بتكرهي إحساسها الدهني التقيل على جلدك؟ المخمرية التقليدية تقيلة ودهنية ، والبرفان لوحده بيطير بسرعة لأن الريحة مش لاقية حاجة تمسك فيها على الجلد الناشف. الحل إحنا عملناها كريمي بزبدة الشيا والزيوت المرطّبة: بتتشرب من غير إحساس دهني، و الترطيب نفسه هو اللي بيثبّت الريحة ، عشان كده بتعيش أطول من السبلاش لوحده. ٨ روايح، و٦ منهم ليهم سبلاش من نفس الريحة. هتكسبي إيه؟ ترطيب وريحة في خطوة واحدة من غير إحساس دهني : بتتشرب ريحة بتفضل أطول من السبلاش لوحده جلد أنعم فعلًا بزبدة الشيا نوتات الروايح الروايح دي نفسها نوتات السبلاش من نفس الاسم، فتقدري تجمّعيهم فوق بعض. القمة هي أول إحساس، و القلب بيظهر بعدها، و القاعدة هي اللي بتفضل أطول. ريحة زيرا: جوز هند، فانيليا، حلو، لاكتوني، فواكه، زهري، بودري. دير: مسك أبيض ناعم ونضيف. فانيليا كوست: ريحة دافية وحلوة واستوائية، فانيليا مع جوز هند. القمة: جوز هند لبني خفيف بلمسة استوائية. ال',1795032253147);
INSERT INTO products VALUES(6,'سكراب ملح سيوة','https://zyra-care.com/products/siwa-salt-body-scrub',390.0,0.0,'Active','ملح سيوة، زبدة الشيا، أرجان، جوجوبا','مش على جلد مجروح أو بعد الشيفنج مباشرة، ومش للوش. اختاري ريحتك من فوق، أو خديه في روتين سيوة مع الشيا والليفة ووفّري.','جسمك باين مطفي وملمسه خشن؟ ونفسك في إحساس السبا من غير ما تخرجي من البيت؟ الجلد الميت لما يتراكم بيخلي الجسم باهت وخشن ، وأي لوشن بيقعد فوقه. وأغلب السكرابات يا بتقشّر وتسيب الجلد ناشف، يا ريحتها بتروح قبل ما تنشّفي. الحل ملح سيوة الصخري ، من أشهر أملاح مصر، بيشيل الطبقة الميتة، و زبدة الشيا مع الأرجان والجوجوبا واللوز بيرطّبوا في نفس الخطوة. والنتيجة: جسم ناعم ومنوّر بعد الشاور، و ريحة بتختاريها على مزاجك. هتكسبي إيه؟ جسم ناعم ومنوّر من أول مرة تقشير وترطيب في خطوة واحدة ٥ روايح : من العود للفراولة هدية حلوة بتتصوّر وبتفرّح النتيجة المتوقعة من أول مرة: جسم ناعم ومنوّر وريحة حلوة مع الاستمرار: ملمس أنعم بشكل ثابت مرة لمرتين في الأسبوع كفاية، التقشير الزيادة بيتعب الجلد مش بينفعه. ⚠️ مش على جلد مجروح أو بعد الشيفنج مباشرة، ومش للوش. اختاري ريحتك من فوق، أو خديه في روتين سيوة مع الشيا والليفة ووفّري.',1795032253162);
INSERT INTO products VALUES(7,'صابونة اللوف للجسم','https://zyra-care.com/products/natural-loofah-body-soap',175.0,0.0,'Active','','للجسم بس. البشرة الحساسة جدًا: مرتين في الأسبوع وبضغط خفيف. اختاري ريحتك من فوق، والدفع عند الاستلام.','عارفة إن جسمك محتاج تقشير، بس بتنسي، أو مش لاقية وقت لسكراب كل أسبوع؟ الجلد الميت لما تسيبيه يتراكم أسابيع وبعدين تقشّري بقوة مرة واحدة، ده أقسى على الجلد وأقل فايدة . السر مش في سكراب أقوى، السر في الانتظام . الحل الليفة الطبيعية جوه الصابونة نفسها ، فالتقشير الخفيف بيحصل لوحده مع كل شاور، من غير خطوة زيادة. الجلد الميت مبيلحقش يتراكم، فجسمك بيفضل أنعم. و ٥ روايح : قهوة، ورد، لافندر، شيا ومسك، شيا وعود. هتكسبي إيه؟ تقشير تلقائي مع كل شاور جسم أنعم من أول مرة ريحة حلوة بتفضل بعد الشاور بتوفّري خطوة : صابونة وليفة في حتة واحدة النتيجة المتوقعة من أول مرة: جسم أنعم وريحة حلوة بعد أسبوع: ملمس أكثر توحيد دي صيانة يومية لطيفة، مش بديل عن السكراب العميق ، بس بتخلّيكي محتاجاه أقل. ⚠️ للجسم بس. البشرة الحساسة جدًا: مرتين في الأسبوع وبضغط خفيف. اختاري ريحتك من فوق، والدفع عند الاستلام.',1795032253174);
INSERT INTO products VALUES(8,'زبدة الشيا الخام المكرره','https://zyra-care.com/products/shea-butter-raw',250.0,0.0,'Active','زبدة الشيا','','كعبك ناشف ومشقق؟ وكوعك وركبتك خشنين مهما حطيتي لوشن؟ أغلب اللوشنات أساسها مية، بتدّي إحساس ترطيب لحظي وبعدين المية بتتبخّر والجلد يرجع زي ما هو. اللي ناقص مش المية، اللي ناقص الطبقة اللي بتمنعها تهرب . الحل زبدة الشيا بتعمل طبقة بتساعد تقلل فقد المية من الجلد، عشان كده هي آخر خطوة في أي روتين: بتقفل على كل اللي قبلها. مكوّن واحد، من غير إضافات. هتكسبي إيه؟ جلد أطرى على طول : حتى الكعب ترطيب بيقفل وما يتبخرش مكوّن واحد : تعرفي إيه اللي على جلدك للجسم وأطراف الشعر كمان النتيجة المتوقعة على طول: الجلد أطرى ومرطّب بعد أسبوع: جفاف أقل وملمس أنعم تقيلة على الوش الدهني وممكن تسد المسام، الأفضل للجسم. ولو عندك حساسية من المكسرات جربي الأول. جربيها على الكعب بالليل بشراب قطن، والدفع عند الاستلام.',1795032253185);
INSERT INTO products VALUES(9,'صابون الوجه الطبيعي','https://zyra-care.com/products/natural-face-soap-bar',175.0,0.0,'Active','أرجان، بانثينول، صبار، مورينجا، كولاجين','','وشك بيشد بعد الغسيل؟ أو بيلمع تاني بعد ساعتين؟ وجربتي غسولات كتير من غير فرق؟ المشكلة غالبًا مش في بشرتك، في الغسول الغلط . الغسول القوي بيشيل الطبقة الواقية، فالناشفة تتعب أكتر والدهنية تفرز دهون أكتر تعويضًا. وغسول واحد لكل الناس عمره ما هيناسب مشكلتك بالذات. الحل عشان كده عملنا ٦ أنواع، كل نوع لبشرة : الفحم والليمون جراس أو الصبار والتي تري للدهنية والحبوب، الأرجان أو لبن الماعز والبانثينول للناشفة والحساسة، و المورينجا أو الكولاجين وبذور العنب للوش المطفي. تنظيف من غير ما يسيب البشرة مشدودة. هتكسبي إيه؟ وش نضيف من غير شد من أول غسلة صابونة مناسبة لمشكلتك مش واحدة للكل بشرة أريح وأكثر توازن مع الاستخدام سعر بسيط : وبتعيش أطول في صحن مصفّى النتيجة المتوقعة من أول مرة: وش نضيف من غير إحساس الشد مع الاستخدام: بشرة مرتاحة أكتر بالنوع المناسب الصابونة خطوة تنظيف، النتيجة الأقوى لما التونر ييجي بعدها على طول . والحبوب الشديدة محتاجة متابعة د',1795032253197);
INSERT INTO products VALUES(10,'روتين البشره الجافه','https://zyra-care.com/products/hydration-comfort',599.0,0.0,'Active','أرجان، بانثينول','','تغسلي وشك وعلى طول تحسي بشد وجفاف؟ وكل الكريمات بتدّي راحة لحظية وترجعي زي ما إنتِ؟ أغلب الصوابين بتشيل أكتر من اللازم من الطبقة الواقية، والترطيب اللي بعدها بساعة بيبقى متأخر ، البشرة فقدت رطوبتها خلاص. الروتين خطوة بخطوة صابونة لبن الماعز والبانثينول تنظيف هادي صابونة الأرجان تنظيف مغذّي تونر الورد والخيار ترطيب وتهدئة ليه بيشتغل؟ الحل غسول ألطف وترطيب في وقته : صابونة لبن الماعز والبانثينول للأيام الحساسة، و صابونة الأرجان للأيام الناشفة، و تونر الورد والخيار بعدها على طول يرجّع الترطيب قبل المرطب. هتكسبي إيه؟ غسيل من غير إحساس الشد من أول مرة بشرة أريح وأنعم مع الاستخدام صابونة لكل يوم حسب حالة بشرتك روتين كامل بسعر أوفر النتيجة المتوقعة من أول مرة: غسيل من غير إحساس الشد مع الاستخدام: بشرة أريح وأنعم الروتين مش علاج للإكزيما أو الحساسية ، ولو بشرتك حساسة جدًا ابدئي بلبن الماعز والتونر بس. ودّعي إحساس الشد من النهاردة، والدفع عند الاس',1795032253208);
INSERT INTO products VALUES(11,'Signature scent routine','https://zyra-care.com/products/signature-scent-ritual',599.0,0.0,'Active','','العطور ممكن تضايق البشرة الحساسة، جربي الأول، ومش على جلد متهيّج أو بعد الشيفنج مباشرة. اختاري ريحتك','ريحتك بتطير بعد ساعة؟ والناس عمرها ما سألتك «حاطة إيه؟» الريحة مش بتمسك على الجلد الناشف ، بتطير. وأي عطر لوحده، مهما كان حلو، هيروح بسرعة لو مفيش تحته قاعدة. الروتين خطوة بخطوة صابونة الليفة تنضيف وتقشير مخمرية كريمي قاعدة الريحة بادي سبلاش الريحة فوقها ليه بيشتغل؟ الروتين ده بيبني الريحة طبقة فوق طبقة : صابونة الليفة بتنضّف وتقشّر فالجلد يتقبّل الترطيب، و المخمرية الكريمي قاعدة بتمسك الريحة، و البادي سبلاش بنفس الريحة فوقها. النتيجة: ريحة أطول ووجود أوضح. هتكسبي إيه؟ ريحة بتفضل أطول من السبلاش لوحده جلد ناعم ومرطّب كمان طقس بعد الشاور بيحسسك إنك مهتمة بنفسك هدية جاهزة لصاحبتك النتيجة المتوقعة على طول: ريحة واضحة وجلد ناعم خلال اليوم: الريحة بتفضل أطول من السبلاش لوحده الثبات بيختلف حسب الجلد والجو، بس الطبقات دايمًا بتطوّل عمر الريحة. ⚠️ العطور ممكن تضايق البشرة الحساسة، جربي الأول، ومش على جلد متهيّج أو بعد الشيفنج مباشرة. اختاري ريحتك',1795032253219);
INSERT INTO products VALUES(12,'كيت الساحل الكامل','https://zyra-care.com/products/complete-beach-kit',1300.0,0.0,'Active','صبار','','حجزتي الساحل؟ شعرك بيطلع من البحر متعقد، وجلدك سخن آخر اليوم، وعايزة تطلعي حلوة في الصور؟ كل مشكلة من دول محتاجة منتج في وقت معين من اليوم، ولو اشتريتيهم متفرقين بتدفعي أكتر وبتنسي نص الحاجات. الروتين خطوة بخطوة سيروم سي شيلد — قبل البحر والبيسين قبل المية خلطة الـ١٣ زيت للشعر قبل الغسيل زيت البرونز جلو اللمعة تونر الورد والخيار انتعاش الوش جل الصبار المركّز آخر اليوم ليه بيشتغل؟ الكيت مترتب على يوم الساحل نفسه : سي شيلد للشعر قبل المية، خلطة الـ١٣ زيت بعد الغسيل، زيت البرونز للّمعة فوق واقي الشمس، و التونر وجل الصبار آخر اليوم للوش والجلد. هتكسبي إيه؟ ٥ منتجات لكل لحظة في يوم الساحل شعر أسهل في التسريح بعد البحر والبيسين لمعة برونزي في الصور أوفر من شراء كل منتج لوحده النتيجة المتوقعة من أول يوم: الشعر بيتسرّح أسهل والوش مرتاح طول الرحلة: إحساس أقل بالخشونة ولمعة في الصور زيت البرونز مش واقي شمس ، لازم واقي منفصل. والكيت مش بديل عن غسيل ',1795032253231);
INSERT INTO products VALUES(13,'روتين سيوه للعنايه الأسبوعيه','https://zyra-care.com/products/siwa-deep-nourishment-routine',700.0,0.0,'Active','ملح سيوة، زبدة الشيا','','روتين سيوة للعناية الأسبوعية 🌿 جسمك محتاج عناية أكتر من مجرد لوشن! لو بشرتك باهتة، ملمسها خشن، أو الكوع والركبة والكعب دايمًا فيهم جفاف، روتين سيوة معمول علشان يدي جسمك عناية متكاملة تجمع بين التنضيف والتقشير والترطيب العميق. مستوحى من طبيعة سيوة، 3 خطوات بسيطة تحوّل يوم العناية الأسبوعي لتجربة سبا في البيت. روتينك في 3 خطوات صابونة الليفة تنظيف وتقشير لطيف لتنضيف الجسم والمساعدة على إزالة خلايا الجلد الميتة وتحسين ملمس البشرة. سكراب ملح سيوة تقشير أسبوعي لتقشير أعمق وإزالة تراكمات الجلد الميت، والمساعدة على استعادة ملمس أنعم وأكثر إشراقًا. زبدة الشيا الخام ترطيب وتغذية لترطيب المناطق الجافة وتنعيم الكوع والركبة والكعب، والمساعدة على الحفاظ على رطوبة البشرة. إيه اللي هتلاحظيه مع الاستخدام؟ ملمس أنعم وبشرة أكثر نعومة وإشراقًا. جفاف أقل في المناطق الخشنة. كوع وركبة وكعب أكثر طراوة. إحساس بالنظافة والانتعاش بعد كل مرة عناية. طريقة الاستخدام ',1795032253242);
INSERT INTO products VALUES(14,'روتين جلد الوزة والفراولة','https://zyra-care.com/products/kp-calm-smooth-routine',799.0,350.0,'Active','ملح سيوة، يوريا ٢٥٪، يوريا، زبدة الشيا','','حبيبات خشنة في دراعك وفخدك؟ ونقط غامقة في رجلك بعد الشيفنج مش راضية تمشي؟ دي اسمها جلد الوزة : جلد ميت متراكم حوالين فتحات الشعر. التقشير لوحده بيحسّن السطح يومين وترجع، و اللوشن لوحده بيقعد فوق التراكم. الحل في الاتنين مع بعض، بالترتيب. الروتين خطوة بخطوة سكراب جلد الوزة نجهّز ونقشر لوشن جلد الوزة — يوريا ٢٥٪ نستهدف زبدة الشيا الخام نرطب ليه بيشتغل؟ سكراب جلد الوزة بملح سيوة بيشيل التراكم، وبعده لوشن اليوريا ٢٥٪ بيليّن الجلد التقيل ويشد المية جوه، و زبدة الشيا هي القفلة الغنية: طبقة بتقفل على الترطيب وبتخلّي الجلد مرتاح وناعم أطول. هتكسبي إيه؟ ملمس أنعم من أول استخدام حبيبات أقل بروزًا ونقط أقل وضوحًا مع الانتظام جلد مرتاح وناعم أطول بفضل القفلة الغنية أوفر من شراء كل منتج لوحده النتيجة المتوقعة من أول استخدام: ملمس أنعم بعد ٣–٤ أسابيع: الحبيبات أقل بروزًا والنقط أقل وضوحًا مع الاستمرار: الانتظام هو اللي بيحافظ على النتيجة جلد الوزة بيتح',1795032253254);
INSERT INTO products VALUES(15,'تونر الورد والخيار المنعش','https://zyra-care.com/products/hydrating-soothing-toner',350.0,0.0,'Active','بانثينول، صبار','بعيد عن العين، وجربيه الأول لو بشرتك حساسة من الورد أو اللافندر. كمّلي بيه روتين وشك، أو خديه في روتين وش كامل ووفّري.','بتغسلي وشك وتحسي إنه بيشد وناشف؟ وفاكرة إن ده معناه إنه نضف؟ الشد بعد الغسيل معناه إن البشرة فقدت رطوبتها، حتى لو حاسة إنها نضيفة. ولو سبتيها كده بتتعب أسرع، والمرطب اللي بعدها مش بيتفرد كويس. الحل التونر ده هو الخطوة اللي بين الصابونة والكريم : ماء الورد والشاي الأخضر واللافندر قاعدة منعشة، و الخيار والصبار بيرطّبوا، و البانثينول والألانتوين بيدعموا راحة البشرة. رشّة بعد الغسيل على طول، والبشرة ترجع مرتاحة في ثواني. هتكسبي إيه؟ إحساس الشد بيقل بعد الغسيل على طول انتعاش فوري : وأحلى في الحر المرطب بيتفرد أحسن بعده خفيف : مناسب للدهنية والناشفة النتيجة المتوقعة على طول: انتعاش وإحساس شد أقل مع الاستخدام: بشرة أريح وأنعم التونر مش علاج للحبوب أو البقع ، شغلته ترجّع الترطيب والراحة بعد الغسيل، وده أساس أي روتين وش. ⚠️ بعيد عن العين، وجربيه الأول لو بشرتك حساسة من الورد أو اللافندر. كمّلي بيه روتين وشك، أو خديه في روتين وش كامل ووفّري.',1795032253265);
INSERT INTO products VALUES(16,'Multi Oil Hair Serum','https://zyra-care.com/products/multi-oil-hair-treatment',399.0,0.0,'Active','أرجان، جوجوبا، مورينجا','','شعرك هايش وأطرافه ناشفة ومقصفة، ومش لاقية وقت تخلطي زيوت في المطبخ؟ الهيشان والأطراف الناشفة سببها شعرة عطشانة للزيوت. وخلطات البيت بتاخد وقت ونسبها مش مضبوطة، فيا بتتقل الشعر يا مش بتفرق. الحل ١٣ زيت ومستخلص في إزازة واحدة : جوز هند وأرجان وجوجوبا وأفوكادو بيليّنوا الشعرة، و خروع ولوز وزيتون بيقللوا الجفاف، و حبة البركة والمورينجا والروزماري مكمّلين الخلطة. حمّام زيت قبل الغسيل، أو نقطتين على الأطراف. هتكسبي إيه؟ شعر أنعم وأسهل في التسريح من أول مرة هيشان أقل ولمعة أحسن مع الانتظام أطراف شكلها أصح وأقل جفاف ١٣ زيت بسعر إزازة واحدة : من غير مطبخ ولا لخبطة النتيجة المتوقعة من أول مرة: شعر أنعم وأسهل في التسريح بعد ٣–٤ أسابيع: هيشان أقل ولمعة أحسن بصراحة: الخلطة بتحسّن الملمس واللمعة ومظهر الأطراف ، مش علاج تساقط ومش بتكثّف الشعر. جربيها كحمّام زيت الأسبوع ده، والدفع عند الاستلام.',1795032253276);
INSERT INTO products VALUES(17,'Pre-Sweeming Hair Serum','https://zyra-care.com/products/sea-shield-hair-serum',420.0,0.0,'Active','أرجان، جوجوبا','','شعرك بيطلع من البحر ناشف ومتعقد، والتسريح بيبقى معركة؟ خصوصًا لو مفرود أو مصبوغ؟ كلنا بنهتم بالشعر بعد البحر، بس الضرر بيحصل وإنتِ في المية . الملح والكلور بيلاقوا الشعرة مكشوفة، والنتيجة خشونة وتعقيد وفلوس الفرد والصبغة رايحة. الحل سي شيلد هو الخطوة المنسية قبل المية : سيليكونات خفيفة بتعمل طبقة ناعمة على الشعرة بتقلل الاحتكاك والتعقيد، و زيت الأرجان والجوجوبا بينعّموا. تحطيه على شعر ناشف قبل ما تنزلي بعشر دقايق. هتكسبي إيه؟ تسريح أسهل بعد البحر والبيسين إحساس أقل بالخشونة والتعقيد عناية بالشعر المفرود والمصبوغ في الصيف خفيف : كمية صغيرة على الأطوال بس النتيجة المتوقعة من أول يوم: الشعر بيطلع من المية أسهل في التسريح على مدار الصيف: إحساس أقل بالخشونة والتعقيد بيساعد في العناية قبل المية، بس مش بيمنع تأثير الملح والكلور بالكامل ، ولازم تغسلي شعرك كويس بعد البحر. ومش ليف-إن يومي. حطيه في شنطة الساحل، أو خديه في كيت الساحل الكامل ووفّري.',1795032253287);
INSERT INTO products VALUES(18,'جل الصبار المركّز','https://zyra-care.com/products/aloe-vera-gel-130ml',120.0,0.0,'Active','صبار','','جلدك سخن ومشدود بعد يوم بحر؟ أو بيحمر ويتضايق بعد الشيفنج؟ في اللحظات دي جلدك محتاج ترطيب خفيف ، مش كريم تقيل يسد المسام ويحسسك بالحر أكتر. الحل خلاصة صبار مركّزة بقوام جل خفيف بيتشرب في ثواني ومش بيسيب أي لمعة دهنية. للوش والجسم، وتقدري تحطيه أكتر من مرة في اليوم. وسر صغير: خليه في التلاجة . هتكسبي إيه؟ إحساس بارد ومريح على طول ترطيب من غير تقل ولا لمعة دهنية للوش والجسم : حتى البشرة الدهنية إضافة ذكية لأي روتين بسعر بسيط النتيجة المتوقعة على طول: إحساس انتعاش وراحة مع الاستخدام: جلد مرطّب من غير تقل ده ترطيب وإحساس بالراحة، مش علاج للحروق . الحرق الحقيقي محتاج دكتور. ضيفيه لأوردرك وخليه في التلاجة، هتشكرينا بعدين.',1795032253300);
INSERT INTO products VALUES(19,'Bronze Glow Tanning Oil','https://zyra-care.com/products/bronze-glow-tanning-oil',390.0,0.0,'Active','أرجان، جوجوبا','','عايزة جلدك يلمع في صور الساحل من غير ما يبان دهني أو تقيل؟ أغلب زيوت التان تقيلة ودبقة وبتبقّع الهدوم، وكتير منها بيشجعك تقعدي في الشمس بالساعات، وده آخر حاجة جلدك محتاجها. الحل زيت البرونز جلو معمول للّمعة مش للتسمير : خلطة أرجان وجوجوبا وسمسم بتنعّم الجلد، ومكونات سيليكونية خفيفة بتخلّي الزيت يتفرد بسلاسة ويدّي لمعة ذهبي برونزي من غير إحساس دبق. تحطيه فوق واقي الشمس، وخلاص. هتكسبي إيه؟ لمعة برونزي فورية بتبان في الصور ملمس حرير مش دهني ولا دبق زيوت بتنعّم الجلد بعد يوم البحر خفيف وبيتشرب : سيبيه ٥ دقايق قبل اللبس النتيجة المتوقعة على طول: لمعة برونزي وملمس حرير طول اليوم: جلد شكله منوّر في الصور مهم: ده زيت لمعة مش واقي شمس ومش بيحمي من الأشعة. حطي الواقي الأول، وجدّديه كل ساعتين. جهّزي شنطة الساحل، أو خديه في كيت الساحل الكامل ووفّري.',1795032253312);
INSERT INTO products VALUES(20,'كريم السيلوليت بالريتينول والكافيين','https://zyra-care.com/products/cellulite-firming-cream',350.0,0.0,'Active','يوريا، كافيين، ريتينول، نياسيناميد، جليسرين','','عارفة الريتينول اللي بيستخدموه في روتين الوش؟ طيب ليه مش في روتين جسمك؟ الجلد الناشف بيخلي مظهر السيلوليت أوضح ، والملمس المتعرّج بيبان أكتر في النور. وأغلب كريمات السيلوليت بتوعد بالتخسيس وتدّيكي في الآخر ترطيب عادي، فتزهقي وتبطّلي. الحل الكريم ده بيشتغل على حاجتين بصراحة: الملمس والترطيب . الريتينول معروف إنه بيحسّن ملمس البشرة ومظهرها مع الوقت، و الكافيين مكوّن شائع في منتجات العناية بمظهر السيلوليت، و النياسيناميد بيدعم طبقة الحماية، و اليوريا والجليسرين والشيا بيرطّبوا. دقيقتين بالليل، ودي كل الحكاية. هتكسبي إيه؟ ترطيب أحسن من أول أسبوع ملمس أنعم ومظهر أكثر تجانس مع الانتظام روتين ليلي دقيقتين سهل تلتزمي بيه تركيبة صريحة من غير وعود تخسيس النتيجة المتوقعة من أول أسبوع: ترطيب أحسن وملمس أنعم بعد ٤–٨ أسابيع: تحسّن تدريجي في مظهر سطح الجلد مع الاستمرار: النتيجة بتتبني بالانتظام وبتقل لو وقفتي الكريم بيحسّن الملمس والمظهر، مش بيخسّس ومش ',1795032253323);
INSERT INTO products VALUES(21,'سكراب السيلوليت بالكافيين','https://zyra-care.com/products/cellulite-body-scrub',450.0,0.0,'Active','ملح سيوة، كافيين، زيت بذور العنب','','بتبصي على فخدك في النور وتلاقي الملمس متعرّج؟ وبتتكسفي من المايوه أو الفستان القصير؟ السيلوليت طبيعي وعند أغلب الستات ، حتى الرفيعة. بس الجلد الناشف والطبقة الميتة بيخلّوا مظهره أوضح في الإضاءة، وأي كريم بتحطيه على طبقة ميتة بيقعد فوقها ومش بيوصل. الحل السكراب ده هو خطوة التجهيز . ملح سيوة بيشيل الجلد الميت، و الكافيين مكوّن مستخدم في منتجات العناية بمظهر السيلوليت، ومعاهم زبدة الكاكاو والشيا وزيت بذور العنب واللوز بيسيبوا الجلد ناعم بعد الشطف. تدليك دقيقة من تحت لفوق بيديكي إحساس انتعاش ويجهّز الجلد للكريم. هتكسبي إيه؟ سطح جلد أنعم في الفخد والأرداف من أول مرة جلد مستعد للكريم فالكريم يشتغل أحسن إحساس انتعاش وريحة كاكاو دافية في الشاور ترطيب بعد الشطف مش جلد ناشف النتيجة المتوقعة من أول مرة: ملمس أنعم وإحساس انتعاش بعد ٤ أسابيع مع الكريم: سطح الجلد شكله أنعم وأكثر تجانس مع الاستمرار: النتيجة بتتبني بالانتظام مش هنقولك إنه هيشيل السيلوليت',1795032253335);
INSERT INTO products VALUES(22,'لوشن جلد الوزة — يوريا ٢٥٪','https://zyra-care.com/products/kp-urea-lotion',360.0,0.0,'Active','يوريا، زبدة شيا، لاكتيك أسيد، بانثينول','للجسم بس، مش للوش.','جربتي لوشنات كتير والجلد لسه خشن؟ والكوع والركبة والكعب ناشفين مهما حطيتي؟ السبب إن المرطب العادي بيرطّب السطح بس . لكن الجلد الخشن والتقيل وجلد الوزة مشكلتهم في طبقة متراكمة المية مش بتعدّيها، فبتحطي كريم كل يوم وبعد ساعتين ترجعي زي ما كنتي. الحل يوريا بتركيز ٢٥٪ بتليّن الطبقة التقيلة نفسها وبتشد المية جوه الجلد، و لاكتيك أسيد بيقشّر بنعومة من غير فرك. ومعاهم بانثينول وزبدة شيا عشان الجلد يفضل مرتاح. اللوشن ده معمول للجلد اللي المرطب العادي ما قدرش عليه. هتكسبي إيه؟ جلد أطرى من أول أسبوع : حتى الكوع والكعب الحبيبات أقل بروزًا مع الاستخدام المنتظم ترطيب بيفضل مش بيروح بعد ساعتين تقشير ناعم من غير فرك بفضل اللاكتيك أسيد النتيجة المتوقعة من أول أسبوع: الملمس أطرى والجفاف أقل بوضوح بعد ٤ أسابيع: الحبيبات أقل بروزًا والكوع والركبة أنعم مع الاستمرار: نعومة ثابتة طول ما إنتِ منتظمة ابدئي ٣ مرات في الأسبوع وزوّدي بالتدريج. ⚠️ للجسم بس، مش للوش. ',1795032253347);
INSERT INTO products VALUES(23,'سكراب جلد الوزة','https://zyra-care.com/products/kp-body-scrub',440.0,0.0,'Active','ملح سيوة، يوريا، زبدة المانجو، جوجوبا','','بتلبسي كم طويل في عز الصيف عشان الحبيبات الصغيرة الخشنة اللي في دراعك؟ ولما تحطي إيدك عليها تحسيها زي الرملة؟ ده جلد الوزة : جلد ميت بيتراكم حوالين فتحات الشعر ويقفلها، ومالوش علاقة بالحساسية. واللوشن العادي بيقعد فوق الطبقة دي ومش بيوصل لها، والسكراب العادي بيشيلها بقسوة ويسيب الجلد مشدود وناشف، فترجع أسرع. الحل السكراب ده معمول للمشكلة دي بالذات: ملح سيوة متطحون ناعم بيفك التراكم بتدليك خفيف من غير ما يجرح، وفي نفس الخطوة زبدة المانجو والشيا مع زيت الجوجوبا وجوز الهند بيعوّضوا الرطوبة على طول. يعني تقشير وترطيب في خطوة واحدة، والجلد يطلع ناعم مش مشدود. هتكسبي إيه؟ ملمس ناعم تحسّيه بإيدك : من أول مرة في الشاور تقشير من غير جرح ولا شد : الملح ناعم ومخلوط بزبدات بيقلل الشعر اللي تحت الجلد والنقط الغامقة بعد الشيفنج مع الانتظام بيجهّز الجلد للوشن اليوريا فيشتغل أحسن بكتير النتيجة المتوقعة من أول استخدام: ملمس أنعم واضح عند اللمس بعد ٣–٤ أسا',1795032253358);
INSERT INTO market_rounds VALUES(1,'موقع البراند zyra-care.com','قراءة الكتالوج الكامل + السياسات (شحن/استرجاع/دفع عند الاستلام)','تمت قراءة 23 منتج بأسعارها الحالية من لقطة الويبسايت الموثقة — روتينات 599–1300 EGP ومنتجات مفردة 120–450 EGP. الشحن 75 EGP ومجاني من 1000 EGP، استرجاع 14 يوم، شحن خلال 3–5 أيام عمل.','2026-11-18',1795032253389);
INSERT INTO market_rounds VALUES(2,'Cairo Drop — صفحة منتج Urepar','مسح دوري لمنافس واحد: Hayah — Urepar (يوريا 10% لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Hayah — Urepar Cream 10% Urea 200ml ما زال بـ 439 EGP ومتاح (InStock) على Cairo Drop — السعر بدون تغيير عن اللقطة المسجلة. الصفحة تظهر إشارات طلب نشط: «8 sold in last 18 hours» و«21 people viewing». التركيبة: يوريا 10% + شيا + زيت صويا + جلسرين، لجلد الوزة والخشونة. الفجوة لصالح ZYRA ثابتة: يوريا 25% بسعر 360 EGP للوشن مقابل 10% بـ 439 EGP. لم يُرصد عرض جديد أو تغيير سعر. مصدر السعر: صفحة Cairo Drop (آخر زحف 2026-11-12). لم تظهر نتائج مباشرة لـ Urepar في بحث الويب العام — الاعتماد على صفحة المتجر المسجلة.','2026-11-18',1795035021863);
INSERT INTO market_rounds VALUES(3,'Pharma Image — صفحة منتج Skinova Image Urea Lotion Plus','مسح دوري لمنافس واحد: Skinova Image (يوريا 20% لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Skinova Image — Urea Lotion Plus 20% ما زال بـ 199 EGP ومتاح (InStock) على Pharma Image — السعر بدون تغيير عن اللقطة المسجلة. التركيبة: يوريا 20% + لاكتيك أسيد + سيراميد + نياسيناميد + شيا، لجلد الوزة والخشونة (Keratosis Pilaris). الفجوة لصالح ZYRA ثابتة: يوريا 25% بسعر 360 EGP للوشن مقابل 20% بـ 199 EGP — Skinova يبقى أرخص منافس يوريا عالي التركيز وضغط سعري على فئة جلد الوزة. لم يُرصد عرض جديد أو تغيير سعر. مصدر السعر: صفحة Pharma Image (زحف 2026-11-18 21:21 UTC).','2026-11-18',1795036899492);
INSERT INTO market_rounds VALUES(4,'Meta Ads Library','مصر — إعلانات نشطة فقط. بحث بصفحات المنافسين (Tetavara, Mazora, Alejon, Soralone, Kolagra, Centevia, Nefertari, Era Care) + بحث بكلمات عربية: «جلد الوزة» (~520 نتيجة)، «كريم يوريا» (~270 نتيجة)، «سيلوليت». الجلب عبر متصفح المالك بتاريخ 2026-11-18.',replace('نتائج عصر مكتبة إعلانات ميتا — 2026-11-18:\n\n1) اكتشاف كبير: Hepta Skin — هيبتا (ehepta.com) — منافس مباشر جديد لم يكن مُتتبَّعًا. مهيمن على «جلد الوزة» و«كريم يوريا»، منتج البطل Carbamide Twenty (يوريا 20%)، إعلانات فيديو بهوكات أطباء شغالة من ديسمبر 2025 (~335–345 يوم) — أطول عمر إعلاني في الفئة. هو المنافس الإعلاني رقم 1 لروتين جلد الوزة.\n\n2) Alejon: ~84 إعلان نشط — White Friday: Buy 2 Get 2 + هدية سرية + شحن مجاني فوق 1,000. أقدم إعلانات من 19 أغسطس 2026 (91 يوم). فيديو جلد وزة مباشر من 4 نوفمبر 2026 بهوك «حل جلد الوزه واثار جلد الوزه قبل اي حاجه هو الاستمرار».\n\n3) Soralone: ~56 إعلان نشط، كلها بدأت 3–18 نوفمبر 2026 (دفعة Black Friday جديدة، لا شيء عمره 30+ يوم في الصفحة الأولى). عرض: 50% عند شراء 3 منتجات + شحن مجاني فوق 1,500.\n\n4) Centevia: ~7 إعلانات — فيديو جلد وزة من 15 أكتوبر 2026 (34 يوم، Send message) + عرض Black Friday: Buy 2 Get 2.\n\n5) Mazora: ~10 إعلانات لكنها مكملات تخسيس فقط — كريم السيلوليت مش مُعلَن. أقدمها 23 سبتمبر 2026 (56 يوم).\n\n6) صفر إعلانات نشطة: Tetavara (رغم عرض Pink Friday على موقعه)، Era Care (الصفحة الرئيسية)، Kolagra، Nefertari.\n\n7) فرصة: كلمة «سيلوليت» كلها عيادات وأجهزة (Hollywood Clinic Emtone من يناير 2025، ~682 يوم) — لا روتين منزلي DTC بيعلن عليها. ممر مفتوح لروتين السيلوليت من زيرا.','\n',char(10)),'2026-11-18',1795037012026);
INSERT INTO market_rounds VALUES(5,'TikTok Creative Center — Top Ads','TikTok Top Ads — منطقة مصر. بحث بـ8 براندات منافسة (Tetavara، Mazora، Alejon، Era Care، Soralone، Kolagra، Centevia، Nefertari) + 3 كلمات مفتاحية («جلد الوزة»، «سيلوليت»، «كريم يوريا»)، لنافذتي آخر 30 يومًا وآخر 180 يومًا. العرض المجاني: أول 4 نتائج لكل بحث فقط.',replace('منهجية: بحث في TikTok Creative Center — Top Ads (منطقة مصر) عبر متصفح المالك المسجّل، لنافذتين: آخر 30 يومًا وآخر 180 يومًا. العرض المجاني يُظهر أول 4 نتائج فقط لكل بحث قبل جدار «Log in to access all Top Ads» — لم يتم الضغط على تسجيل دخول الأعمال الإضافي. Top Ads عرض مُنتقى لأفضل الإعلانات أداءً وليس مكتبة إعلانات كاملة: غياب براند يعني أنه لم تظهر له إعلانات ضمن الأعلى تصنيفًا، وليس إثباتًا أنه لا يعلن على TikTok.\n\nآخر 30 يومًا: صفر إعلانات مطابقة لكل من Tetavara وMazora وAlejon وEra Care وSoralone وKolagra وCentevia وNefertari، وللكلمات «جلد الوزة» و«سيلوليت» و«كريم يوريا».\n\nآخر 180 يومًا: Tetavara وMazora وAlejon وSoralone وCentevia وNefertari ما زالوا صفرًا؛ و«سيلوليت» صفر في النافذتين.\n\nKolagra: أربع إعلانات فيديو للعناية بالبشرة في 180 يومًا (اسم البراند ظاهر على صور المنتجات) — الأقوى أنبوب «KOLAGRA 50+»: ‏2K إعجاب، CTR ضمن أعلى 28%، ميزانية عالية؛ أنبوب أخضر: ‏1K إعجاب، CTR ضمن أعلى 49%، ميزانية عالية؛ وإعلانان أضعف (54 و51 إعجابًا). Kolagra هو المنافس المتتبَّع الوحيد الذي ظهرت له إعلانات في TikTok Top Ads.\n\n«جلد الوزة» (180 يومًا): أربع إعلانات فيديو للعناية بالجسم — الأقوى براند غير مُعرَّف بعبوة بيضاء بمضخة (الاسم غير مقروء في الصورة المصغرة): ‏12K إعجاب، CTR أعلى 25%، ميزانية عالية، هدف Traffic؛ علبة Glow and Glory ‏(@GlowandGlory): ‏9K إعجاب، CTR أعلى 13%، ميزانية عالية؛ فيديو أنبوب أخضر مزرق بأسلوب صانع محتوى (6 إعجابات)؛ فيديو عناية بالجسم «الدلكة» (796 إعجابًا، CTR أعلى 33%).\n\n«كريم يوريا» (180 يومًا): معظم النتائج غير ذات صلة؛ إعلان واحد لعبوة عناية بالبشرة (نفس العبوة البيضاء بالمضخة): ‏9K إعجاب، CTR أعلى 22%، ميزانية عالية.','\n',char(10)),'2026-11-18',1795037151118);
INSERT INTO market_rounds VALUES(6,'Melano Store — صفحة منتج Uremel','مسح دوري لمنافس واحد: Melano Pharma — Uremel (يوريا 20% لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Melano Pharma — Uremel Cream 20% ما زال بـ 350 EGP ومتاح للشراء على Melano Store — السعر بدون تغيير عن اللقطة المسجلة. التركيبة: يوريا 20% + ساليسيليك أسيد 2%، لجلد الوزة (Keratosis Pilaris) والكعب المتشقق والصدفية والإكزيما. التقييم: 4.9/5 (8 مراجعات). الشحن 3–7 أيام عمل لكل المحافظات، وشحن مخفّض للطلبات من 999 EGP؛ استرجاع/استبدال خلال 7 أيام. لم يُرصد عرض جديد أو خصم على المنتج نفسه. الفجوة لصالح ZYRA ثابتة لكنها ضيقة: يوريا 25% بسعر 360 EGP للوشن مقابل 20% بـ 350 EGP — فرق 10 EGP فقط مقابل +5% تركيز، ما يجعل Uremel أقرب منافس سعري للوشن جلد الوزة. مصدر السعر: صفحة Melano Store (زحف 2026-11-18 21:32 UTC).','2026-11-18',1795037551116);
INSERT INTO market_rounds VALUES(7,'Jumia Egypt + Talabat + Vezeeta Pharmacy + Chefaa — بحث عام 2026-11-18','مسح دوري لمنافس واحد: Bobana (سكرابات جسم 300 جم) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Bobana — سكرابات الجسم 300 جم ما زالت في الشريحة الاقتصادية 35–50 EGP ومتاحة (InStock) على جوميا والصيدليات — الأسعار بدون تغيير جوهري عن اللقطة المسجلة. على جوميا (لقطات زحف حديثة): Honey & Collagen Scrub ‏~49–50 EGP (بدل 70)، Apricot Scrub ‏~49–50 EGP (بدل 70)، Coffee Scrub ‏~48–50، Gold/Charcoal ‏~49.49–49.99، وأملاح السبا (Berries/Yogurt/Milk/Lemon) ‏35–44 EGP. أحدث الأسعار: Talabat (زحف قبل ساعات) — Milk Salt 300g بـ 35.99–45 EGP حسب الصيدلية؛ Vezeeta Pharmacy — Charcoal Scrub 300g بـ 45 EGP؛ Chefaa — Apricot بـ 68 EGP. لم يُرصد عرض جديد أو خصم موسمي (Black Friday) خاص ببوبانا، ولا تموضع جديد لجلد الوزة/السيلوليت — باستثناء مقال ترويجي (3 نوفمبر 2026) يربط Berries Salt Scrub بتقليل مظهر السيلوليت. التقييم: بوبانا يبقى منافس سعر/حجم جماهيري فقط — سكراب بـ ~50 EGP مقابل سكرابات زيرا ضمن روتينات 799 EGP؛ الفجوة لصالح ZYRA ثابتة (روتين متكامل + مواد فعالة مقابل سكراب منفرد اقتصادي)، ولا ضغط سعري جديد على الهيروين.','2026-11-18',1795038057306);
INSERT INTO market_rounds VALUES(8,'بحث عام 2026-11-18 — Talabat + Amazon.eg + Jumia Egypt + Rosheta + مقال صيدليات (shefaa2021.com)','مسح دوري لمنافس واحد: Eva Cosmetics — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Eva Cosmetics (إيفا فارما) — من أكبر مصنّعي مستحضرات التجميل في مصر، توزيع صيدليات واسع وشريحة سعرية جماهيرية. المنتج الوحيد المتموضع للسيلوليت: Eva Smooth Skin Slimming Cream — مذكور في مقال صيدليات (نوفمبر 2024) كتركيبة مصرية «تحسّن مظهر الجلد وتقلل من السيلوليت»، لكن لم يظهر له أي سعر أو قائمة بيع حالية في بحث اليوم (لا جوميا ولا أمازون ولا طلبات) — يبدو منتجاً قديماً/محدود التوزيع، ولا يمكن تأكيد سعره أو توفره الحالي. لم يُرصد أي منتج يوريا أو منتج متموضع لجلد الوزة من إيفا. النطاق الحالي الموثّق اليوم: كريمات كلاسيكية 9–70 EGP (جلسرين 20 جم 16–20 EGP، عسل ~27 EGP، سوفت بالصبار 11–50 EGP، كريم وجه 45 جم 35 EGP)، مقشر جسم Natural Glow 250 جم بـ 120 EGP (متاح على طلبات)، كريم كعب 60 مل 57–73 EGP، وسيرومات Skin Clinic حتى ~297 EGP (فيتامين A 30 مل). لم يُرصد عرض جديد أو خصم موسمي (Black Friday) خاص بإيفا. التقييم: إيفا يبقى منافس سعر/حجم جماهيري فقط — كريم منفرد رخيص مقابل روتينات زيرا المتكاملة 799 EGP؛ لا منافس مباشر في KP/اليوريا، ومنتج السيلوليت بلا سعر حي، فلا ضغط سعري جديد على الهيروين والفجوة لصالح ZYRA ثابتة (روتين متكامل + مواد فعالة مقابل كريم/سكراب منفرد اقتصادي).','2026-11-18',1795038681749);
INSERT INTO market_rounds VALUES(9,'بحث عام 2026-11-18 — eracare-eg.com (صفحة الفروع) + بحث ويب','مسح دوري لمنافس واحد: Era Care — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Era Care (ايرا كير) — اتضح أنها سلسلة متاجر تجزئة للعناية والتجميل بفروع فعلية (المعادي شارع 9، المقطم، سيتي ستارز مدينة نصر، فيصل التعاون، ألف مسكن، الزمالك)، مواعيد يومية 10ص–8م (الأحد 11ص–7م)، وليست براند DTC بمنتج خاص. لم يظهر لها أي منتج متموضع لجلد الوزة أو السيلوليت أو اليوريا في بحث اليوم (بحث ويب عام + صفحة فروع الموقع eracare-eg.com)، ولا قائمة أسعار أونلاين على صفحة الفروع، ولا عرض موسمي/خصم موثق. يتوافق مع اللقطة المسجلة: صفر إعلانات نشطة في Meta Ads Library وصفر في TikTok Top Ads (آخر 30 و180 يومًا). التقييم: إيرا كير منافس تجزئة أوفلاين متعدد البراندات فقط — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينان متكاملان 799 EGP مقابل تجزئة عامة بلا منتج KP/سيلوليت خاص).','2026-11-18',1795039264360);
INSERT INTO market_rounds VALUES(10,'clementineorganics.com — الصفحة الرئيسية + صفحة منتج Holiday Skin (زحف 2026-11-18 22:30 UTC)','مسح دوري لمنافس واحد: Clementine Organics — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Clementine Organics — لا تغيير جوهري عن اللقطة المسجلة. المتجر وجه فقط (Shop By Skin Concern: جفاف/تصبغات/بهتان/شفاه متشققة) ولا يوجد أي خط جسم أو منتج متموضع لجلد الوزة أو السيلوليت أو اليوريا. السعر ثابت: Holiday Skin Niacinamide Serum 40ml بـ 560 EGP (نفس الشريحة المسجلة 470–560 EGP). التوفر: نفاد شبه كامل مستمر — Holiday Skin وGlow Jelly وCaffeine Dream (كريم عين ريتينول) وMoon Milk 2.0 كلها Sold out على الصفحة الرئيسية وصفحة المنتج. لم يُرصد عرض جديد أو خصم موسمي على الصفحة الرئيسية. التقييم: يبقى توأم نموذج (DTC حسب المشكلة + مواد فعالة) للوجه فقط — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينا جسم متكاملان 799 EGP مقابل وجه فقط ونفاد مخزون).','2026-11-19',1795041039082);
INSERT INTO market_rounds VALUES(11,'بحث عام 2026-11-19 — joviality-eg.com (مدونة البراند) + Mai Pharmacy + Talabat','مسح دوري لمنافس واحد: Joviality — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Joviality (جوفياليتي) — براند مصري للجمال الطبيعي (10 سنوات في السوق، يقدّم نفسه كأول براند جمال طبيعي في مصر)، عناية بالبشرة والشعر والجسم. لا يوجد أي منتج متموضع لجلد الوزة أو السيلوليت أو اليوريا في بحث اليوم: خط الجسم هو لوشنات وميستات لامعة وبلسم للجسم وبلسم مضاد للاحتكاك ومزيل عرق — التموضع كله على اللمعان/الرائحة/الطبيعي، وليس على مشكلة جلدية. الأسعار (Mai Pharmacy، خصم ~15%): لوشن الجسم 240 مل 340→289 EGP، Skin Rescue Body Balm ‏30 جم 360→306 EGP، Anti-Chafe Balm ‏30 جم 320→272 EGP، Shimmer Body Mist ‏150 مل 320→272 EGP، مزيل عرق 290→246.50 EGP؛ وعلى طلبات: Tropical Glow Body Lotion SPF15 ‏120 مل بـ 320 EGP لكن المخزون 0 في فرع طلبات مارت المفحوص. عرض موسمي: Green Friday مذكور على مدونة البراند. التقييم: جوفياليتي منافس جمال طبيعي/لمعان فقط — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينا جسم علاجيان متكاملان 799 EGP مقابل لوشنات/ميستات تجميلية منفردة).','2026-11-19',1795043447935);
INSERT INTO market_rounds VALUES(12,'Bloom Pharmacy + Zynah + Source Beauty — بحث عام 2026-11-19','مسح دوري لمنافس واحد: Urban Ducks — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Urban Ducks — براند مصري طبيعي 100% يبيع عبر ماركت بليس/صيدليات (بلوم فارمسي + Zynah)، بلا متجر خاص. على Bloom Pharmacy اليوم (4 منتجات فقط): مرطبا Liquid Silk Body Moisturizer 250مل بـ 255 EGP بدل 300 (−15%)، ولوشن Chocolate Cookies All Natural 120مل بـ 180 EGP، وزبدة جسم Strawberry Vanilla Shake 120مل بـ 210 EGP (متاحة). مقارنة باللقطة المسجلة (2026-11-18: زبدة 210، لوشن 170، سكراب 255، زيت جسم 320): زبدة الجسم ثابتة 210 EGP؛ اللوشن 170→180 EGP (+10، نفس الفئة — المتغير/الرائحة غير مؤكدة كمطابق تمامًا)؛ وسكرابا القهوة/البرتقال بخطاب السيلوليت (255 EGP) وزيت الجسم (320 EGP) غير موجودين إطلاقًا في تشكيلة بلوم الحالية (4 منتجات فقط) — غياب موثّق على بلوم فقط، وليس تأكيدًا لسحب المنتج (لم تُفحص Zynah صفحةً صفحةً؛ صفحتها الأولى من «Shop by Concern» لا تظهر Urban Ducks). خطاب السيلوليت للقهوة سكراب مؤكد من مصدر قديم (Source Beauty، مقال 14 نوفمبر 2023: «minimizes cellulite… Say goodbye to the appearance of cellulite»). لم يُرصد عرض موسمي جديد أو منتج جديد أو روتين متكامل. التقييم: Urban Ducks يبقى منافس عناية طبيعية منفردة رخيصة (170–255 EGP) بلا روتينات وبلا مواد فعالة — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينا جسم علاجيان متكاملان 799 EGP مقابل لوشنات/زبدات تجميلية منفردة)؛ غياب سكرابات السيلوليت من بلوم — إن تأكد — يضعف أصلًا أقرب ادعاء سيلوليت صريح لديه.','2026-11-19',1795045670078);
INSERT INTO market_rounds VALUES(13,'Chefaa + Noon + Cairo Drop (نطاق منتهٍ) — بحث عام 2026-11-19','مسح دوري لمنافس واحد: Hayah — Urepar (يوريا 10% لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Hayah — Urepar Cream 10% Urea 200ml — تغيير مهم في المصدر والسعر. أولاً: Cairo Drop — مصدر اللقطة المسجلة — لم يعد متاحًا: النطاق cairodrop.com منتهٍ وموقوف (صفحة GoDaddy «has expired and is parked free»)، فلا يمكن تأكيد السعر السابق 439 EGP من المصدر الأصلي. ثانيًا: شفاء (chefaa.com) — السعر الحالي 357 EGP، متوفر (In stock، زر إضافة للعربة مفعّل، توصيل 30–60 دقيقة عبر أقرب صيدلية) — أي أقل بـ 82 EGP من اللقطة المسجلة على Cairo Drop (439 EGP)، مع ملاحظة أن نص وصف المنتج على الصفحة يذكر نحو 269 EGP لكن حقل السعر المعروض هو 357 EGP وهو المعتمد. لا خصم على المنتج نفسه؛ عرض عام فقط: خصم إضافي 10% على أول طلب بكوبون CHJ10 لفترة محدودة. ثالثًا: نون — 416.22 EGP، متوفر بكميات محدودة («Only 3 left in stock»، البائع Elmasry Pharmacy، توصيل متوقع حتى 25 نوفمبر)، بلا خصم سعري ظاهر، مع تقسيط valu بـ 6 أقساط × 69.37 EGP. رابعًا: Amazon.eg (ASIN B08WJJNFT7) لم تُفتح — رسالة خطأ في المعالجة، فلم يُتحقق من سعرها. التقييم: Urepar ما زال كريم يوريا 10% منفردًا بلا روتين وبلا تموضع سيلوليت؛ الفجوة لصالح ZYRA ثابتة (لوشن يوريا 25% بسعر 360 EGP ضمن روتين 799 EGP مقابل كريم 10% بـ 357–416 EGP)، لكن انخفاض سعره على شفاء إلى 357 EGP يضيّق الفارق السعري مع لوشن زيرا المنفرد (360 EGP) إلى 3 EGP فقط — ضغط سعري يستحق المتابعة في الجولات القادمة، خصوصًا مع اختفاء مصدر Cairo Drop. لا عرض موسمي جديد أو منتج جديد أو روتين متكامل رُصد.','2026-11-19',1795046773657);
INSERT INTO market_rounds VALUES(14,'Pharma Image — صفحة منتج Skinova Image 20% Urea Cream Plus','مسح دوري لمنافس واحد: Skinova Image (يوريا 20% لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Skinova Image — تغيير سعري وعرضي موثّق على Pharma Image. المنتج المميز «Top of the week» على الصفحة الرئيسية هو Skinova Image 20% Urea Cream Plus بسعر LE 190.00 (مشطوب LE 410.00 — خصم معروض ~54%) ومتاح (InStock). اللقطة المسجلة 2026-11-18 كانت 199 EGP تحت اسم «Urea Lotion Plus 20%» — أي انخفاض 9 EGP في السعر المعروض، مع ظهور تأطير خصم جديد (190 مقابل 410) لم يكن موثقًا في اللقطة السابقة. ملاحظة عدم يقين: اسم المنتج على الصفحة الحالية «Cream Plus» مقابل «Lotion Plus» في اللقطة السابقة، وقائمة المكونات المعروضة الآن (يوريا 20% + زبدة شيا + ساليسيليك أسيد) أضيق من وصف اللقطة السابقة (يوريا 20% + لاكتيك أسيد + سيراميد + نياسيناميد + شيا) — لم يُعثر على صفحة لوشن منفصلة لـ Skinova على Pharma Image في بحث اليوم، والمرجّح أنه نفس المنتج بتسمية/عرض محدّث، لكن لم يُثبت تغيير الاسم رسميًا. لا منتج جديد ولا روتين متكامل رُصد. التقييم: Skinova يبقى أرخص منافس يوريا عالي التركيز — 190 EGP مقابل لوشن زيرا المنفرد 360 EGP — والفجوة السعرية اتسعت قليلًا لصالحه (170 EGP بدل 161 EGP)، ومع تأطير الخصم الجديد (410→190) يزداد الضغط السعري على فئة جلد الوزة؛ الفجوة لصالح ZYRA ما زالت ثابتة على مستوى القيمة (يوريا 25% ضمن روتين متكامل 799 EGP مقابل كريم منفرد 20%). مصدر السعر: صفحة منتج Pharma Image (زحف 2026-11-19 00:21 UTC / 02:21 EET).','2026-11-19',1795047755268);
INSERT INTO market_rounds VALUES(15,'Melano Store — صفحة منتج Uremel + الصفحة الرئيسية (زحف 2026-11-19 00:30 UTC)','مسح دوري لمنافس واحد: Melano Pharma — Uremel (يوريا 20% لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Melano Pharma — Uremel Cream 20% — تغيير عرضي موثّق. السعر ثابت: 350 EGP ومتاح على صفحة المنتج (melanopharma.store/products/uremel-20)، التركيبة نفسها (يوريا 20% + ساليسيليك أسيد 2%، لجلد الوزة والكعب المتشقق)، التقييم 4.9/5 (8 مراجعات)، شحن 3–7 أيام عمل وشحن مخفّض من 999 EGP واسترجاع 7 أيام. الجديد: الصفحة الرئيسية للمتجر (زحف 2026-11-19 00:30 UTC / 02:30 EET) تعرض بانر «البيضاء الجمعة عروض SALE 11/11 — لفترة محدودة فقط — مجموعات متكاملة بأسعار خاصة حتى نفاد الكمية»، وUremel 20% ظاهر في شبكة العرض بشارة Buy 1 Get 1 بسعر 350 EGP — أي سعر فعّال 175 EGP للوحدة لو طُبّق العرض، مقابل 350 EGP في لقطة 2026-11-18 التي لم ترصد أي عرض على المنتج نفسه. ملاحظة عدم يقين: صفحة المنتج نفسها لا تذكر B1G1، فالتأكيد النهائي لتطبيق العرض على Uremel يحتاج تحققًا عند إتمام الشراء أو إعلان صريح على صفحة المنتج. كذلك Uremel 10% ظاهر في شبكة العرض بـ 220 EGP مع شارة Buy 1 Get 1 (لم يُوثَّق سعره من قبل في ملف المنافس — رُصد كملاحظة لا كمنتج جديد). لا منتج جديد متموضع لجلد الوزة/سيلوليت ولا روتين متكامل رُصد. التقييم: B1G1 على أقرب منافس سعري للوشن جلد الوزة (350 EGP مقابل 360 EGP عند زيرا) يضاعف الضغط السعري على فئة جلد الوزة — السعر الفعّال 175 EGP للوحدة يقلّص الفجوة السعرية لصالح زيرا إلى مستوى التركيز/الروتين فقط (يوريا 25% ضمن روتين متكامل 799 EGP مقابل كريم منفرد 20% بعرض B1G1). يستحق المتابعة في الجولة القادمة للتأكد من استمرار العرض بعد White Friday.','2026-11-19',1795048281091);
INSERT INTO market_rounds VALUES(16,'Talabat (صيدليتان) + Dawaagate — بحث عام 2026-11-19','مسح دوري لمنافس واحد: Melano Pharma — Uremel (يوريا لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Melano Pharma — Uremel — تغيير سعري مهم في قناة الصيدليات مقابل اللقطة المسجلة. اللقطة المسجلة (2026-11-18): Uremel Cream 20% بـ 350 EGP على Melano Store، تركيبة يوريا 20% + ساليسيليك أسيد 2%. اليوم (2026-11-19 ~02:30 EET): طلبات — صيدلية الخطيب: «Melano Uremel 10% Urea 2% Salicylic Acid Moisturizing Soothing Multi Action Cream 100g» بـ 165 EGP ومتاح (InStock)؛ طلبات — صيدلية إسلام المنصوري: «Uremel Multi Action Skin Cream 100ml» بـ 240 EGP ومتاح؛ دواء جيت (dawaagate): «يوريميل كريم 100 مل — ميلانو فارما» بـ 240 EGP. أي أن سعر الصيدلية الحالي 165–240 EGP، أقل بـ 110–185 EGP من سعر متجر ميلانو المسجل (350 EGP). ملاحظة عدم يقين مهمة: عنوان طلبات يذكر يوريا 10% بينما اللقطة المسجلة تقول 20% — لم يُتحقق من صفحة Melano Store نفسها في هذه الجولة (لم تظهر في نتائج البحث)، فلا يمكن تأكيد ما إذا كان هناك متغيران (10% و20%) أم أن أحد المصدرين مخطئ في التركيز. لم يُرصد عرض جديد أو خصم موسمي أو منتج جديد أو روتين متكامل. التقييم: Uremel يبقى كريم يوريا منفردًا بلا روتين وبلا تموضع سيلوليت؛ الفجوة لصالح ZYRA ثابتة على مستوى القيمة (يوريا 25% ضمن روتين متكامل 799 EGP مقابل كريم منفرد)، لكن الفجوة السعرية اتسعت لصالحه بشدة إن صح سعر 165 EGP — لوشن زيرا المنفرد 360 EGP يصبح أغلى بأكثر من الضعف من كريم الصيدلية؛ يستحق التحقق من تركيز Uremel الفعلي وسعر Melano Store في الجولة القادمة.','2026-11-19',1795048301934);
INSERT INTO market_rounds VALUES(17,'alejon.com — الصفحة الرئيسية (زحف 2026-11-19 00:40 UTC) + صيدليات/Jumia — بحث عام 2026-11-19','مسح دوري لمنافس واحد: Alejon (يوريا لجلد الوزة) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Alejon — عرض White Friday ما زال شغالاً على المتجر الرسمي، مع منتج جديد في خط اليوريا. العرض: Buy 2 Get 2 ما زال ظاهرًا على معظم المنتجات (زحف الصفحة الرئيسية 2026-11-19 00:40 UTC / 02:40 EET)، وزيوت وچدة بخيار «Buy 2 Get 2 أو خصم 30%»، وبوكسات بخصم 30% (Drink Your Water Box ‏890 بدل 1,275 EGP؛ Oil Control Mode Box ‏660 بدل 945 EGP). الجديد: «أليجون يوريا كريم 10% – 500 مل» موسوم «جديد» بسعر 660 EGP مع Buy 2 Get 2 — أي سعر فعّال 330 EGP للعبوة 500 مل؛ حجم جديد لم يكن موثقًا في لقطة 2026-11-18 (كانت العبوة 200 مل فقط). يوريا كريم 10% – 200 مل ثابت بـ 380 EGP ومتاح (InStock) على المتجر الرسمي — نفس السعر في الصيدليات (M. Talaat Pharmacy ‏380 EGP؛ Jumia ‏334–380 EGP مقابل سعر قائمة 513 EGP)، أي ارتفاع عن سعر 320 EGP المذكور في مقال قديم (2024). كريم القدم (يوريا 30%) ثابت 295 EGP. لوشن تفتيح وترطيب الجسم 360 EGP مع B2G2. ملاحظة توفر: أليجون آي كنتور كريم (320 EGP) «غير متوفر» في قسم الأكثر مبيعًا — استمرار نمط نفاد المخزون عند Alejon. لم يُرصد منتج متموضع للسيلوليت ولا روتين متكامل لجلد الوزة، ولا إشارة للهدية السرية أو حد الشحن المجاني على الصفحة الرئيسية في هذا الزحف (لم يُتحقق من صفحة السلة/الشروط). التقييم: Alejon يوسّع خط اليوريا بحجم 500 مل بسعر فعّال 330 EGP تحت B2G2 — منافسة قيمة أقوى على كريم اليوريا المنفرد، لكنه ما زال يوريا 10% منفردًا بلا روتين؛ الفجوة لصالح ZYRA ثابتة على مستوى القيمة (يوريا 25% ضمن روتين متكامل 799 EGP مقابل كريم منفرد 10%)، مع ملاحظة أن السعر الفعّال لعبوة 500 مل يضغط على لوشن زيرا المنفرد (360 EGP).','2026-11-19',1795048890186);
INSERT INTO market_rounds VALUES(18,'Jumia Egypt + Talabat + Vezeeta Pharmacy + Chefaa + Hyper One — بحث عام 2026-11-19','مسح دوري لمنافس واحد: Bobana (سكرابات جسم 300 جم) — السعر والتوفر والعرض','جولة دورية (منافس واحد/اليوم): Bobana — لا تغيير جوهري عن اللقطة المسجلة 2026-11-18. سكرابات الجسم 300 جم ما زالت في الشريحة الاقتصادية 35–50 EGP ومتاحة: جوميا — Coffee Scrub ‏47.89–49.99 بدل 70، Apricot ‏49.49–49.99 بدل 70، Honey & Collagen ‏49.49–49.99، Gold ‏49.49–49.99، Charcoal ‏49.49–49.99، وأملاح السبا Berries ‏39.99–44 بدل 60، Yogurt ‏39.99، Milk ‏38، Lemon ‏35 (لقطات زحف جوميا قديمة 90–225 يوم لكن الأسعار متسقة عبرها). طلبات (زحف حديث): Milk Salt 300g بـ 35.99–37.45 EGP حسب الصيدلية — ملاحظة عدم يقين: إحدى قوائم طلبات تذكر «فقط 0 صنف في المخزن» لفرع معين بينما بيانات JSON-LD تقول InStock، فالتوفر يختلف حسب الفرع. Vezeeta Pharmacy: Charcoal Scrub 300g ثابت 45 EGP ومتاح. Chefaa: Apricot ثابت 68 EGP ومتاح. جديد هامشي: عرض Hyper One 9 نوفمبر — Body Splash 250مل بـ 84.95 بدل 229.95 (سبلاش جسم، ليس سكراب)؛ وعرض Wafar Cash (21 أكتوبر) — قطعتا Coffee Scrub 300g بـ 89 EGP بدل 144.40 (أي ~44.5 للوحدة، داخل نفس الشريحة). لم يُرصد عرض Black Friday/White Friday خاص ببوبانا، ولا تموضع جديد لجلد الوزة أو السيلوليت — مقالا 3 نوفمبر الترويجيان (Berries Salt لتقليل مظهر السيلوليت؛ Coffee Scrub للبشرة المشدودة) سبق توثيقهما في جولة 18-11. التقييم: بوبانا يبقى منافس سعر/حجم جماهيري فقط — سكراب بـ ~50 EGP مقابل سكرابات زيرا ضمن روتينات 799 EGP؛ الفجوة لصالح ZYRA ثابتة (روتين متكامل + مواد فعالة مقابل سكراب منفرد اقتصادي)، ولا ضغط سعري جديد على الهيروين.','2026-11-19',1795050199755);
INSERT INTO market_rounds VALUES(19,'بحث عام 2026-11-19 — Talabat + Amazon.eg + Jumia Egypt','مسح دوري لمنافس واحد: Eva Cosmetics — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Eva Cosmetics (إيفا فارما) — لا تغيير جوهري عن اللقطة المسجلة 2026-11-18. المنتج الوحيد المتموضع للسيلوليت Eva Smooth Skin Slimming Cream ما زال بلا سعر أو قائمة بيع حية في بحث اليوم (لا جوميا ولا أمازون ولا طلبات) — منتج قديم/محدود التوزيع، ولا يمكن تأكيد سعره أو توفره الحالي. لم يُرصد أي منتج يوريا أو منتج متموضع لجلد الوزة من إيفا. النطاق الحالي الموثّق اليوم (طلبات/أمازون، زحف حديث): كريمات كلاسيكية 9–70 EGP (جلسرين 20 جم 16 EGP، زبادي وخيار 50 جم 42.8 EGP ومتاح)، لوشن جسم Tropical ‏240 مل 91 EGP، كريم تبييض جسم 150 مل 199.95 EGP ومتاح، سيرومات Skin Clinic حتى ~297 EGP (فيتامين A ‏30 مل 297 EGP، فيتامين C نايت كريم 50 مل 250 EGP). لم يُرصد عرض Black Friday/White Friday خاص بإيفا ولا منتج جديد. التقييم: إيفا يبقى منافس سعر/حجم جماهيري فقط — كريم منفرد رخيص مقابل روتينات زيرا المتكاملة 799 EGP؛ لا منافس مباشر في KP/اليوريا، ومنتج السيلوليت بلا سعر حي، فلا ضغط سعري جديد على الهيروين والفجوة لصالح ZYRA ثابتة (روتين متكامل + مواد فعالة مقابل كريم/سكراب منفرد اقتصادي). ملاحظة تشغيلية: هذه ثاني تكة على التوالي يسمّي فيها مؤشر التدوير «Eva Cosmetics» — الجولة السابقة (تكة 01:10 UTC) لم تُسجَّل كجولة سوق، فظل المؤشر عليها؛ هذه الجولة مسجَّلة الآن، والمؤشر متوقَّع يتقدّم في التكة القادمة.','2026-11-19',1795051268207);
INSERT INTO market_rounds VALUES(20,'Jumia Egypt — بحث حي + صفحة العلامة 2026-11-19','مسح دوري لمنافس واحد: Nefertari — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Nefertari — تغيير موثّق: زيت السيلوليت الوحيد عندها لم يعد مدرجاً على جوميا. البحث بالاسم الكامل «Nefertari Natural Anti-Cellulite Oil» على جوميا مصر (19 نوفمبر 03:37 EET) أعطى «No results found»، وصفحة العلامة أظهرت 7 منتجات فقط ولا يوجد بينها زيت مضاد للسيلوليت ولا أي مقشر جسم؛ وبحث «Anti-Cellulite» العام (28 منتجاً) بلا أي منتج Nefertari (العلامات الظاهرة: Aliver وCarina وEveline وGeneric وRoc). السعر المسجل سابقاً للزيت (515 EGP على جوميا، زحف قديم ~217 يوم) لم يعد قابلاً للتأكيد — المنتج غير مدرج حالياً (لا يمكن التمييز بين سحب المنتج ونفاد المخزون من البحث وحده). ملاحظة عدم يقين: صفحة فئة جوميا نفسها حجبها Cloudflare ولم تُحمَّل، فالفحص اعتمد على البحث + صفحة العلامة؛ وزحف الموقع الرسمي قديم (~217 يوم) فأسعاره غير معتمدة. المنتجات السبعة الحية على جوميا الآن (كلها بأسعار مخفّضة مقابل السعر المطبوع، ومعظمها Low Stock): زيت Cyperus ‏60 مل 374 بدل 500 (-25%)، زيت جوز هند عضوي 60 مل 293.25 بدل 500 (-41%)، كحل أسود طبيعي 600 بدل 800 (-25% — ليس عناية جسم)، زيت سمسم 125 مل 391 بدل 500 (-22%)، سيروم سكوالين 635 بدل 800 (-21%)، كريم جسم بزيت الليمون 175 جم 650 بدل 800 (-19%)، زيت لافندر عطري 25 مل 590 بدل 700 (-16%). لم يُرصد أي منتج يوريا أو منتج متموضع لجلد الوزة من Nefertari، ولا عرض موسمي/Black Friday خاص بها (التخفيضات الظاهرة تخفيضات جوميا على المنتجات، لا عرض براند معلن). التقييم: Nefertari يبقى براند زيوت/عناية طبيعية منفردة بلا روتينات وبلا مواد فعالة — لا ضغط سعري أو إعلاني جديد على هيروين زيرا؛ واختفاء منتج السيلوليت الوحيد من جوميا يُبقي ممر السيلوليت مفتوحاً بالكامل لروتين زيرا المتكامل 799 EGP، والفجوة لصالح ZYRA ثابتة (روتين متكامل + يوريا 25% مقابل زيت منفرد غير مدرج حالياً).','2026-11-19',1795052406141);
INSERT INTO market_rounds VALUES(21,'بحث عام 2026-11-19 — Amazon.eg (pricena) + almktoob','مسح دوري لمنافس واحد: Eucerin — السعر والتوفر والعرض (يوريا/جلد الوزة + سيلوليت)','جولة دورية (منافس واحد/اليوم): Eucerin — لا تغيير جوهري عن اللقطة المسجلة 2026-11-18. الخط UreaRepair Plus (يوريا 10% + سيراميد) ما زال مستورداً فاخراً بلا متجر مصري مباشر وبلا تموضع «جلد الوزة» صريح وبلا منتج سيلوليت. أسعار اليوم (بحث عام 2026-11-19 ~04:00 EET): كريم القدم UreaRepair Plus 10% Urea 100مل بـ 1,699 EGP على Amazon.eg (pricena — السعر محدَّث قبل 6 أيام) / 1,720 شامل الشحن — منتج قدم لا لوشن جسم، فلا يقارن مباشرة بلوشن 250مل المسجل (1,474–1,657 EGP عند CareToBeauty) لكنه داخل نفس الشريحة الفاخرة المستوردة؛ ومقال محدَّث 2026-11-17 (almktoob) يذكر أن كريم يوسيرين يوريا في مصر يبدأ من 579 EGP. لم يُرصد عرض Black Friday/White Friday خاص بيوسيرين ولا منتج جديد ولا روتين متكامل. ملاحظة عدم يقين: صفحة pricena آخر زحف لها قديم (~291 يوم) رغم تحديث السعر قبل 6 أيام؛ وأسعار قديمة (beautykhana ~243 EGP، آخر تحديث 1,134 يوم) اترفضت كغير ممثلة؛ ولم يُتحقق اليوم من سعر لوشن CareToBeauty نفسه. التقييم: يوسيرين يبقى مرجع مصداقية طبي مستورد مش منافس رف — أسعار 2–4 أضعاف زيرا (لوشن زيرا 360 EGP وروتين KP ‏799 EGP)، فلا ضغط سعري أو إعلاني جديد على الهيروين، والفجوة لصالح ZYRA ثابتة (يوريا 25% ضمن روتين متكامل بسعر أقل بكثير من كريم مستورد منفرد 10%).','2026-11-19',1795053713188);
INSERT INTO market_rounds VALUES(22,'Jumia Egypt + Tallah Beauty + Flowrista — بحث عام 2026-11-19','مسح دوري لمنافس واحد: Bubblzz — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Bubblzz — لا تغيير جوهري في التموضع عن اللقطة المسجلة 2026-11-18، مع حركة سعرية طفيفة على السكراب. التموضع ما زال عناية جسم طبيعية قائمة على الروائح (سكراب/لوشن/شاور جل/سبلاش + سيتس هدايا «Blooming Love» و«Cupcake Body Care Collection»)، بلا أي منتج متموضع لجلد الوزة أو السيلوليت أو اليوريا، وبلا روتين علاجي متكامل وبلا مواد فعالة مسماة. الأسعار اليوم (بحث عام 2026-11-19 ~04:40 EET): Tallah Beauty (زحف قبل ~10 ساعات) — Vanilla Body Scrub 250 جم بـ 290 EGP مقابل 250 EGP في اللقطة المسجلة (+40 EGP، +16% على هذه القناة)؛ Coconut Ultra Rich Body Lotion 150 جم 280 EGP وBerryilicious Ultra Rich Body Lotion 150 جم 280 EGP (مطابقان للقطة ~280)؛ Coconut Travel Size Hand & Body Lotion 50 مل 110 EGP. جوميا (زحف قديم ~21 يوم — ملاحظة عدم يقين): سبلاشات الجسم 250 مل بـ 327 EGP بدل 380 (-14%، Low Stock) — White Musk وStrawberries N Cream وBonbon وCherry Blossom وOud وVanilla — مقابل 375 EGP في اللقطة المسجلة؛ White Knight Perfume 50 مل 426 بدل 495 (-14%)؛ Pink Blush Fragrance Mist 200 مل 400 بدل 420 (-5%)؛ Mini Perfume White Knight 18 مل 77 بدل 90. لم يُرصد عرض Black Friday/White Friday خاص ببوبلز ولا منتج جديد. التقييم: بوبلز يبقى منافس عناية جسم معطرة طبيعية فقط — سكراب بـ 250–290 EGP ولوشن بـ 280 EGP مقابل سكرابات/لوشنات زيرا ضمن روتينات 799 EGP؛ لا ضغط سعري أو إعلاني جديد على الهيروين، والفجوة لصالح ZYRA ثابتة (روتينان علاجيان متكاملان + يوريا 25% مقابل منتجات منفردة قائمة على الرائحة). ملاحظة تشغيلية: مؤشر التدوير سمّى «Bubblzz» في 4 تكات متتالية (02:10 و02:20 و02:29 و02:39 UTC) من غير تسجيل جولة — هذه الجولة مسجَّلة الآن، والمؤشر متوقَّع يتقدّم في التكة القادمة.','2026-11-19',1795056059688);
INSERT INTO market_rounds VALUES(23,'norshek.com — المتجر الرسمي (فحص حي 2026-11-19 04:51–04:58 EET)','مسح دوري لمنافس واحد: Norshek — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Norshek — تغييرات موثّقة في التوفر والسعر مقابل اللقطة المسجلة 2026-11-18. أولاً: لوشن Skin Kin (زبدة شيا + حليب جوز الهند، غير دهني) سعره الحالي 272 EGP على المتجر الرسمي مقابل 395 EGP في اللقطة المسجلة — لكنه OUT OF STOCK / Sold out (مقاسا 250 مل و500 مل، و500 مل يظهر مشطوباً)، فلا ضغط سعري حي منه؛ ملاحظة عدم يقين: لم يتأكد إن كان 272 سعر الـ250 مل أم سعر موحّد بعد نفاد الـ500 مل. ثانياً: المتجر نفسه شبه نافد — صفحة Shop تعرض 9 منتجات متاحة فقط، والمنتجات النافدة مخفية من الأقسام وتظهر في البحث المباشر فقط؛ لوشن ما بعد الشمس Sol-lotion (373 EGP) نافد، وسيروم الشعر Hairytale نافد بلا سعر ظاهر، ومعظم الكتالوج (شامبو/بلسم سائل، جل شعر، زيوت عطور، شاي) نافد. المتاح فعلياً اليوم: لوح شامبو So Nice بـ 325 EGP ولوح بلسم So So Nice بـ 272 EGP (مقابل 185–195 في اللقطة المسجلة — ارتفاع واضح في الألواح)، و4 صواني صابون جلسرين (Earth/Oath/Birth/Faith) بـ 160 EGP لكل منها مقابل 95–140 في اللقطة (ارتفاع)، وشاي عشبي Karkar-Eh بـ 230 وHippies-Kiss بـ 210 EGP، ومزيل عرق Bodo بـ 215 EGP. ثالثاً: لا يوجد أي منتج متموضع لجلد الوزة أو السيلوليت أو اليوريا — بحث المتجر نفسه يعيد «No products found» لكلمات keratosis وcellulite و«جلد الوزة» و«سيلوليت» و«يوريا»؛ ونتائج urea الإنجليزية تعود فقط لأن المكونات تتضمن Diazolidinyl Urea كمادة حافظة، لا كيوريا علاجية. رابعاً: لا عرض Black Friday/White Friday — بحث المتجر عنهما يعيد «No products found» ولا لافتة موسمية على الصفحة الرئيسية؛ العرض الوحيد حزمة شعر 15% (610 بدل 518 EGP) وهي نافدة أيضاً، إضافة لعرض استدامة دائم (إرجاع عبوة = خصم 10% على الشراء التالي) وتوصيل نفس اليوم داخل القاهرة. خامساً: منتج جديد واحد — Hairapy Leave-In Conditioner (شارة NEW، رائحة فراولة، 250 مل) لكنه نافد بلا سعر ظاهر. التقييم: Norshek يبقى براند إيكولوجي/طبيعي بلا روتينات وبلا مواد فعالة وبلا أي تموضع KP/سيلوليت — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينان علاجيان متكاملان 799 EGP مقابل لوشن ترطيب منفرد نافد + ألواح شعر أغلى سعراً)؛ بل إن نفاد معظم مخزون متجره يضعف حضوره التنافسي أونلاين أكثر.','2026-11-19',1795057137653);
INSERT INTO market_rounds VALUES(24,'scrubbybubbyshop.com (معطّل — DNS) + Beauty Bounty — فحص حي 2026-11-19 05:10–05:12 EET','مسح دوري لمنافس واحد: Scrubby Bubby Shop — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Scrubby Bubby Shop — تغيير موثّق في القناة والتشكيلة. أولاً: الموقع الرسمي scrubbybubbyshop.com لا يتحمّل إطلاقاً — خطأ DNS (This site can''t be reached / DNS address could not be found) في فحص حي 2026-11-19 05:10–05:12 EET وتكرر بعد إعادة التحميل، فلا يمكن تأكيد أي سعر أو عرض من المتجر الرسمي نفسه. ثانياً: على Beauty Bounty (القناة البديلة المسجلة) يوجد منتج واحد فقط من البراند: Super Hydrating Beauty Shower Gel — Strawberry Sorbet 300 جم بـ 150 EGP ومتاح (InStock) بلا سعر مخفّض — نفس سعر اللقطة المسجلة 2026-11-18 (150 EGP)؛ أما سكراب Candy Jam المسجل بـ 60 EGP فلم يعد ظاهراً في كتالوج Beauty Bounty (بحث «Scrubby Bubby» و«Scrubby» و«Bubby») — غياب موثّق على هذه القناة فقط، وليس تأكيداً لسحب المنتج. ثالثاً: لا يوجد أي منتج متموضع لجلد الوزة أو السيلوليت أو اليوريا من سكربي بوبي، ولا عرض Black Friday/White Friday خاص بها. رابعاً: ملاحظة سوق على نفس القناة (ليست منتجات سكربي بوبي): كريمات يوريا متموضعة لجلد الوزة ظهرت على Beauty Bounty — Vee Allure Urea Hydro Cream 10% بـ 249 EGP (يذكر صراحة Keratosis Pilaris) وSoralone Urea 15% Cream Gel بـ 245 EGP (مقابل ~125 EGP سعر التخفيض المسجل في مسح 18-11 — فرق قناة) وMiss Je Lu Urea-Cica Repairing Cream بـ 390 EGP؛ ومنتجات سيلوليت: Areej Faltter 60 مل بـ 360 EGP (علاج شدّ للجلد المعرّض للسيلوليت) وAreej Scrub Energize Coffee 200 جم بـ 450 EGP — براندات جديدة تستحق التتبع كمنافسين محتملين على نفس الرف. التقييم: سكربي بوبي يبقى براند عناية يدوية معطرة متناهي الصغر بلا روتينات وبلا مواد فعالة وبلا تموضع KP/سيلوليت — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة؛ بل إن تعطل موقعه الرسمي واختفاء السكراب من Beauty Bounty يضعفان حضوره الأونلاين أكثر.','2026-11-19',1795057986406);
INSERT INTO market_rounds VALUES(25,'rawafrican.net — المتجر الرسمي (فحص حي لكتالوج 2026-11-19 05:31–05:33 EET)','مسح دوري لمنافس واحد: Raw African — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Raw African — أول جولة مسجلة له في النظام (لا لقطة سابقة للمقارنة). التموضع: عناية طبيعية/نظيفة للجسم والشعر والوجه بأسعار اقتصادية، بلا أي منتج متموضع لجلد الوزة أو السيلوليت وبلا روتين علاجي متكامل. الأسعار اليوم (فحص حي لكتالوج المتجر الرسمي 2026-11-19 05:31–05:33 EET، كلها متاحة): غسولات الجسم الثلاثة 120 EGP لكل منها (Very Berry / African Blossom / Arabian Oud)؛ لوشن الجسم الوحيد Moon Kiss Shimmering Lotion بـ 345 EGP؛ لا يوجد سكراب جسم مخصص (أقرب مقشر: Lip Polish بـ 120 EGP) ولا زبدة جسم مستقلة (نتائج Shea Butter منتجات شعر). اليوريا موجودة لكن للقدمين فقط: Urea Heel Cream بـ 140 EGP (يوريا + شيا + كاكاو + منثول للكعب الجاف/المتشقق) — ويظهر أيضاً ضمن مجموعة Night Skin Routine بـ 470 بدل 610 EGP. بحث الكتالوج عن keratosis pilaris / «جلد الوزة» أعاد صفر منتج، وعن cellulite / «سيلوليت» بلا مطابقة. باقات مخفضة قائمة في الكتالوج (ليست موسومة Black Friday/White Friday): Summer Set بـ 455 بدل 910 EGP (-50%)، Shea Butter Mega Set بـ 760 بدل 1,169 EGP، Fully Fresh Set of 3 بـ 260 بدل 390 EGP، Head-to-Toe بـ 865 بدل 1,085 EGP، Polished & Fresh بـ 520 بدل 615 EGP. لم يُرصد عرض Black Friday/White Friday صريح في بحث الكتالوج. ملاحظة عدم يقين: لافتات الصفحة الرئيسية وشروط الشحن لم تُتحقق من الكتالوج (تحتاج فحص صفحة رئيسية). التقييم: Raw African يبقى منافس عناية طبيعية اقتصادية منفردة (غسول 120 EGP ولوشن لامع 345 EGP) بلا مواد فعالة مسماة للجسم وبلا تموضع KP/سيلوليت — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينان علاجيان متكاملان 799 EGP بيوريا 25% مقابل منتجات منفردة قائمة على الرائحة/الطبيعي)؛ كريم اليوريا الوحيد عنده للكعب فقط بـ 140 EGP، فلا منافسة مباشرة على لوشن KP.','2026-11-19',1795059256692);
INSERT INTO market_rounds VALUES(26,'بحث عام 2026-11-19 — أخبار التمويل يناير 2024 + ملف المنافس المسجل؛ لا متجر عام ظاهر','مسح دوري لمنافس واحد: Mira Cosmetics — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Mira Cosmetics — لا لقطة سعر/عرض حيّة قابلة للتأكيد اليوم. أولاً: لا متجر إلكتروني عام ظاهر للبراند في بحث اليوم (2026-11-19 ~05:40 EET): كل النتائج الحالية عن ميرا هي أخبار تمويل يناير 2024 (200 ألف دولار من Wingoo Investment and Technology، المؤسِّسة أميرة داود، أول منتج محلي نهاية 2023، هدف 100 ألف عميل بنهاية 2024، وخطط لموقع إلكتروني ومنافذ بيع) — ولا يوجد متابعة صحفية منشورة عن تحقق هدف 2024 أو عن توسع الإمارات/السعودية. ثانياً: لا قائمة منتجات حية على جوميا/نون/زينة ظهرت في البحث؛ النتائج باسم «Mira» تخص براندات أخرى (Mirada عطور، Mira حقائب/ملابس). ثالثاً: السعر الوحيد المسجّل يبقى لقطة 2026-11-18 من إنستجرام البراند — مزيل عرق بالكركديه والشيا 30 مل بـ 150 EGP — ولم يُتحقق منه اليوم لعدم ظهور حساب/كتالوج عام في البحث (اسم حساب إنستجرام غير مسجّل في ملف المنافس). رابعاً: لا يوجد أي منتج متموضع لجلد الوزة أو السيلوليت أو اليوريا من ميرا في أي نتيجة، ولا عرض Black Friday/White Friday خاص بها. ملاحظة عدم يقين: البراند يبيع عبر إنستجرام/رسائل (بلا كتالوج عام)، فلا يمكن تأكيد السعر أو التوفر الحالي أو حتى استمرار نشاطه التجاري في 2026 من المصادر العامة وحدها — يحتاج فحص حساب إنستجرام مباشرة. التقييم: ميرا تبقى توأم نموذج DTC ممول (تشابه 41/100) وليست منافس منتجات — لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينان علاجيان متكاملان 799 EGP بيوريا 25% مقابل مزيل عرق وزيوت معطرة اقتصادية بلا تموضع مشاكل). ملاحظة تشغيلية: مؤشر التدوير تقدّم صحيحاً من Raw African (جولة 25 مسجلة 05:34 EET) إلى Mira Cosmetics — هذه أول جولة مسجلة لميرا في النظام.','2026-11-19',1795059664758);
INSERT INTO market_rounds VALUES(27,'Source Beauty — فحص حي 2026-11-19 06:30 EET','مسح دوري لمنافس واحد: Kyra Naturals — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)','جولة دورية (منافس واحد/اليوم): Kyra Naturals — أول جولة مسجلة له في النظام، وتغيير كبير موثّق: البراند اختفى تماماً من قناة بيعه الوحيدة المسجلة. أولاً: صفحة العلامة على Source Beauty (فحص حي 2026-11-19 06:30–06:34 EET) فارغة تماماً — النص حرفياً «Sorry, there are no products in this collection» — صفر منتج، فلا قائمة أسعار ولا حالات توفر اليوم. البحث داخل الموقع عن «Kyra» أعاد 10 نتائج كلها مقالات مدونة، وفحص الكتالوج أعاد 0 منتج باسم Kyra. ثانياً: دليل على أن المنتجات كانت موجودة ثم أُزيلت — وصف صفحة المجموعة في نتائج البحث يقول «Shop 39+ products» (وصف قديم لا يطابق الوضع الحالي)، ورابط منتج قديم «كيرا بيتشى سكراب» أصبح الآن 404. اللقطة المسجلة 2026-11-18 كانت: Coconut Body Lotion 130مل بـ 110 EGP، لوشنات 110، شاور جل 85، باث فيز 100 — كلها غير قابلة للتأكيد اليوم لأن المنتجات غير مدرجة أصلاً. ثالثاً: لا يوجد أي منتج Kyra متموضع لجلد الوزة أو السيلوليت أو اليوريا — لا منتجات أصلاً لفحص وصفها — ولا عرض Black Friday/White Friday أو شارة «جديد» خاصة بها. عرض Source Beauty العام (ليس Kyra): «BLACK FRIDAY SALE · UP TO 70% OFF» + «THE BIG BEAUTY SALE · 1–30 NOVEMBER». رابعاً: إنستجرام المصري المؤكد kyra_naturals (11.1K متابع) ما زال موجوداً — الوصف «For orders DM 🇪🇬Made in Egypt» وبلا رابط متجر خاص في الملف الشخصي — أي أن البيع عبر الرسائل هو القناة الباقية الظاهرة؛ ولم يُعثر على متجر خاص مؤكد (kyranatural.com الظاهر في البحث موقع لتتبع خلايا النحل، لا علاقة له بالبراند). ملاحظة عدم يقين: سبب الإزالة من Source Beauty غير معروف (انسحاب من المنصة؟ نفاد مخزون جماعي؟ إغلاق؟) — لا يمكن التمييز من المصادر العامة وحدها؛ يحتاج متابعة حساب الإنستجرام. ملاحظة جانبية من نفس الرف (ليست منتجات Kyra): على Source Beauty توجد منتجات يوريا/سيلوليت لبراندات أخرى — Shaan Urea 10% Body Moisturizer بـ 280 EGP (متاح)، Vee Allure Urea Hydro Cream 10% بـ 162 EGP بدل 249 (متاح)، Hathor Cellulite Oil بـ 360 EGP (غير متوفر)، Areej Cellulite Treatment بـ 360 EGP (غير متوفر) — براندات تستحق التتبع كمنافسين محتملين على نفس الرف. التقييم: Kyra Naturals يبقى براند عناية طبيعية اقتصادية منفردة (تشابه 38/100) بلا روتينات وبلا مواد فعالة وبلا أي تموضع KP/سيلوليت — واختفاؤه من Source Beauty يضعف حضوره الأونلاين إلى حد كبير؛ لا ضغط سعري أو إعلاني جديد على هيروين زيرا، والفجوة لصالح ZYRA ثابتة (روتينان علاجيان متكاملان 799 EGP بيوريا 25% مقابل براند بلا منتجات مدرجة حالياً على قناته المسجلة).','2026-11-19',1795062994556);
INSERT INTO competitor_alerts VALUES(1,'سوق اليوريا الصيدلي (Hayah/Skinova/Melano/Alejon)','منتج منافس','أربعة منافسين صيدليين يبيعون منتجات يوريا لجلد الوزة بتركيزات 10–20% وأسعار 199–439 EGP — راجع تنبيه التمييز: ZYRA عندها 25% بـ 360 EGP.','بحث ويب موثق بروابط صفحات المنتجات','New',1795032253496);
INSERT INTO competitor_alerts VALUES(2,'سوق السيلوليت — كلمة «سيلوليت» في مكتبة الإعلانات','فرصة سوق','كلمة «سيلوليت» في Meta Ads Library كلها عيادات وأجهزة فقط: Hollywood Clinic بإعلان Emtone شغال من يناير 2025 (~682 يوم). المنتجات المنزلية الوحيدة المرئية: أداة Rolliva وقطع To Redo patches. لا يوجد أي روتين سيلوليت منزلي DTC بيعلن على الكلمة — ممر مفتوح لروتين السيلوليت من زيرا (799 EGP).','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','New',1795037004005);
INSERT INTO competitor_alerts VALUES(3,'Hepta Skin — هيبتا','هيمنة إعلانية','Hepta Skin يمتلك أطول عمر إعلاني في فئة جلد الوزة/اليوريا: إعلانات فيديو شغالة من 8–18 ديسمبر 2025 (~335–345 يوم) بهوكات أطباء (د. ناردين، روان)، ومهيمن على بحث «جلد الوزة» (~520 نتيجة) و«كريم يوريا» (~270 نتيجة). منتج البطل Carbamide Twenty (يوريا 20%). هذا هو المنافس الإعلاني رقم 1 الجديد لروتين جلد الوزة من زيرا — لم يكن مُتتبَّعًا من قبل.','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','New',1795037004019);
INSERT INTO competitor_alerts VALUES(4,'Tetavara','توقف إعلاني','Tetavara مظلم تمامًا على ميتا دلوقتي: صفر إعلانات نشطة في مصر بتاريخ 2026-11-18، رغم إن عرض Pink Friday شغال على موقعه (كريم شدّ Buy 1 Get 1 بسعر 350 EGP + هدايا متدرجة). أقرب منافس DTC لروتين السيلوليت مش بيعلن حاليًا — نافذة دخول أنضف لزيرا.','Meta Ads Library — مصر، إعلانات نشطة — عبر متصفح المالك، 2026-11-18','New',1795037004035);
INSERT INTO competitor_alerts VALUES(5,'Alejon','تحليل استراتيجي','موقف Alejon في جلد الوزة أضعف مما يوحي به حجمه الإعلاني (~84 إعلان نشط): منتجات فردية يوريا 10% فقط، لا يوجد روتين مخصص لجلد الوزة، وكل الـ14 باقة نفدت مخزونًا. قوته الحقيقية هي التوزيع (2.5M متابع + صيدليات) وميكانيكا العروض (Buy 2 Get 2 + هدية سرية + شحن مجاني فوق 1,000 EGP)، مش التركيبة — مقابل يوريا 25% وروتين كامل بـ799 EGP عند زيرا.','alejon.com (تصفح مباشر، جهاز المالك) + Meta Ads Library — 2026-11-18','New',1795037036209);
INSERT INTO competitor_alerts VALUES(6,'Urban Ducks','تغيير سعر/توفر','على Bloom Pharmacy (زحف 2026-11-18 23:46 UTC): تشكيلة Urban Ducks تقلصت لـ4 منتجات فقط — سكرابا القهوة/البرتقال بخطاب السيلوليت الصريح (255 EGP في اللقطة المسجلة) وزيت الجسم (320 EGP) غير موجودين إطلاقًا في التشكيلة الحالية. الغياب موثّق على بلوم فقط وليس تأكيدًا لسحب المنتج (Zynah لم تُفحص صفحةً صفحةً). تغييرات سعرية صغيرة: مرطبا Liquid Silk 250مل بـ 255 بدل 300 EGP (−15%)، ولوشن Chocolate Cookies 120مل بـ 180 بدل 170 EGP (+10)، وزبدة الجسم ثابتة 210 EGP. لا منتج جديد ولا عرض موسمي جديد. الأثر على زيرا: لا ضغط جديد على روتين السيلوليت 799 EGP — وغياب السكرابات، إن تأكد، يضعف أقرب ادعاء سيلوليت صريح لدى هذا المنافس.','Bloom Pharmacy — https://www.bloompharmacy.com/collections/urban-ducks','New',1795045697919);
INSERT INTO competitor_alerts VALUES(7,'Melano Pharma — Uremel','عرض جديد','عرض Buy 1 Get 1 ظهر على Uremel Cream 20% (350 EGP) في شبكة عروض White Friday 11/11 على الصفحة الرئيسية لمتجر Melano — سعر فعّال 175 EGP للوحدة، مقابل 350 EGP بدون عرض في لقطة 2026-11-18. ده أقرب منافس سعري للوشن جلد الوزة بتاع زيرا (360 EGP)، فالعرض بيضاعف الضغط السعري على فئة جلد الوزة. ملاحظة: صفحة المنتج نفسها لا تذكر B1G1 — التطبيق الفعلي يحتاج تحققًا. لا منتج جديد ولا تغيير في السعر الأساسي (350 EGP ثابت).','Melano Store — https://melanopharma.store/ — زحف 2026-11-19 00:30 UTC / 02:30 EET','New',1795048281167);
INSERT INTO competitor_alerts VALUES(8,'Alejon','منتج جديد','حجم جديد في خط اليوريا: «أليجون يوريا كريم 10% – 500 مل» موسوم «جديد» على alejon.com بسعر 660 EGP مع عرض Buy 2 Get 2 (سعر فعّال 330 EGP للعبوة 500 مل). لقطة 2026-11-18 كانت توثّق عبوة 200 مل فقط (380 EGP). يوريا كريم 200 مل ثابت 380 EGP ومتاح. لا روتين جلد وزة ولا منتج سيلوليت جديد. الأثر على زيرا: منافسة قيمة أقوى على كريم اليوريا المنفرد — السعر الفعّال 330 EGP لعبوة 500 مل يضغط على لوشن زيرا المنفرد (360 EGP)، لكن الفجوة على مستوى القيمة ثابتة (يوريا 25% ضمن روتين متكامل 799 EGP مقابل كريم منفرد 10%).','alejon.com — الصفحة الرئيسية (زحف 2026-11-19 00:40 UTC / 02:40 EET)','New',1795048900983);
INSERT INTO competitor_alerts VALUES(9,'Kyra Naturals','اختفاء من قناة بيع','اختفاء كامل من Source Beauty — قناة البيع الوحيدة المسجلة للبراند: صفحة العلامة فارغة («Sorry, there are no products in this collection») وبحث الكتالوج يعيد 0 منتج، ورابط منتج قديم («كيرا بيتشى سكراب») أصبح 404، رغم أن وصف الصفحة القديم يقول «Shop 39+ products». اللقطة المسجلة 2026-11-18 (لوشن جوز هند 110 EGP، شاور جل 85، باث فيز 100) لم تعد قابلة للتأكيد. إنستجرام kyra_naturals (11.1K متابع) ما زال موجوداً والبيع عبر الرسائل هو القناة الباقية الظاهرة. سبب الإزالة غير معروف من المصادر العامة — يحتاج متابعة. الأثر على زيرا: لا ضغط جديد على الهيروين؛ حضور منافس مجاور (تشابه 38/100) ضعف أونلاين.','Source Beauty — https://sourcebeauty.com/collections/kyra-naturals — فحص حي 2026-11-19 06:30–06:34 EET','New',1795063012703);
INSERT INTO agent_plans VALUES(1,'خطة Relaunch: إعادة إطلاق Zyra Care من قراءة الويبسايت والسوق لحد أول قرار Kill/Scale','C','[{"step":"قراءة الويبسايت وتثبيت الكتالوج والسياسات في المدخلات الأساسية","stage":"RETRIEVE","section":"المدخلات الأساسية","detail":"23 منتج بأسعار حقيقية من zyra-care.com + شحن 75/مجاني من 1000 + استرجاع 14 يوم. COGS لسه على المالك."},{"step":"دراسة السوق: منافسو اليوريا الصيدليون + الجماهيريون","stage":"RETRIEVE","section":"متابعة السوق","detail":"فجوة تمييز موثقة: يوريا 25% الأعلى تركيزاً بـ 360 EGP مقابل 10–20% عند المنافسين."},{"step":"تجهيز كرييتيف الإطلاق للـ Dual Hero بقاعدة Rule of One + Cold Start checklist","stage":"EXECUTE","section":"الكرييتيف","detail":"هيرو مزدوج بقرار مالك: روتين السيلوليت 799 + روتين جلد الوزة/الفراولة 799 — كل إعلان مشكلة واحدة واحتياج عاطفي واحد واعتراض واحد ودليل واحد، مع تحذير الريتينول وفحص AEO."},{"step":"حملتان منفصلتان + اعتماد الإطلاق","stage":"PLAN","section":"الميديا باير","detail":"CBO مستقل لكل Hero Offer (قاعدة Domino)، ميزانية اختبار منقسمة بين الهيروين، وتتبع Kill/Scale مستقل لكل روتين — الإطلاق نفسه قرار مالك في الاعتمادات، مع فرصة Cross-Bundle (799+799) كاختبار لاحق."},{"step":"متابعة أول 30 يوم: Funnel يومي ولقطات COD أسبوعية","stage":"VALIDATE","section":"متابعة الشغل","detail":"أول Task D بعد 7 أيام نظيفة خارج تشويش الـ Payday قدر الإمكان."},{"step":"تقييم وتعلم: Proven/Dead + خطة تصحيح","stage":"DELIVER & LEARN","section":"التجارب والتعلم","detail":"Outcome Review على كل عنصر Relaunch وتسجيل التعلم قبل أي Scale."}]','Proposed',1795032253673);
INSERT INTO agent_plans VALUES(2,'إنتاج واختبار أول دفعة كرييتف للهيروين (سيلوليت + جلد الوزة) جاهزة لنافذة اختبار 25 نوفمبر — مفاهيم متنوعة بجد، مبنية على عصر المنافسين، وبوابات Task D جاهزة','C','[{"step":"تثبيت مدخلات المفاهيم من عصر المنافسين","stage":"UNDERSTAND","section":"السوق والمنافسين","detail":"Hepta كسبان بفيديوهات دكتور + يوريا 20% من ~345 يوم؛ Alejon زاوية الاستمرارية ناجحة رغم يوريا 10% وباندلات غير متوفرة؛ لين السيلوليت فاضي من معلنين DTC؛ يوريا زيرا 25% أعلى تركيز معلن."},{"step":"صياغة 4–5 مفاهيم متنوعة لكل هيرو (مش نسخ من مفهوم واحد)","stage":"PLAN","section":"المحتوى والكرييتف","detail":"KP: سلطة خبير/دكتور + استمرارية الروتين + مقارنة تركيز 25%. سيلوليت: روتين متكامل في البيت + مشكلة بالعامية + قبل/بعد واقعي. Rule of One لكل مفهوم."},{"step":"إنتاج المسودات وربطها بطلبات التوليد","stage":"EXECUTE","section":"المحتوى والكرييتف","detail":"المسودات تتعمل من طابور طلبات التوليد داخل السيستم وترجع كأصول مسودة مرتبطة بطلبها — لا نشر بدون اعتماد المالك."},{"step":"فحص AEO + Validator + تحذير الريتينول","stage":"VALIDATE","section":"المحتوى والكرييتف","detail":"صفر وعود علاجية أو ضمان نتيجة؛ تحذير الريتينول الإلزامي على أي أصل فيه ريتينول؛ ادعاء الـ1000+ عميلة لا يُستخدم قبل توثيقه."},{"step":"هيكل الاختبار: CBO مستقل لكل هيرو، تقسيم 50/50","stage":"PLAN","section":"الحملات والميديا باير","detail":"واحد Broad Advantage+/CBO لكل Hero Offer (Domino)؛ لا قتل قبل 48–72 ساعة؛ 3:2:2 محفوظة لمرحلة الـ Scale على SKU مثبت."},{"step":"بوابات القرار Task D من أول يوم","stage":"CRITIQUE","section":"المالية والتدقيق","detail":"هدف Placed CPP ≤150–160؛ Break-even ≈275 [EST لحد رسوم Bosta الفعلية]؛ GPT <15% من AOV = لا Scale؛ أول قرار بعد 7 أيام نظيفة (بند شغل 11 بتاريخ 2026-12-03)."},{"step":"تسجيل التعلم بعد الاختبار","stage":"DELIVER & LEARN","section":"التشغيل والتعلّم","detail":"الفائز يدخل Proven Wrappers والخاسر Dead Angle Graveyard بأسبابه — ويتغذي بيه تفكير زيرا وبريفّات الجمهور في الدورة اللي بعدها."}]','Proposed',1795048324242);
