INSERT INTO activity_events VALUES(11,'النظام والإعدادات','Loop Tick','Tick 23:09 EET — قائمة المهام فارغة؛ 14 عنصر شغل كلها New بلا تاريخ استحقاق (بانتظار تواريخ واعتماد المالك) فلا مهام مستحقة للتشغيل. لا اعتمادات معلّقة ولا تعليمات مالك مخزّنة. خطة Relaunch المقترحة (id 1) عمرها ساعات وTTL 14 يوم فليست منتهية. نفّذ runlooptick: ملاحظة مسح المنافس الدوري Skinova Image + لا مسودات بريفات جمهور بعد. لا إجراء خارجي نُفّذ.',1795036212331);
INSERT INTO activity_events VALUES(12,'النظام والإعدادات','تدقيق فجوات','تدقيق فجوات شامل (بيانات ووظائف فقط — التصميم خارج النطاق أثناء إعادة البناء): المنتجات 23 ✓، المنافسون 30 ✓ (الخمسة المسترجعون موجودون بتموضع وأسعار)، اللقطة المالية 1 وموسومة [EST] بافتراضات موثقة ✓، عناصر الريلونش 14، جولات السوق 2، كلمات البحث 12 بمسح أساس اليوم، المراجعة الأسبوعية مقفولة ✓، أرقام الداشبورد مطابقة للقوائم. فجوات على المالك: أهداف الريلونش فارغة، COGS غير الهيروين، رسوم Bosta الفعلية ونسب التأكيد/التسليم، تصاميم الأورجانيك الـ15. فجوات منصة: سحب ميتا (الوضع يبقى Pending). لا بيانات مخترعة ولا إجراءات خارجية.',1795036505394);
INSERT INTO activity_events VALUES(13,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Skinova Image» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور: لا مسودات محتوى بعد — التحديث الدوري (كل 6 ساعات) هيلاقيها فاضية لحد ما تتكتب مسودات.',1795036835708);
