INSERT INTO activity_events VALUES(43,'الأورجانيك','تسجيل حزمة الأورجانيك والهيروين','تم تسجيل 15 بوست أورجانيك (10 ستاتيك S1–S10 + 5 كاروسيل C1–C5) مع 45 كابشن (3 فاريانتات لكل بوست: تعليمي/قيمة، تفاعلي، بيع ناعم وCTA) — كلها بحالة مسودة، ولا يوجد كابشن معتمد من المالك بعد. تم التأكد من هيروين الريلونش كمنتجات موجودة (روتين السيلوليت id 3 وروتين جلد الوزة والفراولة id 14 — كل واحد 799 EGP وCOGS 350 EGP) وتسجيل هدفين ريلونش لهما (التارجت 0 — لم يحدده المالك بعد، الميزانيات مؤجلة بقراره). أعلام الامتثال والأخطاء مسجلة على البوستات: ريتينول على S1/S2/S4/C1/C2/C4، وعد الشحن في C3 سلايد 8، خطأ C2 سلايد 9، وخطأي C5 (سلايد 7 وسلايد 9 المفقودة)، والبوستات المثبتة C1/C2/C3.',1795038303744);
