INSERT INTO activity_events VALUES(110,'النظام والإعدادات','دورة داتا كاملة','دورة داتا كاملة بأمر المالك 19-11-2026: فحص حداثة + تيك لوب + لوب تحليل (تحليلان جديدان لإعلانات منافسين) + توليد تفكير (4 مدخلات جديدة بانتظار قرار المالك) + تجهيز شغل: تواريخ استحقاق لكل بنود الشغل الـ14 حسب مراحل الريلونش (تحضير لحد 24-11، إطلاق 25-11، أول Task D ‏3-12، تقييم 30 يوم 26-12)، بند دراسة المنافسين اتقفل Done 100%، بند المدخلات الأساسية اتعلّم بمعوّق Bosta/النسب على المالك، خطة وكيل جديدة لإنتاج واختبار كرييتف الهيروين، مهمة بحث سوق دورية في طابور الشغل، و3 مسودات محتوى لأسبوع الأورجانيك (20–22 نوفمبر) في المحتوى والكرييتف.',1795048344478);
INSERT INTO activity_events VALUES(111,'Operations','Loop Tick','Tick 02:29 EET 19 نوفمبر: قائمة المهام فارغة وعناصر العمل الـ14 بلا موعد استحقاق (بانتظار تواريخ واعتماد المالك) — لا مهام مستحقة للتشغيل. لا موافقات معلقة ولا تعليمات مالك جديدة. لا اقتراحات منتهية الصلاحية (TTL 14 يومًا، الفرصتان من 18 نوفمبر ما زالتا ساريتين). نُفّذ مسح المنافس الدوري «Melano Pharma — Uremel» وسُجّل كجولتين: (15) متجر ميلانو — Uremel 20% ثابت 350 EGP مع بانر White Friday وشارة Buy 1 Get 1 (سعر فعّال 175 EGP للوحدة) وUremel 10% بـ 220 EGP مع B1G1؛ (16) قناة الصيدليات — Uremel 10% بـ 165 EGP و100 مل بـ 240 EGP على طلبات/دواء جيت. بريفات الجمهور: لا مسودات محتوى بعد.',1795048357698);
INSERT INTO activity_events VALUES(112,'لغة البحث','مسح لغة البحث','مسح Google Egypt autocomplete (hl=ar, gl=eg, client=chrome) لـ 12 كلمة مفتاحية — 02:30 EET. 5 اقتراحات جديدة مقابل مسح 02:09: «علاج جلد الوزة والشعر تحت الجلد»، و«كريم mixa للجسم يوريا»، «كريم ايفلين للجسم يوريا»، «كريم ترطيب للجسم يوريا»، «كريم في يوريا للجسم». سُجلت ملاحظتان (23، 24) وفرصة منتج جديدة (id 3: الشعر تحت الجلد). لغة بحث يوريا 30% و«سيلوليت رول» لسه في القوائم — الفرصتان السابقتان (id 1، 2) قيد الدراسة.',1795048404720);
INSERT INTO activity_events VALUES(113,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Alejon» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795048793565);
