INSERT INTO activity_events VALUES(141,'التشغيل والتعلّم','Loop Tick','تيك 10 دقائق 03:59 EET 19 نوفمبر: (1) قائمة المهام: مهمة واحدة (id 1 — بحث سوق دوري Hepta/Alejon/Soralone/Centevia) بلا تاريخ استحقاق مسجّل فليست مستحقة بعد؛ عناصر الشغل: لا شيء مستحق اليوم (أقرب استحقاق 2026-11-21). (2) التيك نفّذ مسح المنافس الدوري «Eucerin» وسُجّل كجولة سوق id 21: لا تغيير جوهري — مستورد فاخر (قدم 10% ‏1,699 EGP على Amazon.eg؛ يوريا يبدأ من 579 EGP)، بلا تموضع جلد وزة صريح وبلا عرض موسمي؛ الفجوة لصالح زيرا ثابتة. (3) انتهاء الصلاحية: لا اقتراحات منتهية — خطتا الوكيل (id 1 و2) والفرص الأربع والكلمات الـ12 كلها ضمن مهلة 14 يوماً وآخر مسح كلمات 03:51 EET. (4) الاعتمادات: لا شيء معلّق. (5) بريفات الجمهور: 3 عناصر مسودة — مراجعة دورية فقط، النشر ممنوع (Draft-only). لا إجراء خارجي نُفّذ ولا قرار مطلوب من المالك.',1795053744164);
INSERT INTO activity_events VALUES(142,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Bubblzz» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795054204921);
INSERT INTO activity_events VALUES(143,'العمليات','Loop Tick','تيك اللوب 04:09 EET (19 نوفمبر): runlooptick نفّذ مسح المنافس الدوري «Bubblzz» (دوره النهارده، منافس واحد في الجولة) وسجّله كجولة سوق؛ بريفات الجمهور/تقويم المحتوى 3 عناصر مسودة — مراجعة دورية فقط، النشر ممنوع (Draft-only). لا اقتراحات منتهية الصلاحية (TTL 14 يوم؛ أحدث الفرص 18–19 نوفمبر). لا موافقات معلّقة. لا عناصر عمل مستحقة (أقرب استحقاق 21 نوفمبر). تعليمات المالك (2) نشطة ومحترمة — لا إجراء خارجي.',1795054231286);
INSERT INTO activity_events VALUES(144,'لغة البحث','مسح لغة البحث','مسح لغة البحث 04:10 EET (19 نوفمبر): 12 كلمة مفتاحية، 120 اقتراح من Google Egypt autocomplete — لا اقتراحات جديدة مقارنة بلقطة 03:49 EET. تبديل ترتيب فقط في «سيلوليت» (الافخاذ/بالانجليزي) و«يوريا» (يورياج سيكا/صن بلوك). لا ملاحظات جديدة ولا فرص منتجات جديدة. الفرص الأربع القائمة كما هي.',1795054295481);
INSERT INTO activity_events VALUES(145,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Bubblzz» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795054807000);
INSERT INTO activity_events VALUES(146,'التشغيل والتعلم','Loop Tick','Tick 04:19 EET (loop run id 37): runlooptick نفّذ مسح المنافس الدوري «Bubblzz» (دوره النهارده) وسجّله كجولة؛ بريفات الجمهور/تقويم المحتوى 3 عناصر مسودة — مراجعة دورية فقط، النشر ممنوع. قائمة المهام: مهمة واحدة (بحث سوق دوري Hepta/Alejon/Soralone/Centevia) بلا تاريخ استحقاق — جزؤها الآلي مغطى بمسح التدوير. بنود الشغل: لا بند مستحق (أقرب استحقاق 2026-11-21). لا اقتراحات منتهية (خطتا Agent المقترحتان عمرهما < يوم، TTL 14 يوم). لا اعتمادات معلّقة. تعليمات المالك النشطة (2) مُراعاة — لا تنفيذ خارجي ولا تصميم بصري في التيك. مؤشر التدوير متسق: التيك وgetopsstate يسمّيان Bubblzz التالي.',1795054849988);
INSERT INTO activity_events VALUES(147,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Bubblzz» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795055395118);
INSERT INTO activity_events VALUES(148,'Operations','Loop Tick','Tick 04:29 EET 19-11-2026: runlooptick نفّذ المسح الدوري لمنافس اليوم «Bubblzz» (جولة مسجلة) + مراجعة بريفات الجمهور/تقويم المحتوى (3 عناصر مسودة، Draft-only، لا نشر). مهمة بحث السوق الدوري (id 1) ما زالت New. لا موافقات معلّقة. لا اقتراحات منتهية الصلاحية (TTL 14 يوم؛ الفرص الأربع قيد الدراسة من 18–19 نوفمبر). لا عناصر عمل مستحقة اليوم (أقرب استحقاق 2026-11-21). تعليمات المالك 1 و2 نشطة ومحترمة. لا شيء يحتاج قرار أحمد في هذا الـ tick.',1795055415549);
INSERT INTO activity_events VALUES(149,'تفكير زيرا وقراراتنا','مراجعة المستشار',replace('مراجعة المستشار 19 نوفمبر 04:29 EET. المصادر: لوحة السيستم + 8 تنبيهات + 26 ملاحظة + مسح لغة بحث 04:10 EET. النافذة: 18–19 نوفمبر. الحداثة 🟢 <ساعة.\n\nما تغيّر: (1) ضغط سعري جديد على KP: Alejon يوريا 10% عبوة 500مل جديدة بـ660 ج مع B2G2 (فعّال 330 ج)؛ Melano يورّم Uremel 20% بـB1G1 (فعّال 175 ج) — B1G1 غير مذكور بصفحة المنتج، يحتاج تحقق. (2) مسح 04:10: لا اقتراحات جديدة. (3) التدوير شغال بلا أعطال. (4) لا موافقات معلّقة؛ أقرب استحقاق 21 نوفمبر (Cold Start) ثم 24 نوفمبر (اعتماد الإطلاق + فحص AEO + مدخلات Bosta).\n\nالمعنى: الضغط السعري يتصاعد في White Friday، لكن تموضع زيرا (يوريا 25% + روتين 799 ج) لم يتغيّر — المنافسون يبيعون كريم منفرد بتركيز أقل، لا روتين. لا خطر يغيّر الإطلاق.\n\nالثقة 85% في اتجاه الضغط؛ B1G1 على Uremel غير مؤكد. الأثر: لا تغيير في بوابات CPP (هدف ≤150–160، سقف 180، تعادل 275).\n\nأهم إجراء تالٍ: أحمد يحدّد ميزانية الاختبار لكل روتين + يوثّق رسوم Bosta ونسب التأكيد/التسليم قبل 24 نوفمبر — بدونها لا اعتماد للإطلاق ولا حساب تعادل فعلي. لا قرار مطلوب قبل الملخص اليومي.','\n',char(10)),1795055478076);
INSERT INTO activity_events VALUES(150,'لغة البحث','مسح لغة البحث','مسح لغة البحث 04:30 EET: 12 كلمة مفتاحية، 120 اقتراح — لا اقتراحات جديدة (0). تبديل ترتيب فقط في «علاج جلد الوزة» (من الصيدلية نزلت للمركز 9) و«مخمرية» (مخمرية / العود الملكي بدّلوا المركزين 1–2). لا ملاحظات جديدة ولا فرص منتج جديدة.',1795055502126);
INSERT INTO activity_events VALUES(151,'المحتوى والكرييتف','تحديث بريفات الجمهور','تحديث دوري كل 6 ساعات 19-11-2026 04:29 EET: راجعت insights (فارغة — لا صوت عميلة مباشر مسجل بعد)، تعلّم واحد (V4 ستاتيك)، 26 ملاحظة (أحدثها لغة بحث 03:49 EET + عرض Melano B1G1)، وتعليمتي المالك 1 و2. تغيير جوهري منذ كتابة البريفات 02:32 EET: بريف السيلوليت كان بيسقط صابونة الكولاجين (مخالف لتعليمة المالك 1 — الروتين 3 قطع إلزامي)، وبريفات KP كانت ناقصة زاوية جفاف الشتا الإلزامية ولغة البحث الجديدة. حدّثت 3 مسودات (سيلوليت 1، يوريا 2، KP 3) — كل واحدة: مين هي، كلامها، اعتراضاتها، الدليل المطلوب، زاوية القيادة — بثقة متوسطة (لغة بحث + عصر منافسين). مسودة فقط — لا نشر.',1795055544911);
INSERT INTO activity_events VALUES(152,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Bubblzz» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795055988625);
