INSERT INTO activity_events VALUES(154,'العمليات','Loop Tick','تكة 04:39 EET: runlooptick سمّى Bubblzz (رابع تكة متتالية عليه من غير جولة مسجلة) — نُفّذ المسح فعلياً من مصادر عامة وسُجّل كجولة سوق رقم 22: لا تغيير جوهري في التموضع (عناية جسم معطرة، بلا KP/سيلوليت/يوريا)؛ سكراب الفانيليا 250 جم 290 EGP على Tallah (+40 عن اللقطة)، سبلاشات 327 EGP على جوميا. لا موافقات معلقة؛ لا اقتراحات منتهية (كل الفرص ضمن TTL 14 يوم)؛ لا عناصر عمل مستحقة اليوم.',1795056070404);
INSERT INTO activity_events VALUES(155,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Norshek» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795056591838);
INSERT INTO activity_events VALUES(156,'لغة البحث','مسح لغة البحث','مسح جوجل مصر 19 نوفمبر 04:50 EET: 12 كلمة، 120 اقتراح، بدون أخطاء. اقتراح جديد واحد: «زبدة الشيا الاصلية» (بدل «زبدة الشيا للبشرة») — سُجّل كملاحظة (id 27) وفرصة منتج (id 5). ترتيب بس اتغير في «علاج جلد الوزة» و«سيلوليت» و«مخمرية». باقي الكلمات مطابقة تماماً.',1795056708023);
INSERT INTO activity_events VALUES(157,'لغة البحث','تصحيح مسح لغة البحث','تصحيح لمسح 04:50 EET: فرصة المنتج «زبدة شيا أصلية/خام» (id 5) حُذفت بعد المراجعة — «زبدة الشيا الاصلية» صفة أصالة على مكوّن موجود أصلاً عند زيرا، وليست منتجاً جديداً لا تحمله (سابقة مسجلة في الملاحظتين 3 و13). الاقتراح يبقى مسجّلاً كملاحظة (id 27) كمؤشر قلق أصالة في لغة البحث، والفرص القائمة تفضل 4 فقط: يوريا 30%، رول سيلوليت، الشعر تحت الجلد، جلد الوزة في الوجه.',1795056741207);
INSERT INTO activity_events VALUES(158,'Market Watch','جولة متابعة','norshek.com — المتجر الرسمي (فحص حي 2026-11-19 04:51–04:58 EET): مسح دوري لمنافس واحد: Norshek — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)',1795057137685);
INSERT INTO activity_events VALUES(159,'التشغيل والتعلّم','Loop Tick','تيك 04:49 EET (جولة تشغيل 40): مسح Norshek الدوري — فحص حي لمتجره الرسمي (04:51–04:58 EET) وسُجّل كجولة سوق 23: لوشن Skin Kin بـ 272 EGP لكنه نافد (مقابل 395 في اللقطة)، ألواح الشامبو/البلسم والصابون ارتفعت أسعارها، لا منتج KP/سيلوليت/يوريا، لا عرض Black Friday، ومنتج جديد واحد (Hairapy Leave-In) نافد. لا موافقات معلّقة ولا اقتراحات منتهية الصلاحية (الخطط والفرص ضمن مهلة 14 يوماً). بريفات الجمهور: 3 عناصر مسودة — مراجعة دورية فقط، النشر ممنوع.',1795057147259);
INSERT INTO activity_events VALUES(160,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Scrubby Bubby Shop» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795057309506);
INSERT INTO activity_events VALUES(161,'العمليات','Loop Tick','تيك 05:01 EET (run id 41): مسح المنافس الدوري Scrubby Bubby Shop (مطابق لمؤشر التدوير في getopsstate)؛ بريفات الجمهور وتقويم المحتوى 3 عناصر مسودة — مراجعة دورية فقط، النشر ممنوع. لا مهام مستحقة في الطابور (المهمة الوحيدة id 1 دورية بلا تاريخ استحقاق)، ولا بنود عمل مستحقة قبل 21-11، ولا موافقات معلّقة، ولا اقتراحات منتهية الصلاحية (آخر مسح كلمات 02:51Z، TTL 14 يوم). تعليمات المالك 1 و2 نشطة وتمت مراعاتها.',1795057347575);
INSERT INTO activity_events VALUES(162,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Scrubby Bubby Shop» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795057793549);
INSERT INTO activity_events VALUES(163,'Operations','Loop Tick','تِك 05:09 EET — runlooptick سجّل جولة التدوير رقم 42: المنافس الدوري «Scrubby Bubby Shop» (دوره النهارده). الفحص الحي للموقع الرسمي جارٍ عبر المتصفح (الموقع لم يُفتح عبر القراءة النصية) وستُسجَّل الجولة فور وصول النتيجة. لا اقتراحات منتهية الصلاحية (الفرص الأربع من 18–19 نوفمبر، TTL 14 يوم). لا موافقات معلّقة. لا عناصر عمل مستحقة قبل 21 نوفمبر. تعليمات المالك (1 و2) نشطة ومُراعاة.',1795057843222);
INSERT INTO activity_events VALUES(164,'لغة البحث','مسح لغة بحث','مسح لغة بحث جوجل مصر 05:10 EET (12 كلمة، 120 اقتراحاً، بلا أخطاء). اقتراح جديد واحد: «علاج السيلوليت عند النساء» (كلمة «علاج السيلوليت»، المركز 10) — وسُجّل كملاحظة سوق id 28؛ ليس فرصة منتج (تقييد ديموغرافي على مشكلة الروتين يغطيها). خرج في نفس المسح الاقتراح العاري «علاج السيلوليت» من قائمته. تبديل ترتيب فقط: «يوريا» (يورياج صن بلوك/سيكا 8–9)، «مخمرية» (نفس تبديلات الجولات السابقة). باقي 9 كلمات مطابقة تماماً لمسح 04:50 EET.',1795057878121);
INSERT INTO activity_events VALUES(165,'Market Watch','جولة متابعة','scrubbybubbyshop.com (معطّل — DNS) + Beauty Bounty — فحص حي 2026-11-19 05:10–05:12 EET: مسح دوري لمنافس واحد: Scrubby Bubby Shop — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)',1795057986425);
INSERT INTO activity_events VALUES(166,'Market & Competitors','Market Round','اكتمل مسح التِك: جولة سوق رقم 24 لـ «Scrubby Bubby Shop» مسجّلة — الموقع الرسمي معطّل (DNS غير موجود، فحص حي 05:10–05:12 EET)، وعلى Beauty Bounty منتج واحد فقط: شاور جل Strawberry Sorbet 300 جم بـ 150 EGP ومتاح، وسكراب Candy Jam (60 EGP) لم يعد ظاهراً على القناة. لا تموضع KP/سيلوليت/يوريا ولا عرض موسمي. ملاحظة سوق على نفس القناة: كريمات يوريا جديدة متموضعة لجلد الوزة (Vee Allure 10% بـ 249 EGP، Soralone 15% بـ 245 EGP، Miss Je Lu بـ 390 EGP) ومنتجات سيلوليت Areej (360–450 EGP) — تستحق التتبع كمنافسين محتملين.',1795058001031);
INSERT INTO activity_events VALUES(167,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Raw African» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795058387577);
