INSERT INTO activity_events VALUES(193,'التشغيل والتعلّم','Loop Tick','تيك 10 دقايق 06:29 EET: تشغيل runlooptick — مسح المنافس الدوري «Kyra Naturals» (دوره النهارده) + مراجعة بريفات الجمهور/تقويم المحتوى (3 عناصر مسودة، Draft-only، بلا نشر). لا مهام مستحقة الآن (أقرب استحقاق بند شغل 3 بتاريخ 21-11)؛ لا موافقات معلّقة؛ لا اقتراحات منتهية (TTL 14 يوم — الخطط المقترحة والفرص كلها من 18–19 نوفمبر). تعليمات المالك 1 و2 سارية ولم يُتخذ أي إجراء خارجي.',1795062636138);
INSERT INTO activity_events VALUES(194,'تفكير زيرا وقراراتنا','مراجعة المستشار الساعية','مراجعة المستشار 06:29 EET 19-11. ما تغيّر: مسح لغة بحث 06:10 — 12 كلمة، 120 اقتراح، صفر جديد؛ تيك اللوب 06:19 (run #49) مسح Kyra Naturals ومتسق مع getopsstate؛ تحليلان جديدان لإعلان منافس. لا تنبيهات جديدة منذ 02:40 (Alejon يوريا 500مل) و02:30 (Melano B1G1). المفتوح: 8 تنبيهات منافس (كلها New)، صفر موافقات معلقة، تعلّم واحد معلّق (سيت V4)، مهمة طابور واحدة New، 14 عنصر عمل وأقرب استحقاق 21-11. ماذا يعني: لا خطر حرج على الإطلاق؛ ضغط الأسعار على كريمات KP المنفردة يتصاعد (Alejon 500مل بسعر فعّال 330، Uremel B1G1 بسعر فعّال 175) — يعزّز تموضع «روتين يوريا 25% بـ799» مقابل كريم منفرد، ولا يستدعي تغيير سعر زيرا. أهم إجراء تالٍ: قرار أحمد على ميزانية الاختبار لكل روتين + اعتماد بريف المصمم قبل 25-11، وتثبيت رسوم Bosta الفعلية (عنصر عمل 1، مستحق 24-11). ملاحظة جودة: أحداث 189–191 موسومة «تحليل إعلان منافس» وهي ملاحظات لغة بحث. المصادر: لوحة المساحة + التنبيهات + الملاحظات + النشاط + opsstate. النافذة 05:29–06:29 EET، حداثة <1س. ثقة عالية. الأثر: لا تغيير في خطة الإطلاق.',1795062639213);
INSERT INTO activity_events VALUES(195,'Thinking','تفكير جديد','اتولدت 3 مدخلات تفكير من بيانات النظام الحالية (2026-11-19)',1795062656412);
INSERT INTO activity_events VALUES(196,'لغة البحث','مسح اقتراحات جوجل مصر','مسح اقتراحات جوجل مصر 06:30 EET — 12 كلمة، 120 اقتراح، صفر اقتراحات جديدة مقارنة بلقطة 06:10. تغيير ترتيب فقط في كلمة واحدة (يوريا: «يورياج صن بلوك» 9→8 و«يورياج سيكا» 8→9). لا ملاحظات ولا فرص منتج جديدة.',1795062695871);
INSERT INTO activity_events VALUES(197,'Market Watch','جولة متابعة','Source Beauty — فحص حي 2026-11-19 06:30 EET: مسح دوري لمنافس واحد: Kyra Naturals — السعر والتوفر والعرض (سيلوليت + جلد الوزة/يوريا)',1795062994623);
INSERT INTO activity_events VALUES(198,'السوق والمنافسين','مسح منافس دوري','جولة مسح دوري للمنافس Kyra Naturals (دوره اليوم حسب مؤشر التدوير — أول جولة مسجلة له): فحص حي لـ Source Beauty 06:30–06:34 EET — البراند اختفى تماماً من المنصة (صفر منتج، صفحة فارغة، رابط قديم 404). سُجلت جولة سوق (id 27) + ملاحظة موثقة (id 29) + تنبيه منافس (id 9). لا منتج جديد ولا عرض ولا حركة سعرية من Kyra على هيروين زيرا — لا تنبيه شات للمالك.',1795063025939);
INSERT INTO activity_events VALUES(199,'Ops & Learning','لوب: Tick','مسح المنافس الدوري التالي: «Naturelle» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور وتقويم المحتوى: 3 عنصر مسودة — التحديث الدوري (كل 6 ساعات) بيراجع المسودات بس؛ النشر ممنوع (Draft-only).',1795063192918);
INSERT INTO owner_instructions VALUES(1,'قواعد أحمد لتصميم الستاتيك المدفوع (2026-11-19)','تعليمات المالك الملزمة لأي ستاتيك مدفوع: (1) كل تصميم تمبلت وتكوين مختلف فعلياً على مستوى الليアウト — اختلاف الديكور جوه نفس الهيكل لا يُحتسب اختلافاً. (2) كل تصميم فيه هوك بصري قوي أو صورة Clue للمشكلة نفسها (ملمس جلد الوزة/السيلوليت) — الصور دي مسموحة ومطلوبة لرفع CTR. (3) ممنوع زحمة العناصر تحت: السعر والـ CTA والحل موزعين بأبعاد مظبوطة ومساحات فاضية مريحة. (4) كلام قليل ومقنع وطبيعي — ممنوع نصوص ملهاش لازمة. (5) روتين السيلوليت 3 قطع دايماً في أي ذكر: صابونة كولاجين + سكراب كافيين + كريم ريتينول بالليل — ممنوع نسيان الصابونة. (6) ممنوع كلمة «محرجاكي» وأي هوك فيه إحراج/شيمينج. (7) ممنوع مصطلحات فصحى بعيدة عن كلام العميلة: «العناية الموضعية» تتبدل بـ «سكراب وكريم». (8) زاوية جفاف الشتا لجلد الوزة زاوية أساسية موسمية — فحص موسمية إلزامي قبل اعتماد أي سيت زوايا. (9) الهدف: أعلى CTR وتنوع حقيقي يفهمه Andromeda — لا التزام حرفي بأول بريف لو فيه نسخة أقوى.','الكرييتف / الستاتيك المدفوع',1,1795050445006,1795050445006);
INSERT INTO owner_instructions VALUES(2,'تقسيم أدوار الكرييتف (قرار أحمد 2026-11-19)','قرار المالك: دور Muse في الكرييتف = الزوايا والأنجلز والهوكات والكوبي المعتمد + بريف صغير للمصمم (أو كذا بريف لنفس الفكرة باتجاهات بصرية مختلفة). التصميم البصري النهائي مش دور Muse — بيتنفذ عند مصمم بشري من البريف. ممنوع تقديم رندرات Muse كتصميمات نهائية للمالك؛ أي إنتاج بصري من Muse يبقى موك أب توضيحي للبريف فقط ويتقدم على إنه كده.','الكرييتف / الإنتاج البصري',1,1795050701754,1795050701754);
