INSERT INTO product_opportunities VALUES(1,'طلب بحث على يوريا 30% — أعلى من بطل زيرا (25%)','طلبات عملاء','اقتراحات جديدة في مسح جوجل مصر 19 نوفمبر 01:51 EET: «يوريا 30»، «يوريا ٣٠٪»، «كريم يوريا ٣٠ للجسم» — باحثون بيدوّروا على يوريا 30%، أعلى من لوشن زيرا الحالي (يوريا 25%، الأعلى المعلن في السوق). الطلب على تركيز أعلى ظاهر في لغة البحث نفسها.','قيد الدراسة','زيرا لا تحمل منتج يوريا 30% حالياً — البطل الحالي يوريا 25%. الفكرة للدراسة مع أحمد: منتج/تركيز أعلى كخطوة تالية، أو محتوى يوضح ليه 25% هو التركيز المناسب للاستخدام اليومي. لا قرار إنتاج من غير موافقة المالك.',1795046088313);
INSERT INTO product_opportunities VALUES(2,'رول/أداة تدليك للسيلوليت — طلب بحث ظاهر وزيرا لا تحمل أداة','طلبات عملاء','اقتراح جديد في مسح جوجل مصر 19 نوفمبر 01:51 EET: «سيلوليت رول امازون»، مع بقاء «سيلوليت رول / رولر / رول نون» في الاقتراحات — باحثون بيدوّروا على رول/أداة تدليك للسيلوليت وبيشتروها من أمازون/نون.','قيد الدراسة','زيرا عندها سكراب + كريم للسيلوليت لكن لا تحمل أداة رول/تدليك. الفكرة للدراسة مع أحمد: رول سيلوليت كإضافة/أكسسوار لروتين السيلوليت (799 ج). لا قرار شراء/إنتاج من غير موافقة المالك.',1795046088330);
INSERT INTO product_opportunities VALUES(3,'الشعر تحت الجلد — مشكلة مرتبطة بجلد الوزة ظهرت في لغة البحث','طلبات عملاء','اقتراح جديد في مسح جوجل مصر 19 نوفمبر 02:30 EET: «علاج جلد الوزة والشعر تحت الجلد» ضمن اقتراحات «علاج جلد الوزة» — باحثون بيربطوا علاج جلد الوزة بمشكلة الشعر تحت الجلد.','قيد الدراسة','زيرا لا تحمل منتج/تموضع مخصص للشعر تحت الجلد حالياً؛ روتين KP (يوريا 25% + سكراب) قد يعالج المشكلة ضمناً. الفكرة للدراسة مع أحمد: محتوى يربط روتين KP بالشعر تحت الجلد، أو تموضع/منتج مخصص. لا قرار إنتاج/محتوى من غير موافقة المالك.',1795048393162);
INSERT INTO product_opportunities VALUES(4,'جلد الوزة في الوجه — منطقة بحث جديدة وزيرا لا تحمل منتج وجه مخصص','طلبات عملاء','اقتراح جديد في مسح جوجل مصر 19 نوفمبر 03:11 EET: «علاج جلد الوزة في الوجه» ضمن اقتراحات «علاج جلد الوزة» — باحثون بيدوّروا على علاج جلد الوزة في الوجه، مش الجسم بس.','قيد الدراسة','زيرا لا تحمل منتج/تموضع مخصص لجلد الوزة في الوجه حالياً؛ روتين KP الحالي للجسم (يوريا 25% + سكراب + ريتينول ليلي) غير مخصص للوجه. الفكرة للدراسة مع أحمد: محتوى يوضح حدود روتين الجسم على الوجه، أو منتج/تركيبة وجه لاحقاً. لا قرار إنتاج/محتوى من غير موافقة المالك.',1795050756116);
INSERT INTO loop_runs VALUES(1,'Tick','مسح المنافس الدوري التالي: «Hayah — Urepar» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة. بريفات الجمهور: لا مسودات محتوى بعد — التحديث الدوري (كل 6 ساعات) هيلاقيها فاضية لحد ما تتكتب مسودات.',replace('مسح المنافس الدوري التالي: «Hayah — Urepar» — دوره النهارده (منافس واحد في الجولة، كل منافس مرة يومياً). نفّذ المسح من متابعة السوق وسجّله كجولة.\nبريفات الجمهور: لا مسودات محتوى بعد — التحديث الدوري (كل 6 ساعات) هيلاقيها فاضية لحد ما تتكتب مسودات.','\n',char(10)),1795034976447);
