INSERT INTO organic_posts VALUES(1,'S1 — هوك الريتينول للجسم','','انستجرام','هوك الريتينول للجسم: كريم السيلوليت (ريتينول + كافيين + نياسيناميد) — 350 ج بدل 400','Static',1,'«الريتينول اللي في روتين وشك.. ليه مش في جسمك؟» كريم السيلوليت (ريتينول+كافيين+نياسيناميد) 350/400','منتج','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038210312,1795038210312);
INSERT INTO organic_posts VALUES(2,'S6 — طبقات العطر','','انستجرام','طبقات العطر: 3 طبقات من نفس الريحة (لوف + مخمرية + سبلاش)','Static',1,'طبقات العطر — 3 طبقات من نفس الريحة (صابونة لوف ورد + مخمرية + سبلاش Midnight Bloom). سبلاش 240، مخمرية 199','تعليمي','مسودة','','','','',1795038215494,1795038215494);
INSERT INTO organic_posts VALUES(3,'S5 — روتين جلد الوزة','','انستجرام','روتين جلد الوزة: حبيبات الدراع ونقط الرجل بعد الشيفينج — 799 ج بدل 1,020','Static',1,'روتين جلد الوزة — حبيبات الدراع ونقط الرجل بعد الشيفينج، روتين واحد (سكراب + لوشن يوريا 25% + شيا) 799/1,020','مشكلة وحل','مسودة','','','','',1795038215543,1795038215543);
INSERT INTO organic_posts VALUES(4,'S3 — لوشن جلد الوزة يوريا 25%','','انستجرام','لوشن جلد الوزة: يوريا 25% + لاكتيك أسيد + بانثينول + زبدة شيا — 360 ج بدل 400','Static',1,'لوشن جلد الوزة — يوريا 25% + لاكتيك أسيد + بانثينول + زبدة شيا، 200جم، 360/400','منتج','مسودة','','','','',1795038215573,1795038215573);
INSERT INTO organic_posts VALUES(5,'S4 — روتين السيلوليت في 3 خطوات','','انستجرام','روتين السيلوليت في 3 خطوات — 799 ج بدل 975','Static',1,'روتين السيلوليت في 3 خطوات (صابونة كولاجين ← سكراب كافيين ← كريم ريتينول بالليل) 799/975','تعليمي','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038215594,1795038215594);
INSERT INTO organic_posts VALUES(6,'S2 — روتين السيلوليت قبل/بعد مع الانتظام','','انستجرام','روتين السيلوليت قبل/بعد «مع الانتظام» — الروتين 799 ج بدل 975','Static',1,'روتين السيلوليت قبل/بعد «مع الانتظام». الروتين 799/975','مشكلة وحل','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038215616,1795038215616);
INSERT INTO organic_posts VALUES(7,'C1 — تعريف البراند والعودة إحنا زيرا','','انستجرام','تعريف البراند والعودة: «إحنا زيرا وبنقولك الحقيقة»','Carousel',8,'تعريف البراند والعودة «إحنا زيرا وبنقولك الحقيقة»: بنبدأ من المشكلة، مواد فعالة (شيا غانا، ملح سيوة، يوريا 25%، ريتينول وكافيين)، خطوات مدروسة، من غير وعود بمعجزات، وقفنا البيع بإرادتنا ورجعنا، دفع عند الاستلام + 14 يوم إرجاع','تعريف بالبراند','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','📌 بوست مثبت',1795038220393,1795038220393);
INSERT INTO organic_posts VALUES(8,'S7 — عناية الجسم مش تقشير بس','','انستجرام','عناية الجسم مش تقشير بس: سكراب سيوة + لوف + شيا — السكراب 390 ج بدل 450','Static',1,'عناية الجسم مش تقشير بس — تقشير من غير ترطيب = جلد مشدود؛ سكراب ملح سيوة أسبوعي + لوف + شيا. سكراب سيوة 390/450','تعليمي','مسودة','','','','',1795038220421,1795038220421);
INSERT INTO organic_posts VALUES(9,'S10 — سبلاش ولا مخمرية ولا الاتنين','','انستجرام','سبلاش ولا مخمرية ولا الاتنين: سبلاش 240 ج / مخمرية 199 ج','Static',1,'سبلاش ولا مخمرية ولا الاتنين — سبلاش 240 (100مل، 10 روائح، كحول قليل)، مخمرية 199 (شيا، 8 روائح)؛ الثبات الأطول: مخمرية الأول وسبلاش فوقها من نفس الريحة','منتج','مسودة','','','','',1795038220448,1795038220448);
INSERT INTO organic_posts VALUES(10,'S8 — خلي روتين وشك أبسط','','انستجرام','خلي روتين وشك أبسط: تنظيف ألطف + تونر — التونر 350 ج بدل 400','Static',1,'خلي روتين وشك أبسط — تنظيف ألطف صبح وليل + تونر (تونر الورد والخيار 350/400 + صابون فحم وصبار)','تعليمي','مسودة','','','','',1795038220463,1795038220463);
INSERT INTO organic_posts VALUES(11,'S9 — دليل الـ 3 سكرابات بملح سيوة','','انستجرام','دليل الـ 3 سكرابات بملح سيوة: سيوة 390 / جلد الوزة 440 / سيلوليت 450','Static',1,'دليل الـ 3 سكرابات بملح سيوة — سيوة 390 (عناية أسبوعية، 5 روائح، 1-2 مرة/أسبوع)، جلد الوزة 440 (مرة/أسبوع ثم 2-3)، سيلوليت 450 (كافيين، في الشاور وبعده الكريم بالليل). التلاتة للجسم بس ومش بعد الشيفينج مباشرة','تعليمي','مسودة','','','','',1795038220475,1795038220475);
INSERT INTO organic_posts VALUES(12,'C3 — ليه تطلبي من زيرا؟','','انستجرام','«ليه تطلبي من زيرا؟» — الرد على مخاوف أول طلب','Carousel',9,'«ليه تطلبي من زيرا؟» رد على مخاوف أول طلب: إرجاع 14 يوم وفق شروط السياسة، دفع عند الاستلام، مساعدة في اختيار الروتين، المكونات مكتوبة على صفحة كل منتج، طريقة استخدام خطوة بخطوة، توقعات صادقة والنتائج بتختلف','ثقة','مسودة','','🚩 سلايد 8: وعد شحن مجاني من تاني أوردر غير مؤكد — لا يُكرر في الكابشن','','📌 بوست مثبت',1795038224811,1795038224811);
INSERT INTO organic_posts VALUES(13,'C4 — 5 غلطات في روتين السيلوليت','','انستجرام','«5 غلطات في روتين السيلوليت» وتصحيحها — الروتين 799 ج بدل 975','Carousel',10,'«5 غلطات في روتين السيلوليت»: مش عشان التخن، الفرك الجامد بيهيج، الكريم من غير سكراب الأول، الكريم الصبح من غير واقي (ريتينول بالليل + ممنوع في الحمل)، والبطولة بعد أسبوع. الخلاصة: صابونة كولاجين + سكراب كافيين + كريم ريتينول — 799/975','تعليمي','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات','','',1795038224838,1795038224838);
INSERT INTO organic_posts VALUES(14,'C2 — لو عندك المشكلة دي ده روتينك','','انستجرام','«لو عندك المشكلة دي ده روتينك» — 8 روتينات','Carousel',10,'«لو عندك المشكلة دي ده روتينك»: 8 روتينات (سيلوليت 799، جلد الوزة والفراولة 799، بشرة دهنية، بشرة جافة 599، بشرة باهتة، سيوة الأسبوعي 700، Signature Scent، كيت الساحل). ختام: ابعتلنا اللي مضايقك ونرشحلك + COD + 14 يوم','مشكلة وحل','مسودة','','⚠️ ريتينول — التنبيه الإلزامي موجود في الكابشنات | 🚩 سلايد 9 (كيت الساحل): الهيدلاين مكرر ومتلخبط ويحتاج إعادة صياغة قبل النشر','','📌 بوست مثبت',1795038224865,1795038224865);
INSERT INTO organic_posts VALUES(15,'C5 — 4 غلطات بتزود جلد الوزة','','انستجرام','«4 غلطات بتزود جلد الوزة» وتصحيحها — الروتين 799 ج بدل 1,020','Carousel',9,'«4 غلطات بتزود جلد الوزة»: ليفة جامدة كل يوم، مرطب عادي وخلاص (اليوريا بتليّن الخشن)، ترتيب السكراب واللوشن، لوشن بعد الشيفينج على طول (استني 24-48 ساعة). الخلاصة: سكراب جلد الوزة + لوشن يوريا 25% + شيا مكررة — 799/1,020','تعليمي','مسودة','','🚩 سلايد 7: مكتوب «سكراب الكافيين» خطأً — الصح سكراب جلد الوزة | 🚩 سلايد 9 مفقودة في الترقيم (يقفز من 8 إلى 10)','','',1795038224879,1795038224879);
INSERT INTO organic_captions VALUES(1,1,3,'بيع ناعم وCTA',replace('لو مظهر السيلوليت مضايقك، ابدئي بخطوة واحدة صح: كريم السيلوليت بالريتينول والكافيين والنياسيناميد، 350 ج بدل 400.\nولو عايزة الروتين الكامل (سكراب + كريم + صابونة) هتلاقيه بـ 799 ج بدل 975.\nاطلبي من اللينك في البايو، والدفع عند الاستلام.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة، ويُستخدم بالليل فقط.\n#سيلوليت #عناية_بالجسم #زيرا','\n',char(10)),'مسودة',1795038232696,1795038232696);
INSERT INTO organic_captions VALUES(2,1,2,'تفاعلي',replace('سؤال سريع: آخر مرة اهتميتي بجلد جسمك زي وشك كانت إمتى؟\nالريتينول مش للوش بس. كريم السيلوليت بتاعنا بيجمع ريتينول وكافيين ونياسيناميد في خطوة واحدة بالليل، وهدفه مظهر وملمس أنعم تدريجياً.\nاحفظي البوست وارجعيله وإنتي بتظبطي روتينك.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #روتين_الجسم #ZyraCare','\n',char(10)),'مسودة',1795038232711,1795038232711);
INSERT INTO organic_captions VALUES(3,1,1,'تعليمي/قيمة',replace('بتحطي ريتينول في روتين وشك عشان ملمسه ونضارته.. طب وجسمك؟\nكريم السيلوليت من زيرا فيه ريتينول + كافيين + نياسيناميد، وبيشتغل على مظهر السيلوليت وملمس الجلد مع الانتظام في الاستخدام بالليل.\nسعره لوحده 350 ج بدل 400.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة، وبيتحط بالليل بس.\n#سيلوليت #عناية_بالجسم #زيرا','\n',char(10)),'مسودة',1795038232730,1795038232730);
INSERT INTO organic_captions VALUES(4,6,3,'بيع ناعم وCTA',replace('روتين السيلوليت الكامل بـ 799 ج بدل 975، ومكوناته لوحدها أغلى من كده.\nسكراب كافيين + كريم ريتينول وكافيين ونياسيناميد + صابونة كولاجين وبذور العنب.\nابدئي النهارده وخلي الانتظام هو سرك. الدفع عند الاستلام ومن حقك ترجعي خلال 14 يوم.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #ZyraCare #عناية_بالجسم','\n',char(10)),'مسودة',1795038239805,1795038239805);
INSERT INTO organic_captions VALUES(5,6,2,'تفاعلي',replace('«مع الانتظام» دي أهم كلمتين في أي روتين.\nمفيش منتج بيشتغل من مرة واحدة، بس في روتين خطواته صح: تقشير ناعم، ترطيب، وكريم فعال بالليل.\nقولي لنا في الكومنتات: أكتر حاجة بتوقعك من أي روتين إيه؟\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #روتين_الجسم #زيرا','\n',char(10)),'مسودة',1795038239820,1795038239820);
INSERT INTO organic_captions VALUES(6,6,1,'تعليمي/قيمة',replace('الفرق بين الصورتين مش فلتر.. الفرق انتظام.\nروتين السيلوليت: سكراب الكافيين في الشاور، وكريم الريتينول بالليل، وصابونة الكولاجين للتنضيف. الملمس بيتحسن تدريجياً، والمظهر بياخد أسابيع وبيختلف من واحدة للتانية — دي الحقيقة من غير مبالغة.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #قبل_وبعد #عناية_بالجسم','\n',char(10)),'مسودة',1795038239833,1795038239833);
INSERT INTO organic_captions VALUES(7,4,2,'تفاعلي',replace('اعملي اختبار سريع: مرري إيدك على دراعك من بره.. حسيتي بحبيبات صغيرة وخشنة؟\nدي علامة جلد الوزة المشهورة، والشتا بيخليها تبان أكتر.\nاكتبي لنا في الكومنتات بيظهر عندك فين أكتر: دراع، فخد، ولا مكان تاني؟ وهنتابع معاكي بالحل.\n#جلد_الوزة #زيرا #روتين_الجسم','\n',char(10)),'مسودة',1795038243505,1795038243505);
INSERT INTO organic_captions VALUES(8,4,1,'تعليمي/قيمة',replace('دراعك لما تلمسيه زي الرملة؟ ده جلد الوزة، والتعامل معاه بيبدأ من المكونات الصح.\nلوشن جلد الوزة من زيرا: يوريا 25% بتليّن الجلد الخشن، ولاكتيك أسيد بيقشر بلطف، وبانثينول وزبدة شيا للترطيب والتهدئة.\nحجمه 200 جم وسعره 360 ج بدل 400.\n#جلد_الوزة #يوريا #عناية_بالجسم','\n',char(10)),'مسودة',1795038243521,1795038243521);
INSERT INTO organic_captions VALUES(9,4,3,'بيع ناعم وCTA',replace('لوشن جلد الوزة لوحده 360 ج، ولو عندك الحبيبات في أكتر من مكان خدي الروتين الكامل: سكراب جلد الوزة + اللوشن + زبدة الشيا المكررة بـ 799 ج بدل 1,020 (ومكوناته لوحدها بـ 1,050).\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#جلد_الوزة #يوريا25 #عناية_بالجسم','\n',char(10)),'مسودة',1795038243534,1795038243534);
INSERT INTO organic_captions VALUES(10,5,3,'بيع ناعم وCTA',replace('3 منتجات، روتين واحد، 799 ج بدل 975.\nصابونة الكولاجين وبذور العنب + سكراب الكافيين وملح سيوة + كريم الريتينول والكافيين والنياسيناميد.\nاطلبي الروتين من اللينك في البايو، تدفعي لما يوصلك، ومعاكي 14 يوم للاسترجاع.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #زيرا #روتين_الجسم','\n',char(10)),'مسودة',1795038247963,1795038247963);
INSERT INTO organic_captions VALUES(11,5,2,'تفاعلي',replace('أكبر غلطة في روتين السيلوليت؟ تحطي الكريم وخلاص.\nالجلد لازم يتجهز الأول: تنضيف، وبعدين تقشير ناعم، وبعدين الكريم بالليل. كده كل منتج بيشتغل في مكانه الصح.\nاحفظي الترتيب ده وابعتيه لصاحبتك اللي بتشتكي من السيلوليت.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #عناية_بالجسم #ZyraCare','\n',char(10)),'مسودة',1795038247982,1795038247982);
INSERT INTO organic_captions VALUES(12,5,1,'تعليمي/قيمة',replace('روتين السيلوليت في 3 خطوات، وكل خطوة ليها دور:\n1) صابونة الكولاجين: تنضيف.\n2) سكراب الكافيين: تقشير ناعم في الشاور.\n3) كريم الريتينول: بالليل بس.\nلما الترتيب يبقى صح، النتيجة تبقى أوضح. الروتين كامل 799 ج بدل 975.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #روتين_الجسم #زيرا','\n',char(10)),'مسودة',1795038247996,1795038247996);
INSERT INTO organic_captions VALUES(13,3,1,'تعليمي/قيمة',replace('حبيبات في دراعك ونقط في رجلك بعد الشيفينج؟ الاتنين اسمهم واحد: جلد الوزة وجلد الفراولة، والاتنين ليهم روتين واحد.\nسكراب جلد الوزة مرة في الأسبوع في الأول، لوشن يوريا 25% يومياً، وزبدة الشيا المكررة للترطيب العميق.\nالروتين كامل 799 ج بدل 1,020.\n#جلد_الوزة #جلد_الفراولة #عناية_بالجسم','\n',char(10)),'مسودة',1795038251490,1795038251490);
INSERT INTO organic_captions VALUES(14,3,2,'تفاعلي',replace('مين هنا الحبيبات عندها في الدراع، ومين النقط عندها في الرجل بعد الشيفينج؟\nاكتبي مكانها في الكومنتات وهنقولك تبدئي منين بالظبط في الروتين.\nالمشكلتين دول منتشرين جداً، وليهم خطوات واضحة لو مشيتي عليها بانتظام.\n#جلد_الوزة #شيفينج #زيرا','\n',char(10)),'مسودة',1795038251517,1795038251517);
INSERT INTO organic_captions VALUES(15,3,3,'بيع ناعم وCTA',replace('روتين واحد للاتنين: سكراب جلد الوزة + لوشن يوريا 25% + زبدة شيا مكررة.\nلو خدتيهم لوحدهم هتدفعي 1,050 ج، والروتين بـ 799 ج بس.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#جلد_الوزة #يوريا25 #ZyraCare','\n',char(10)),'مسودة',1795038251539,1795038251539);
INSERT INTO organic_captions VALUES(16,2,3,'بيع ناعم وCTA',replace('ابدئي طبقاتك من هنا: مخمرية كريمي بـ 199 ج وبادي سبلاش 100 مل بـ 240 ج، واختاري نفس الريحة من الاتنين.\nوفيه صابونة لوف بنفس العطر تكمل بيها الثلاثية.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#عطور_الجسم #MidnightBloom #ZyraCare','\n',char(10)),'مسودة',1795038254735,1795038254735);
INSERT INTO organic_captions VALUES(17,2,2,'تفاعلي',replace('ريحتك بتطير بعد ساعة؟ جربي قاعدة الطبقات:\nنفس الريحة في 3 أشكال مختلفة بتثبت أكتر من أي منتج لوحده.\nقولي لنا في الكومنتات: إنتي فريق سبلاش بس، ولا فريق الطبقات الكاملة؟\n#مخمرية #سبلاش #زيرا','\n',char(10)),'مسودة',1795038254750,1795038254750);
INSERT INTO organic_captions VALUES(18,2,1,'تعليمي/قيمة',replace('عايزة الكل يسألك «حاطة إيه؟» السر مش ريحة قوية.. السر طبقات من نفس الريحة.\nصابونة لوف في الشاور، مخمرية كريمي على الجلد، وبادي سبلاش فوقها — وكلهم بنفس العطر زي Midnight Bloom.\nكده الريحة بتثبت وبتفضل معاكي أطول.\n#عطور_الجسم #مخمرية #بادي_سبلاش','\n',char(10)),'مسودة',1795038254763,1795038254763);
INSERT INTO organic_captions VALUES(19,8,3,'بيع ناعم وCTA',replace('سكراب ملح سيوة بـ 390 ج بدل 450، وفيه 5 روائح تختاري منها، ومعاه زبدة الشيا المكررة وصابونة اللوف بيكملوا يوم العناية الأسبوعي لجسمك.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#ملح_سيوة #سكراب #ZyraCare','\n',char(10)),'مسودة',1795038260605,1795038260605);
INSERT INTO organic_captions VALUES(20,8,2,'تفاعلي',replace('اعترفي: آخر مرة رطبتي جسمك بعد السكراب كانت إمتى؟\nالسكراب بيشيل الجلد الميت، بس لو سبتي الجلد من غير ترطيب هيرجع ينشف أسرع.\nاحفظي البوست: سكراب، لوف، شيا — وده ترتيب يوم العناية الأسبوعي.\n#عناية_بالجسم #روتين_الجسم #زيرا','\n',char(10)),'مسودة',1795038260625,1795038260625);
INSERT INTO organic_captions VALUES(21,8,1,'تعليمي/قيمة',replace('تقشير من غير ترطيب = جلد مشدود ومقشر على الفاضي.\nعناية الجسم الصح: سكراب ملح سيوة مرة أو مرتين في الأسبوع، صابونة لوف للتنضيف، وبعدها زبدة شيا تقفل الترطيب.\nالتقشير خطوة.. مش الروتين كله.\n#عناية_بالجسم #ملح_سيوة #زبدة_شيا','\n',char(10)),'مسودة',1795038260639,1795038260639);
INSERT INTO organic_captions VALUES(22,10,1,'تعليمي/قيمة',replace('روتين وشك مش محتاج يبقى معقد عشان يبقى فعال.\nغسيل كتير بمنتجات قوية = جفاف وتهيّج. البديل: تنظيف ألطف صبح وليل بصابونة مناسبة، وبعده تونر الورد والخيار المنعش.\nأبسط.. وأريح لبشرتك.\n#عناية_بالبشرة #روتين_الوجه #زيرا','\n',char(10)),'مسودة',1795038264070,1795038264070);
INSERT INTO organic_captions VALUES(23,10,3,'بيع ناعم وCTA',replace('ابدئي التبسيط من الأساسيات: صابونة فحم نشط أو صابونة ألوفيرا حسب بشرتك، وتونر الورد والخيار بـ 350 ج بدل 400.\nروتين خفيف تقدري تلتزمي بيه كل يوم، وده أهم من أي روتين طويل بيتنسي.\nاطلبي من اللينك في البايو.\n#روتين_الوجه #عناية_بالبشرة #زيرا','\n',char(10)),'مسودة',1795038264084,1795038264084);
INSERT INTO organic_captions VALUES(24,10,2,'تفاعلي',replace('كام منتج في روتين وشك دلوقتي؟ وكام واحد فيهم بشرتك محتاجاه فعلاً؟\nأوقات كتير المشكلة مش في بشرتك، المشكلة في كتر المنتجات القوية ورا بعض.\nاكتبي لنا نوع بشرتك في الكومنتات وهنرشحلك أبسط روتين يبدأ بيه.\n#عناية_بالبشرة #تونر #ZyraCare','\n',char(10)),'مسودة',1795038264099,1795038264099);
INSERT INTO organic_captions VALUES(25,11,2,'تفاعلي',replace('دليلك السريع لاختيار سكرابك:\nجسمك خشن عموماً؟ سكراب ملح سيوة مرة أو مرتين أسبوعياً.\nحبيبات في دراعك؟ سكراب جلد الوزة مرة في الأسبوع في الأول وبعدين 2-3.\nسيلوليت؟ سكراب الكافيين في الشاور وبعده الكريم بالليل.\nاحفظي البوست، هتحتاجيه وإنتي بتختاري.\n#جلد_الوزة #سيلوليت #زيرا','\n',char(10)),'مسودة',1795038266664,1795038266664);
INSERT INTO organic_captions VALUES(26,11,3,'بيع ناعم وCTA',replace('اختاري سكراب مشكلتك: ملح سيوة 390 ج، جلد الوزة 440 ج، السيلوليت 450 ج.\nوكلهم بملح سيوة ومكونات مرطبة زي زبدة الشيا والمانجو وزيت الجوجوبا وجوز الهند حسب نوعه.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#سكراب #ZyraCare #عناية_بالجسم','\n',char(10)),'مسودة',1795038266679,1795038266679);
INSERT INTO organic_captions VALUES(27,11,1,'تعليمي/قيمة',replace('بتستخدمي نفس السكراب لكل جسمك؟ عندنا 3 سكرابات بملح سيوة وكل واحد ليه وظيفة:\nسكراب ملح سيوة: عناية أسبوعية عامة و5 روائح.\nسكراب جلد الوزة: للحبيبات ونقط ما بعد الشيفينج.\nسكراب السيلوليت: بالكافيين لمظهر وملمس الجلد المتموّج.\nوالتلاتة للجسم بس، ومش بعد الشيفينج مباشرة.\n#سكراب #ملح_سيوة #عناية_بالجسم','\n',char(10)),'مسودة',1795038266695,1795038266695);
INSERT INTO organic_captions VALUES(28,9,2,'تفاعلي',replace('معركة كل يوم: سبلاش ولا مخمرية؟\nلو بتحبي الإحساس الخفيف والانتعاش السريع هتروحي للسبلاش، ولو عايزة ترطيب وريحة تقعد هتروحي للمخمرية.\nاكتبي فريقك في الكومنتات.. والذكية اللي بتجمع الاتنين تكتب «الاتنين».\n#مخمرية #سبلاش #زيرا','\n',char(10)),'مسودة',1795038269607,1795038269607);
INSERT INTO organic_captions VALUES(29,9,1,'تعليمي/قيمة',replace('سبلاش ولا مخمرية؟ الإجابة الصح: على حسب إنتي عايزة إيه.\nالسبلاش: ريحة خفيفة ومنعشة، 100 مل، كحول قليل وزيوت فمش بينشف، و10 روائح.\nالمخمرية الكريمي: ريحة وترطيب في خطوة واحدة بزبدة الشيا، قوام كريمي من غير إحساس دهني، و8 روائح.\nوعايزاها تفضل أطول؟ مخمرية الأول وسبلاش فوقها من نفس الريحة.\n#بادي_سبلاش #مخمرية #عطور_الجسم','\n',char(10)),'مسودة',1795038269649,1795038269649);
INSERT INTO organic_captions VALUES(30,9,3,'بيع ناعم وCTA',replace('خدي الاتنين بسعرين أوضح من بعض: بادي سبلاش 100 مل بـ 240 ج، ومخمرية كريمي بـ 199 ج.\nاختاري نفس الريحة وحطي المخمرية الأول وبعدها السبلاش، وهتلاحظي الفرق في الثبات.\nاطلبي من اللينك في البايو والدفع عند الاستلام.\n#عطور_الجسم #ZyraCare #مخمرية','\n',char(10)),'مسودة',1795038269666,1795038269666);
INSERT INTO organic_captions VALUES(31,7,2,'تفاعلي',replace('رجعنا.. وعايزين نبدأها صح المرة دي: من عندك إنتي.\nاسحبي السلايدات واعرفي إحنا مين وبنشتغل إزاي، وبعدين اكتبي لنا في الكومنتات: إيه أكتر مشكلة مضايقاكي في جسمك أو بشرتك دلوقتي؟\nكل تعليق هيتقرأ، وهنرشح لكل واحدة الروتين اللي يناسبها.\n#زيرا #جلد_الوزة #سيلوليت','\n',char(10)),'مسودة',1795038272833,1795038272833);
INSERT INTO organic_captions VALUES(32,7,1,'تعليمي/قيمة',replace('إحنا زيرا.. وبنقولك الحقيقة.\nبراند مصري بيبدأ من المشكلة قبل المنتج: إيه اللي مضايقك بالظبط؟ وبعدين نحلها بمواد فعالة وطبيعية: شيا من غانا، ملح سيوة، يوريا 25%، وريتينول وكافيين — بخطوات مدروسة، ومن غير وعود بمعجزات.\nوقفنا البيع بإرادتنا عشان نطوّر، ورجعنا.\nتنبيه: منتجات الريتينول لا تُستخدم أثناء الحمل والرضاعة.\n#زيرا #ZyraCare #عناية_بالجسم','\n',char(10)),'مسودة',1795038272846,1795038272846);
INSERT INTO organic_captions VALUES(33,7,3,'بيع ناعم وCTA',replace('ليه تبتدي مع زيرا وإنتي مطمنة؟\nلأننا هنقولك المنتج بيعمل إيه ومتعمليش بيه إيه، وهنرشحلك قبل ما تطلبي ونتابع معاكي بعدها.\nتدفعي لما الأوردر يوصلك، وقدامك 14 يوم ترجعيه لو مش مناسبك.\nابدئي من اللي مضايقك: ابعتلنا في الرسايل وهنرشحلك.\n#ZyraCare #عناية_بالجسم #براند_مصري','\n',char(10)),'مسودة',1795038272859,1795038272859);
INSERT INTO organic_captions VALUES(34,14,1,'تعليمي/قيمة',replace('لو عندك المشكلة دي.. ده روتينك.\n8 روتينات، وكل روتين بمكوّنه الفعّال وخطواته: سيلوليت، جلد الوزة والفراولة، بشرة دهنية، بشرة جافة، بشرة باهتة، عناية سيوة الأسبوعية، ثبات الريحة، وكيت الساحل.\nاسحبي ووصفي لنفسك المشكلة، وهتلاقي روتينها مستنيكي.\nتنبيه: روتين السيلوليت فيه ريتينول، لا يُستخدم أثناء الحمل والرضاعة.\n#روتين #جلد_الوزة #سيلوليت #زيرا','\n',char(10)),'مسودة',1795038275935,1795038275935);
INSERT INTO organic_captions VALUES(35,14,2,'تفاعلي',replace('محتارة بين روتينين؟ ده طبيعي، وعشان كده عملنا البوست ده.\nاسحبي السلايدات وقارني مشكلتك بكل روتين، ولو لسه محتارة اكتبي لنا في الكومنتات إيه اللي مضايقك بالظبط وهنرشحلك الأنسب.\nاحفظي البوست عندك، ده دليلك السريع لروتينات زيرا كلها.\n#عناية_بالجسم #عناية_بالبشرة #ZyraCare','\n',char(10)),'مسودة',1795038275953,1795038275953);
INSERT INTO organic_captions VALUES(36,14,3,'بيع ناعم وCTA',replace('روتينات الأبطال بتوعنا: روتين السيلوليت وروتين جلد الوزة، كل واحد بـ 799 ج بخصم حقيقي عن تمن مكوناته لوحدهم.\nوفيه روتينات تانية تبدأ من 599 ج لروتين البشرة الجافة و700 ج لروتين سيوة الأسبوعي.\nاختاري روتينك من اللينك في البايو، والدفع عند الاستلام و14 يوم للاسترجاع.\nتنبيه: روتين السيلوليت يحتوي على ريتينول، لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #جلد_الوزة #زيرا','\n',char(10)),'مسودة',1795038275967,1795038275967);
INSERT INTO organic_captions VALUES(37,12,3,'بيع ناعم وCTA',replace('أول طلب من زيرا أأسهل مما تتخيلي:\nاختاري روتينك من اللينك في البايو، ولو محتارة ابعتلنا المشكلة ونساعدك تختاري.\nالأوردر بيوصلك وتدفعي عند الاستلام، ولو احتجتي أي مساعدة إحنا هنا عشانك.\n#ZyraCare #جلد_الوزة #سيلوليت','\n',char(10)),'مسودة',1795038280555,1795038280555);
INSERT INTO organic_captions VALUES(38,12,1,'تعليمي/قيمة',replace('ليه تطلبي من زيرا؟ خلينا نرد على كل خوف ممكن يمنعك تاخدي أول خطوة.\nهتدفعي بس لما الأوردر يوصلك، وتقدري ترجعي خلال 14 يوم وفق شروط سياسة الاسترجاع، ومكوّنات كل منتج مكتوبة على صفحته، وكل روتين ليه طريقة استخدام واضحة خطوة بخطوة.\nاسحبي السلايدات، واطلبي وإنتي مطمنة.\n#زيرا #ZyraCare #تسوق_أونلاين','\n',char(10)),'مسودة',1795038280575,1795038280575);
INSERT INTO organic_captions VALUES(39,12,2,'تفاعلي',replace('إيه أكتر حاجة بتخوفك وإنتي بتطلبي منتجات عناية أونلاين لأول مرة؟\nإنك تدفعي قبل ما تشوفي؟ إن الروتين ميبقاش مناسبك؟ إن محدش يرد عليكي بعدها؟\nاكتبي خوفك في الكومنتات وهنرد عليه بصراحة، زي ما بنرد في السلايدات دي بالظبط.\n#عناية_بالجسم #براند_مصري #زيرا','\n',char(10)),'مسودة',1795038280596,1795038280596);
INSERT INTO organic_captions VALUES(40,13,2,'تفاعلي',replace('أول حقيقة لازم تسمعيها: إنتي مش لوحدك، والسيلوليت عند أغلب الستات حتى الرفيعة — ده شكل طبيعي للجلد.\nالعناية بتفرق في الملمس والمظهر، ومش بتفرق في الوزن، ومفيش كريم بيشيل السيلوليت. دي الحقيقة اللي هنفضل نقولها.\nاحفظي البوست وابعتيه لأي واحدة محتاجة تسمع الكلام ده.\nتنبيه: منتجات الريتينول لا تُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #ZyraCare #روتين_الجسم','\n',char(10)),'مسودة',1795038290784,1795038290784);
INSERT INTO organic_captions VALUES(41,13,1,'تعليمي/قيمة',replace('5 غلطات في روتين السيلوليت ممكن يكونوا السبب إنك مش شايفة فرق:\nتفتكري إنه عشان التخن، تفركي جامد، تحطي الكريم من غير تجهيز، تستخدميه الصبح من غير واقي، أو تبطلي بعد أسبوع.\nاسحبي السلايدات واعرفي تصحيح كل غلطة. الروتين الصح: صابونة كولاجين + سكراب كافيين + كريم ريتينول بالليل.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة.\n#سيلوليت #عناية_بالجسم #زيرا','\n',char(10)),'مسودة',1795038290801,1795038290801);
INSERT INTO organic_captions VALUES(42,13,3,'بيع ناعم وCTA',replace('جاهزة تعملي الروتين صح المرة دي؟\nروتين السيلوليت الكامل: صابونة الكولاجين وبذور العنب + سكراب الكافيين وملح سيوة + كريم الريتينول والكافيين والنياسيناميد — بـ 799 ج بدل 975.\nاطلبي من اللينك في البايو، والدفع عند الاستلام.\nتنبيه: الريتينول لا يُستخدم أثناء الحمل والرضاعة، وبيتحط بالليل بس.\n#سيلوليت #زيرا #عناية_بالجسم','\n',char(10)),'مسودة',1795038290816,1795038290816);
INSERT INTO organic_captions VALUES(43,15,3,'بيع ناعم وCTA',replace('روتين جلد الوزة والفراولة كامل: سكراب جلد الوزة + لوشن يوريا 25% + زبدة شيا مكررة.\nمكوناته لوحدها بـ 1,050 ج، والروتين بـ 799 ج بدل 1,020.\nاطلبي من اللينك في البايو، والدفع عند الاستلام و14 يوم للاسترجاع.\n#جلد_الوزة #يوريا25 #ZyraCare','\n',char(10)),'مسودة',1795038294980,1795038294980);
INSERT INTO organic_captions VALUES(44,15,1,'تعليمي/قيمة',replace('4 غلطات بتزوّد جلد الوزة من غير ما تاخدي بالك:\nليفة جامدة كل يوم، مرطب عادي وخلاص، ترتيب غلط بين السكراب واللوشن، ولوشن بعد الشيفينج على طول.\nالتصحيح: سكراب ناعم مرة في الأسبوع في الأول، لوشن فيه يوريا يليّن الجلد الخشن، واستني 24 لـ 48 ساعة بعد الشيفينج.\nاسحبي السلايدات للتفاصيل.\n#جلد_الوزة #يوريا #عناية_بالجسم','\n',char(10)),'مسودة',1795038294993,1795038294993);
INSERT INTO organic_captions VALUES(45,15,2,'تفاعلي',replace('حبيبات دراعك بتزيد في الشتا؟ إنتي مش لوحدك.\nاسمها جلد الوزة، وعلمياً Keratosis Pilaris: كيراتين بيتراكم حوالين فتحات الشعر، والجو الناشف بيخليها تبان أكتر.\nاكتبي لنا في الكومنتات: بتزيد عندك في الشتا ولا طول السنة؟ وهنقولك تعدلي روتينك إزاي.\n#جلد_الوزة #زيرا #روتين_الجسم','\n',char(10)),'مسودة',1795038295006,1795038295006);
INSERT INTO thinking_entries VALUES(1,'اقتصاديات الـCOD للـDual Hero لسه [EST] — ماينفعش تبني عليها Scale ولا Kill','الملف الأساسي ولقطة Dual Hero المالية المحسوبة [EST] بتاريخ 2026-11-18: سعر كلا الروتينين الهيرو 799 جنيه، وCOGS كل واحد 350 جنيه مؤكد من المالك، وTarget CPP = 160، والحقول الأساسية ممتلئة 3/7، وWhatsApp% = 0 وDelivery% = 0، والمُسلّم الفعلي 0 وBreak-even ROAS = 0. رايات عدم اليقين بنفس التاريخ: رسوم Bosta الفعلية غير مؤكدة، ورقم Break-even 275 ومساهمة 381/مُسلّم محسوبين بافتراضات السكربت الافتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD 2%) وعند تسليم صافٍ 72% افتراضي، ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية لسه على المالك، وCOGS باقي المنتجات غير مدخل، وأهداف الريلونش للهيروين الاتنين مستهدفها 0 ومحققها 0.','لأن كل رقم ربحية هنا مبني على افتراض مش على فعلي، ولأن مفيش تسليم فعلي مسجل (مُسلّم 0) يثبّت النسب ← إذن أي مقارنة بين Target CPP 160 والـBreak-even أو المساهمة هتبقى استنتاج من نموذج تقديري مش من السوق، وأي قرار Kill/Scale دلوقتي هيبقى من غير مرور على Payday ومن غير بيانات فعلية زي ما هو مطلوب.','اقتصاديات الـCOD لسه فرضية [EST] قابلة للتغيير أول ما رسوم Bosta والنسب الفعلية تدخل، ومفيش أساس صادق دلوقتي للحكم على نجاح الهيرو أو فشله.','جمع بيانات فقط — مش Scale ومش Kill: المالك يوثّق في خطوة واحدة رسوم Bosta الفعلية + نسب WhatsApp/Delivery الفعلية + ميزانية الاختبار الأسبوعية، وبعدها بس يتعاد حساب المساهمة والـBreak-even قبل أي صرف. معيار إقفال الخطوة قابل للقياس: التلات بنود موثقة كتابةً والحساب متعاد بيها فعليًا، ولحد ده ما يحصل الصرف والتصعيد يفضلوا موقوفين كمقترح.',25,'بانتظار قرارك','',0,1795045501027);
INSERT INTO thinking_entries VALUES(2,'بوابة امتثال واحدة: خطوات الروتين من غير وعد علاجي ولا تضخيم لادعاء الـ1000 عميلة','تحليلات إعلانات المنافسين الأخيرة المسجلة ضمن معطيات 2026-11-18 (تاريخ منفصل للتحليل غير مذكور في المعطيات): Alejon — «اختبر/تبنَّ: زاوية الاستمرارية كروتين واضح الخطوات والتكرار لزيرا، لكن بصياغة استخدام واقعية وبلا وعد علاجي أو ضمان نتيجة». والملف الأساسي بنفس التاريخ بيذكر «أكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت)» — وده مذكور كإعلان ويبسايت، ومفيش في المعطيات توثيق مستقل مرفق ليه. وفي نفس المعطيات: تحليلات كرييتف زيرا «لا تحليلات بعد»، والأورجانيك 15 بوست مسجل و0 معتمد.','لأن القيمة المسجلة في زاوية Alejon هي وضوح الخطوات والتكرار مش ادعاء نتيجة، ولأن زيرا لسه معندهاش تحليل كرييتف ولا بوست أورجانيك معتمد واحد يثبت إن عندها صياغة آمنة شغالة، ولأن ادعاء الـ1000+ مذكور كمُعلن على الويبسايت من غير توثيق مستقل في المعطيات ← إذن تبنّي الشكل من غير بوابة صياغة وتوثيق هيحوّل اختبار منافس لمخاطرة وعد علاجي أو ادعاء اجتماعي غير مدعوم بالمعطيات المسجلة.','اللي يتاخد من Alejon هو هيكل «روتين واضح الخطوات والتكرار» بصياغة واقعية بس، وأي نسخة فيها وعد علاجي أو ضمان نتيجة أو استخدام غير موثق لادعاء الـ1000+ تبقى برّه بوابة الامتثال.','قرار مقترح واحد: قبل اعتماد أول نسخة كرييتف بزاوية الاستمرارية، تعدّي على فحص امتثال واحد موثق. معيار القياس: النسخة المعتمدة عدد الوعود العلاجية وضمانات النتيجة فيها صفر، وخطوات الاستخدام والتكرار مكتوبة بصياغة واقعية، وادعاء الـ1000+ عميلة مش مستخدم في الكرييتف لحد ما يتوثق مصدره — ولو الفحص فشل في أي بند، النسخة ما تتعتمدش.',35,'بانتظار قرارك','',0,1795045501043);
INSERT INTO thinking_entries VALUES(3,'AEO «زبدة الشيا الاصلية» ورقم 25%: اختبار مؤجل لحد توثيق المصدر والمرجع','بنود مسجلة بصيغة «غير محدد من التسجيل» ضمن معطيات 2026-11-18، ومصدرها وتاريخها المنفصل غير محددين في التسجيل نفسه: (1) اختبار قسم أسئلة شائعة/محتوى بعنوان يطابق لغة البحث «زبدة الشيا الاصلية» يشرح علامات تحقق قابلة للفحص لمنتج زيرا — والقائمة مقطوعة في النص المسجل؛ (2) بند بيقول «اختبر ولا تتبنَّ نهائيًا بعد» العنوان ده مقابل عنوان عام عن زبدة الشيا؛ (3) اختبار إبراز «الرقم الموثق 25%» في عنوان الإعلان/صفحة المنتج مقابل وصف عام للفئة، من غير ذكر أسماء براندات ومن غير ادعاء طبي — ومرجع الرقم 25% لإيه بالظبط غير موضح في المعطيات اللي وصلت.','لأن المصدر غير محدد والقائمة غير مكتملة ومرجع 25% غير موضح ← إذن نشر العنوان أو الرقم كحقيقة منتج دلوقتي هيبقى تبنّي نهائي لمحتوى التسجيل نفسه بيقول عليه «اختبر ولا تتبنَّ نهائيًا بعد»، وهيبني AEO على معلومة ناقصة ممكن تتفهم غلط.','فرصة الـAEO موجودة كفرضية اختبار بس، مش كمحتوى جاهز للنشر، وحالتها الحالية رسميًا: ناقصة التوثيق.','جمع بيانات فقط قبل أي نشر أو اختبار: توثيق مصدر البنود دي + مرجع الرقم 25% مكتوبًا + قائمة علامات تحقق زبدة الشيا كاملة وقابلة للفحص لمنتج زيرا. معيار الإقفال قابل للقياس: التلات عناصر موثقة، وبعده بس يتنفذ اختبار العنوان المسجل «زبدة الشيا الاصلية» مقابل عنوان عام — ولحد التوثيق مفيش تبنّي نهائي.',20,'بانتظار قرارك','',0,1795045501055);
INSERT INTO thinking_entries VALUES(4,'هوية زيرا في السيلوليت: «روتين متكامل» ضد بيع الكريم بالخصم — والفراغ جزئي مش سوق فاضي','الملف الأساسي بتاريخ 2026-11-18: عرض الهيرو «روتينات متكاملة لكل مشكلة بشرة/جسم — مشكلتك ليها روتين»، وروتين السيلوليت هيرو ريلونش بسعر 799 جنيه. ورصد Mazora الموثق (VERIFIED) من Meta Ads Library، مصر، إعلانات نشطة، بتاريخ 2026-11-18: بروفايله المسجل براند مصري لكريمات شد الجسم والسيلوليت بيبيع بعروض خصم موسمية قوية، ومسجل ليه «اختبار فراغ»: حضور Meta مخصص لزاوية الشد والعناية بمظهر السيلوليت اللي المنافس سابها بلا إعلان وقت الرصد. في المقابل، تنبيهات السوق الأخيرة في سياق 2026-11-18 فيها Hepta Skin — هيبتا بهيمنة إعلانية وTetavara بتوقف إعلاني، وإجمالي المنافسين المسجلين 31.','لأن تمييز زيرا المسجل هو الروتين المتكامل للمشكلة، وتمييز Mazora المسجل هو كريم + خصم موسمي قوي، ولأن فراغ Mazora خاص بزاوية معينة ووقت رصد ومش معناه سوق فاضي — بدليل هيمنة Hepta المسجلة في نفس المعطيات ← إذن الهوية تتقال كروتين عناية بمظهر السيلوليت بخطوات واضحة، مش كدخول حرب خصومات ولا كادعاء إن السوق بلا منافسة.','فيه زاوية هوية قابلة للاختبار لروتين السيلوليت، لكنها مش إذن إطلاق ولا Scale: لسه مربوطة ببوابة الاقتصاديات في المدخل الأول وبفحص الامتثال في المدخل التاني.','قرار مقترح واحد تحضيري وبلا صرف: تجهيز نسخة حضور Meta واحدة بس لزاوية الشد والعناية بمظهر السيلوليت مبنية على فكرة الروتين المتكامل مش الخصم الموسمي، وتفضل في حالة مسودة لحد توثيق بيانات الاقتصاديات وعدّيها فحص الامتثال. معيار القياس: نسخة واحدة جاهزة ومراجعة بالامتثال، وصفر صرف إعلاني عليها قبل ما البوابتين يقفلوا.',30,'بانتظار قرارك','',0,1795045501069);
INSERT INTO thinking_entries VALUES(5,'اقتصاديات COD لسه تقديرية — ممنوع Scale/Kill','الملف الأساسي بتاريخ 2026-11-19: الهيروان سعر 799 وCOGS ‏350 مؤكد من المالك، وTarget CPP ‏160، وحقول أساسية ممتلئة 3/7 بس، وWhatsApp%=0 وDelivery%=0. آخر لقطة مالية Dual Hero محسوبة [EST] بتاريخ 2026-11-18: موضوع 0 ومُسلّم 0 ومساهمة/مُسلّم 381 وBreak-even ROAS ‏0 وRTO ‏0%. نفس الملف بيقول إن Break-even ‏275 والمساهمة 381 محسوبة بافتراضات افتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD ‏2%) وتسليم صافي 72% افتراضي، ورسوم Bosta الفعلية غير مؤكدة، ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية لسه على المالك، وأهداف الريلونش للهيروان مستهدف 0 ومحقق 0.','لأن المساهمة 381 وBreak-even ‏275 مبنيين على تسليم 72% ورسوم افتراضية مش فعلية ← إذن أي مقارنة مع Target CPP ‏160 هتدي قرار وهمي. ولأن الموضوع والمُسلّم فعليًا 0 والـDelivery% ‏0 ← إذن مفيش وحدة اقتصادية حقيقية اتقاست أصلًا.','مفيش أساس فعلي لأي حكم ربحية أو Scale/Kill دلوقتي؛ الرقم الوحيد المؤكد في اقتصاديات الهيرو هو COGS ‏350، والباقي إما صفر أو تقديري [EST].','قرار مقترح للمالك بس — جمع بيانات مش تنفيذ: المالك يسلّم رسوم Bosta الفعلية ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية ويستكمل الحقول من 3/7 لـ7/7، وبعدها تتعاد اللقطة المالية بموضوع ومُسلّم أكبر من 0 قبل ما أي Kill/Scale يعدي على Payday — وتاريخ Payday نفسه غير مسجل في المعطيات ويتحدد من المالك.',30,'بانتظار قرارك','',0,1795048285912);
INSERT INTO thinking_entries VALUES(6,'بوابة امتثال AEO: ادعاء الـ+1000 وصياغات العلاج ممنوع يعدّوا من غير توثيق','الملف الأساسي بتاريخ 2026-11-19: عرض الهيرو معلن على الويبسايت بعبارة «أكتر من 1000 عميلة طلبوا من زيرا» من غير مصدر تحقق مستقل مسجل في المعطيات. تحليل Alejon المسجل (التاريخ غير مذكور في المعطيات): تبنّي زاوية الاستمرارية كروتين واضح الخطوات بس بصياغة واقعية وبلا وعد علاجي أو ضمان نتيجة. تحليل Centevia ‏VERIFIED من Meta Ads Library — مصر (التاريخ غير مذكور): صياغة المشكلة لغرض تجميلي/مظهر الخشونة وجلد الوزة. الأورجانيك بتاريخ 2026-11-19: 15 بوست مسجل و0 معتمد، واعتمادات معلّقة 0.','لأن «كما هو معلن على الويبسايت» إعلان مش توثيق ← إذن ماينفعش يتحول الادعاء لدليل تسويقي من غير مصدره. ولأن تحليلات المنافسين المسجلة نفسها حاطة حد واضح: تجميلي وبلا وعد علاجي ولا ضمان نتيجة ← إذن الامتثال بوابة قبل الكرييتف مش بعدها.','بوابة الامتثال والـAEO لسه مفتوحة: الادعاء العددي غير موثّق في المعطيات، ومفيش محتوى معتمد أصلًا، فأي نشر قبل التوثيق والمراجعة مخاطرة مش مدعومة بدليل.','قرار مقترح للمالك بس — بوابة اعتماد قابلة للقياس: الـ15 بوست يفضلوا 0 معتمد لحد ما المالك يقدّم مصدر ادعاء «+1000 عميلة» المسجل، وكل نسخة تعدي مراجعة مكتوبة بتمنع الوعد العلاجي وضمان النتيجة وتلتزم بصياغة المظهر التجميلي بس؛ الاعتماد يتحرك من 0 بس بعد اكتمال التوثيق والمراجعة.',45,'بانتظار قرارك','',0,1795048285927);
INSERT INTO thinking_entries VALUES(7,'اختبار كرييتف واحد بمتغير واحد — بس نصه ناقص','تحليل Centevia ‏VERIFIED، المصدر Meta Ads Library — مصر (التاريخ غير مذكور في المعطيات): «اختبر ولا تنسخ: فيديو يفتتح بمشكلة بصرية واحدة محددة — مظهر الخشونة/جلد الوزة لغرض تجميلي — مقابل فيديو ترطيب عام، بنفس» والنص المسجل مقطوع عند «بنفس». تحليل Alejon المسجل (التاريخ غير مذكور): زاوية تانية مختلفة هي الاستمرارية كروتين واضح الخطوات والتكرار. تحليلات كرييتف أخيرة في ملف 2026-11-19: لا تحليلات بعد.','لأن Rule of One بيطلب متغير واحد، والمقارنة المسجلة هي مشكلة بصرية واحدة محددة مقابل ترطيب عام ← إذن إدخال خطوات الاستمرارية في نفس النسخة هيخلي سبب أي نتيجة مجهول. ولأن الشرط الموحّد مقطوع عند «بنفس» ومفيش تحليلات كرييتف سابقة ← إذن المواصفة والقياس ناقصين ولازم يتجمعوا الأول.','فكرة الاختبار موجودة بس مواصفاتها ناقصة، ودمجها مع زاوية Alejon هيبوّظ عزل المتغير؛ فمفيش اختبار جاهز للتنفيذ ولا فائز ممكن إعلانه.','قرار مقترح للمالك بس — جمع بيانات وتكملة مواصفة: يُستكمل النص المقطوع بعد «بنفس» من مصدر تحليل Centevia ويتسجل الشرط الموحّد بين النسختين ومقياس الحكم قبل الإنتاج، مع فصل اختبار المشكلة البصرية الواحدة عن اختبار الاستمرارية بتاع Alejon فصل كامل؛ من غير الاستكمال ده مفيش إنتاج ولا إطلاق للاختبار.',38,'بانتظار قرارك','',0,1795048285941);
INSERT INTO thinking_entries VALUES(8,'فراغ Mazora في السيلوليت فرصة لحظية — لازم إعادة رصد قبل أي صرف','رصد Mazora ‏VERIFIED بتاريخ 2026-11-18، المصدر Meta Ads Library — مصر، إعلانات نشطة: براند مصري لكريمات شدّ الجسم والسيلوليت بيبيع بخصومات موسمية قوية، والتوصية المسجلة «اختبار الفراغ» لزاوية الشدّ والعناية بمظهر السيلوليت اللي تركها المنافس بلا إعلان وقت الرصد، وباقي التوصية مقطوع في المعطيات. تنبيهات السوق الأخيرة في ملف 2026-11-19 في نفس الوقت: Hepta Skin هيمنة إعلانية، وTetavara توقف إعلاني، وكلمة «سيلوليت» في مكتبة الإعلانات مسجلة كفرصة سوق. ميزانية الاختبار الأسبوعية غير مسجلة ولسه على المالك حسب ملف 2026-11-19.','لأن غياب إعلان Mazora كان «وقت» الرصد بتاريخ 2026-11-18 ← إذن ممكن يكون اتغير على تاريخ النهاردة 2026-11-19 أو بعده ومفيش رصد أحدث. ولأن هيمنة Hepta الإعلانية مسجلة جنب الفرصة ← إذن السوق مش فاضي بالكامل. ولأن الميزانية والاقتصاديات الفعلية ناقصة ← إذن القرار الصح تحقق جديد مش صرف.','الفراغ المسجل لحظي ومؤرخ بـ2026-11-18 ومش دليل دائم، وإشارات السوق متعارضة بين فرصة وهيمنة منافس، فماينفعش يتبني عليه دخول مدفوع دلوقتي.','قرار مقترح للمالك بس — جمع بيانات وتحقق جديد: إعادة رصد مؤرخة على Meta Ads Library لمازورا وHepta Skin لتسجيل حضور أو غياب إعلان زاوية الشدّ ومظهر السيلوليت وقت القرار، ونتيجتها تتربط ببوابة اقتصاديات COD في المدخل الأول؛ لحد ما الرصد الجديد والميزانية يتسجلوا، مفيش إطلاق حضور مدفوع ولا Scale.',32,'بانتظار قرارك','',0,1795048285956);
INSERT INTO thinking_entries VALUES(9,'اقتصاديات COD: أرقام الهيرو تقديرية وصفر تشغيل فعلي — ممنوع Scale/Kill دلوقتي','الملف الأساسي بتاريخ 2026-11-19: سعر الهيروين 799 وCOGS الهيروين 350 EGP مؤكد من المالك، وTarget CPP=160، والح fields الأساسية 3/7 بس. آخر لقطة مالية Dual Hero [EST] بتاريخ 2026-11-18: موضوع 0، مُسلّم 0، مساهمة/مُسلّم 381، Break-even ROAS=0، RTO=0%. نفس المعطيات بتقول رسوم Bosta الفعلية غير مؤكدة، ورقم 381 ورقم Break-even 275 محسوبين بافتراضات سكربت افتراضية (تعبئة 20 / شحن 70 / مرتجع 50 / COD 2%) عند تسليم صافي 72% افتراضي، وWhatsApp%=0 وDelivery%=0، ونسب WhatsApp/Delivery الفعلية وميزانية الاختبار الأسبوعية وCOGS باقي المنتجات لسه ناقصين على المالك.','لأن COGS لوحده مؤكد، لكن تكلفة التوصيل والمرتجع والـ COD والتسليم كلها افتراضية ← إذن المساهمة 381 والـ Break-even 275 مش أرقام فعلية. ولأن الموضوع والمُسلّم وDelivery وWhatsApp كلهم صفر في اللقطة ← إذن مفيش سلوك عميلة فعلي نقيس عليه CPP=160 المستهدف ولا نحكم بيه على الهيرو.','مفيش أساس فعلي لأي قرار Scale أو Kill أو اعتماد رقم 381 كربح حقيقي؛ أي تنفيذ دلوقتي هيبقى مبني على تقدير [EST] وصفر مبيعات مسجلة.','قرار مقترح واحد — جمع بيانات بس، لا Scale ولا Kill قبل Payday والبيانات الفعلية: المالك يسلّم رسوم Bosta الفعلية، ونسب WhatsApp/Delivery الفعلية، وميزانية الاختبار الأسبوعية، وCOGS باقي المنتجات، وتتكمل الحقول الأساسية من 3/7 لـ 7/7، وبعدها تتعاد اللقطة المالية من غير افتراضات السكربت ويُقاس النجاح باختفاء وصف [EST] الافتراضي وظهور موضوع ومُسلّم فعليين غير صفريين.',28,'بانتظار قرارك','',0,1795062656366);
INSERT INTO thinking_entries VALUES(10,'بوابة امتثال AEO: سؤال «جلد الوزة في الوجه» فرضية كويسة بس ممنوع نشرها بلا اعتماد','تحليلات إعلانات المنافسين الأخيرة المسجلة بتاريخ غير محدد من التسجيل: اقتراح اختبار محتوى تعليمي سؤال وجواب موجز يطابق لغة البحث «جلد الوزة في الوجه» مع توضيح فرق احتياجات الوجه عن غيره، واقتراح تاني يشرح صلة التقشير/اليوريا بالشعر تحت الجلد بلغة عناية وصفية غير علاجية، واقتراح قياس الظهور والنقر لعبارة البحث كعنوان خاص بالوجه مقابل المحتوى العام. في المقابل، بتاريخ 2026-11-19: تحليلات الكرييتف «لا تحليلات بعد»، والأورجانيك 15 بوست مسجل و0 معتمد، وميزانية الاختبار الأسبوعية لسه ناقصة.','لأن الطلب المسجل نفسه مربوط بلغة بحث محددة وبيشترط ضمنيًا لغة غير علاجية والتمييز بين الوجه وغيره ← إذن المحتوى لازم يعدّي امتثال AEO قبل ما يبقى رسالة بيع. ولأن الاعتماد صفر والكرييتف غير محلل والميزانية ناقصة ← إذن النشر أو الصرف دلوقتي هيطلع نتيجة مش قابلة للحكم ولا آمنة امتثاليًا.','فكرة الـ AEO المسجلة واعدة كفرضية بحث، بس لسه مش جاهزة للنشر أو الصرف: مفيش تحليل كرييتف، ومفيش اعتماد، وصياغة علاجية واحدة غلط هتعدّي بوابة الامتثال.','قرار مقترح واحد — جمع بيانات واعتماد قبل أي نشر: يتحضّر مسودة واحدة بس بصيغة سؤال/جواب بعنوان عبارة البحث المسجلة «جلد الوزة في الوجه» وبلغة عناية وصفية غير علاجية صريحة، وتقف عند بوابة مراجعة الامتثال والاعتماد، ويُقاس التقدم بتحوّل الاعتماد من 0 من 15 بوست لحالة اعتماد موثقة للمسودة دي وتسجيل مقياس الظهور والنقر المطلوب قبل مقارنتها بالمحتوى العام — من غير إطلاق مدفوع قبل ما المالك يحدد ميزانية الاختبار.',34,'بانتظار قرارك','',0,1795062656384);
INSERT INTO thinking_entries VALUES(11,'هوية البراند: «مشكلتك ليها روتين» عامة، والهيرو وAlejon بيقولوا التخصص لمشكلة واحدة','الملف الأساسي بتاريخ 2026-11-19: عرض الهيرو العام «روتينات متكاملة لكل مشكلة بشرة/جسم — مشكلتك ليها روتين» مع ادعاء «أكتر من 1000 عميلة طلبوا من زيرا (كما هو معلن على الويبسايت)»، والمنتجات المسجلة 23، والهيروات اتنين متخصصين بالاسم: روتين السيلوليت وروتين جلد الوزة والفراولة، كل واحد بسعر 799 وCOGS 350. تحليل Alejon — خط اليوريا/جلد الوزة ببيانات موقع موثقة VERIFIED من alejon.com (التاريخ غير محدد من التسجيل): تبنّي/اختبار منتج وصفحة روتين مخصصين بوضوح لمشكلة واحدة بدل خط عام، باختبار A/B لصفحة متخصصة مقابل صفحة منتج عام — ونص مقياس الاختبار مقطوع عند «بقياس» في التسجيل. أهداف الريلونش بتاريخ 2026-11-19 للهيروين الاتنين: مستهدف 0 ومحقق 0.','لأن العرض الحالي بيكلم كل مشاكل البشرة/الجسم في جملة واحدة، بينما الهيروين نفسهم منتجات مشكلة واحدة، وAlejon الموثق بيختبر التخصص ضد العموم ← إذن فرضية «التخصص أوضح للهوية» تستاهل اختبار. لكن لأن مستهدف ومحقق الريلونش صفر ومقياس الـ A/B مقطوع والميزانية على المالك ← إذن تغيير الهوية أو الصفحة دلوقتي هيبقى قرار تنفيذي بلا معيار نجاح.','فيه توتر هوية حقيقي بين رسالة عامة لكل المشاكل وبين هيروات متخصصة بمشكلة واحدة، ودرس Alejon الموثق بيدعم اختبار التخصص — بس الاختبار نفسه لسه بلا هدف ولا مقياس مكتمل ولا ميزانية.','قرار مقترح واحد — جمع بيانات قبل اختبار الهوية: المالك يحدد مستهدف ريلونش غير صفري لأحد الهيروين، ويتكمل مقياس الـ A/B الناقص في تسجيل Alejon، وتتحدد ميزانية الاختبار الأسبوعية الناقصة، ويُقاس الجاهزية باكتمال التلات عناصر دي موثقة قبل إطلاق أي A/B بين صفحة متخصصة لمشكلة واحدة وصفحة عامة.',38,'بانتظار قرارك','',0,1795062656398);
INSERT INTO competitor_ad_analyses VALUES(1,1,'غير محدد من التسجيل','لا زاوية إعلان مسجلة. مستنتج من المسجل فقط: هيكل كتالوج من 23 منتجًا منظّم كروتينات حسب المشكلة (سيلوليت، جلد الوزة، بشرة دهنية/جافة/باهتة، كيت الساحل) + مفردات، بمكونات معلنة: ملح سيوة، يوريا 25%، كافيين، ريتينول، زبدة شيا.','غير مسجل — لا يوجد هوك أو نص أو محتوى إعلان موصوف في التسجيل.','غير مسجل كإعلان — المادة المسجلة قراءة ويبسايت zyra-care.com (الكتالوج والسياسات) بتاريخ رصد 2026-11-18 ووسم VERIFIED، وليست فيديو أو صورة أو نص إعلان منافس موصوفًا.','مسجل كأسعار كتالوج فقط، لا كعرض إعلاني: روتينات 599 (بشرة دهنية/جافة/باهتة)، 799 (سيلوليت، جلد الوزة)، 1300 (كيت الساحل)؛ مفردات 360 (لوشن يوريا 25%)، 350 (كريم سيلوليت ريتينول/كافيين)، 390 (سكراب ملح سيوة). أي خصم أو شحن أو ضمان إعلاني غير مسجل.','غير مسجلة — المسجل فقط تاريخ الرصد 2026-11-18، ولا يوجد تاريخ بدء أو مدة تشغيل أو استمرارية مذكورة في التسجيل.','النجاح غير مسجل — لا توجد أرقام أداء أو مدة تشغيل في التسجيل فلا يمكن الجزم بأنه شغال. استنتاج محتمل فقط وقابل للاختبار: تنظيم الكتالوج حسب المشكلة مع تسعير واضح للروتين مقابل المفرد قد يقلل حيرة الاختيار ويسهّل المقارنة الداخلية.','الأوضح: المادة ليست إعلان منافس أصلًا — المصدر هو zyra-care.com ولا منافس مذكور صراحة، وبلا هوك أو محتوى إعلاني أو أداء، فأي استنتاج تنافسي مبني عليها غير مؤسس من التسجيل.',replace('تختبر زيرا: مدخل تسوّق حسب المشكلة مقابل مدخل حسب المنتج، بقياس التحويل، دون ادعاءات طبية أو وعود علاجية.\nتتبنى: إظهار المكوّن المعلن ونسبته كما هو مسجل (مثل يوريا 25% وملح سيوة) لرفع الوضوح، دون تحويله لادعاء فعالية طبية.\nتختبر: معمارية سعر الروتين (599/799/1300) مقابل المفردات (350-390) كاختبار لقيمة الباقة، لا كعرض منسوخ من منافس.\nتتجنب: تسمية قراءة موقع zyra-care.com إعلان منافس، أو عمل مقارنات باسم براند (AEO)، أو اختراع هوك أو مدة أو أداء غير مسجل.\nتختبر: تجميع كيت لاستخدام محدد (كيت الساحل 1300) كفكرة تجميع فقط، مع التحقق من الهامش والمخزون قبل التعميم.','\n',char(10)),1795040415721);
INSERT INTO competitor_ad_analyses VALUES(2,2,'غير محدد من التسجيل','مسجل كسياق سوق لا كزاوية إعلان لمنافس محدد: سوق اليوريا/جلد الوزة مزدحم بتركيزات 10–20% وأسعار 149–439 EGP، والتمييز الموثق بالأرقام لزيرا هو تركيز 25% — الأعلى في المقارنة المرصودة — بسعر 360 EGP.','غير مسجل — لا يوجد نص هوك أو افتتاحية أو محتوى إعلان موصوف في التسجيل، فلا يمكن نسب أي هوك لمنافس.','غير مسجل — لا فورمات إعلان موصوف (فيديو/صورة/UGC أو غيره)؛ المصدر المسجل فقط هو صفحات منتجات المنافسين، ووسم الأدلة VERIFIED بتاريخ رصد 2026-11-18.','غير مسجل كعرض ترويجي — لا خصم أو حزمة أو شحن مذكور؛ المسجل فقط نطاق أسعار الفئة 149–439 EGP وسعر لوشن ZYRA ‏360 EGP.','غير مسجلة — لا تاريخ بدء ولا مدة تشغيل أو استمرارية مذكورة؛ التاريخ الوحيد المسجل هو تاريخ الرصد 2026-11-18.','غير مثبت من التسجيل: لا توجد أرقام أداء أو مدة تشغيل لإعلان محدد يمكن الحكم بنجاحه منها. المستنتج فقط أن المقارنة الرقمية القابلة للتحقق (25% مقابل نطاق 10–20% المرصود) واضحة وسهلة الفهم، وقد تساعد على التمييز في فئة مزدحمة — وهذا استنتاج وليس نتيجة مسجلة.','لا نقطة ضعف مسجلة لإعلان محدد لعدم وجود إعلان محدد. الفجوة الأوضح مستنتجة من المسجل: التفوق الرقمي وحده لا يحسم المنافسة لأن المنافسة الأقوى مسجلة في توزيع الصيدليات لا في الإعلان فقط، وسعر 360 EGP ليس الأرخص ضمن 149–439 EGP دون مبرر قيمة إضافي مسجل.',replace('اختبر: إبراز الرقم الموثق 25% في عنوان الإعلان/صفحة المنتج مقابل وصف عام للفئة، دون ذكر أسماء براندات ودون ادعاء طبي، وقارن النقر والتحويل بين النسختين.\nتبنَّ: مقارنة فئوية مجهولة المصدر بالأرقام فقط (نطاق السوق المرصود 10–20%) بدل المقارنة باسم منافس، مع الاحتفاظ بمصدر وتاريخ الرصد.\nاختبر: عرض السعر 360 EGP بشفافية مع اختبار رسائل تبرير القيمة بالتركيز الأعلى، بدل الدخول في منافسة سعرية نحو حد 149 EGP الأدنى دون دليل.\nتبنَّ واختبر: أولوية توزيع/توفر في الصيدليات بالتوازي مع الإعلان، لأن المنافسة الأقوى مسجلة كقناة توزيع؛ قِس التوفر والطلب قبل زيادة الإنفاق الإعلاني.\nتجنب: نسخ زوايا الفئة المزدحمة أو ادعاءات علاجية/نتائج لجلد الوزة غير موثقة في التسجيل، وتجنب ادعاء نجاح أي زاوية قبل اختبارها ببيانات أداء فعلية.','\n',char(10)),1795040444453);
INSERT INTO competitor_ad_analyses VALUES(3,3,'غير محدد من التسجيل','مستنتجة من لغة البحث المسجلة وليست زاوية إعلان منافس موصوفة: الثقة/الأصالة — التمييز بين «زبدة الشيا الاصلية» والمقلدة، كما ورد في تفاصيل الرصد أنها زاوية يمكن توظيفها في محتوى زبدة الشيا.','غير مسجل — لا يوجد هوك أو نص إعلان موصوف؛ العبارة الوحيدة المسجلة هي اقتراح البحث نفسه: «زبدة الشيا الاصلية».','غير مسجل كفورمات إعلان — المسجل فقط اقتراح بحث في Google Egypt Autocomplete (المصدر: suggestqueries.google.com، hl=ar، gl=eg) ضمن قائمة 10 اقتراحات للكلمة المتبعة «زبدة الشيا».','غير مسجل — لا سعر ولا خصم ولا منتج معروض ولا عرض ولا CTA مذكور في التسجيل.','غير مسجلة — لا تاريخ بدء إعلان ولا مدة تشغيل/استمرارية مذكورة؛ المسجل فقط أول ظهور للاقتراح في مسح 2026-11-18 23:10 EET.','غير مثبت كنجاح إعلاني من التسجيل — لا توجد أرقام أداء أو مبيعات مسجلة أصلاً لأنه ليس إعلاناً موصوفاً. المستنتج فقط: دخول الصياغة قائمة الاقتراحات العشرة وحلولها محل «زبدة الشيا للبشرة» في مسح 2026-11-18 يشير على الأرجح إلى نية بحث مرتبطة بالتحقق من الأصالة والثقة، وهي تصلح فرضية محتوى قابلة للاختبار لا دليل نجاح.','الأوضح: إشارة لقطة واحدة بلا حجم بحث ولا استمرارية ولا منافس ولا عرض ولا آلية إثبات أصالة مسجلة، فلا تكفي وحدها لبناء ادعاء أصالة أو قرار منتج/حملة؛ والتسجيل نفسه ينفي كونها منتجاً جديداً غائباً عن زيرا.',replace('اختبر ولا تتبنَّ نهائياً بعد: عنوان/قسم أسئلة بصياغة البحث المسجلة «زبدة الشيا الاصلية» مقابل عنوان عام عن زبدة الشيا، وقارن الظهور والنقرات من بحث Google قبل التعميم.\nتبنَّ: محتوى إثبات أصالة على شكل Checklist للتحقق قبل الشراء، يعتمد فقط على حقائق موثقة لدى زيرا (مثل قائمة المكونات وبيانات المصدر/الدفعة والتغليف إن كانت موثقة داخلياً) — دون اختراع مواصفات غير مسجلة.\nتجنب: الادعاءات الطبية/العلاجية، والمقارنات باسم أي براند، ووصف منتجات أخرى بأنها مقلدة دون دليل، وإنشاء فرصة منتج جديد؛ فالتسجيل يؤكد أن زبدة الشيا مكوّن موجود أصلاً لدى زيرا.\nاختبر الاستمرارية قبل التوسع: أعد رصد اقتراحات «زبدة الشيا» في مسوح لاحقة بنفس إعدادات مصر (hl=ar، gl=eg)، ولا توسّع المحتوى إلا إذا تكرر بقاء الاقتراح ضمن العشرة، لأن الرصد الحالي لقطة واحدة.\nاختبر رسالتين دون نسخ أعمى: نسخة تعليمية (كيف تتحققين من الأصالة) مقابل نسخة ثقة بالأدلة الموثقة لدى زيرا، وقارن التفاعل/التحويل المسجل فعلياً قبل اعتماد أيهما.','\n',char(10)),1795040473717);
INSERT INTO competitor_ad_analyses VALUES(4,13,'غير محدد من التسجيل','غير مسجلة كزاوية إعلان — المسجل فقط إشارة لغة بحث: التمييز بين الأصلي والمقلّد لـ«زبدة الشيا»، وهي صفة أصالة على منتج/مكوّن موجود أصلاً (مكوّن في منتجات زيرا)، وليست منتجاً أو مشكلة جديدة.','غير مسجل — لا يوجد نص أو صورة أو هوك إعلاني موصوف في التسجيل؛ العبارة المسجلة الوحيدة هي اقتراح البحث نفسه «زبدة الشيا الاصلية».','غير مسجل كفورمات إعلان — المصدر اقتراح Google Egypt Autocomplete (suggestqueries.google.com, hl=ar, gl=eg، وسم SEARCH_LANGUAGE) ظهر تحت الكلمة المفتاحية «زبدة الشيا» في المركز 9 من 10.','غير مسجل — لا سعر أو خصم أو ضمان أو أي عرض مذكور في التسجيل.','غير مسجلة — لا مدة تشغيل إعلان مذكورة؛ المسجل فقط أول ظهور للاقتراح في 2026-11-19 00:29 EET، وعدم وجوده في لقطة 2026-11-18 22:10 UTC، ضمن مسح دوري كل 20 دقيقة وتاريخ رصد 2026-11-19.','نجاح إعلاني غير مسجل — لا أرقام أداء أو مبيعات أو محتوى إعلان في التسجيل. كإشارة طلب فقط، دخول صفة «الاصلية» إلى اقتراحات البحث يوحي على الأرجح باهتمام الباحثين بالتحقق من الأصالة قبل الشراء، لا بإثبات نجاح إعلان منافس.','أوضح ضعف/حدّ: إشارة وحيدة عند أول ظهور وفي مركز متأخر (9 من 10)، بلا منافس أو محتوى إعلان أو عرض مسجل، وباقي الكلمات الـ11 بلا اقتراحات جديدة تماماً — فلا تكفي لإثبات طلب واسع أو تفوق منافس.',replace('اختبر: قسم أسئلة شائعة/محتوى بعنوان يطابق لغة البحث «زبدة الشيا الاصلية» يشرح علامات تحقق قابلة للفحص لمنتج زيرا (قائمة المكونات والمصدر الموثقان)، وقِس الدخول والنقرات قبل التوسع.\nتبنّى: إبراز أدلة أصالة زيرا نفسها (مصدر المكوّن، بيانات التشغيلة، قنوات الشراء الرسمية) دون مقارنات باسم أي براند ودون ادعاءات طبية.\nتجنّب: اعتبار الإشارة فرصة منتج جديد أو إطلاق منتج منفصل — التسجيل ينص صراحة أنها صفة على مكوّن موجود أصلاً ولا تحمل فرصة منتج جديدة.\nاختبر بالمراقبة: إعادة فحص استمرار الاقتراح ومركزه في مسوح لاحقة قبل بناء حملة دائمة؛ أول ظهور واحد في المركز 9 لا يكفي وحده لقرار كبير.\nتجنّب: استخدام «الأصلية» كادعاء مطلق بلا إثبات موثق، أو وصف منتجات أخرى بأنها مقلّدة.','\n',char(10)),1795042089856);
INSERT INTO competitor_ad_analyses VALUES(5,4,'Mazora — مصدر الرصد: Meta Ads Library، مصر، إعلانات نشطة، بتاريخ 2026-11-18 (VERIFIED). بروفايله المسجّل: براند مصري لكريمات شدّ الجسم والسيلوليت يبيع بعروض خصم موسمية قوية.','مسجّل: زاوية تخسيس عبر مكملات فقط (Fat Burner, Zero Belly, Slim) مقترنة بعروض كمية/خصم — وليست زاوية سيلوليت/شدّ على Meta، إذ إن Cell Firming Cream غير مُعلَن عنه حاليًا هناك رغم أنه منتج فئة الشدّ والسيلوليت في البروفايل المطابق. أي زاوية كريتيف تفصيلية أخرى غير مسجّلة.','غير مسجّل — التسجيل لا يصف نص هوك أو افتتاحية أو مشهدًا أو ادعاءً محددًا لأي إعلان؛ المسجّل فقط أسماء المنتجات والعروض، ولا يمكن اختراع هوك منها.','غير مسجّل — التسجيل لا يذكر نوع الفورمات (فيديو/صورة/كاروسيل/UGC) ولا بنية أو طول أي إعلان؛ المسجّل فقط وجود ~10 إعلانات نشطة على Meta.','مسجّل على إعلانات Meta النشطة لمكملات التخسيس: Buy 2 Get 1 / القطعة الثانية بخصم 50%. وبشكل منفصل في البروفايل المسجّل بتاريخ 2026-11-12: Cell Firming Cream بخصم Black Friday −50% بسعر 600 EGP — ولا يُنسب هذا كعرض إعلان Meta لأن الكريم مسجّل كغير مُعلَن عنه حاليًا هناك.','مسجّل: تاريخ الرصد 2026-11-18، وأقدم الإعلانات من 23 سبتمبر 2026 — أي 56 يومًا حتى تاريخ الرصد حسب التسجيل. لا يثبت ذلك أن كل إعلان من الـ~10 استمر 56 يومًا، ولا توجد مدة تشغيل فردية أخرى مسجّلة.','لا نجاح مؤكّد مسجّل: لا توجد أرقام أداء (مبيعات/CTR/ROAS) في التسجيل. المؤشر الوحيد للاستنتاج بحذر هو بقاء ~10 إعلانات نشطة ووجود أقدمها منذ 56 يومًا، مع عرض كمية واضح قد يفسّر الاستمرارية بتخفيض التكلفة الظاهرة للوحدة — لكن الاستمرارية ليست إثبات فعالية.','الفجوة الأوضح مسجّلة: انفصال بين تموضع الشدّ والسيلوليت ومنتج Cell Firming Cream وعرضه الموسمي −50% بتاريخ 2026-11-12، وبين غيابه تمامًا عن إعلانات Meta النشطة التي اقتصرت على مكملات التخسيس — فيترك فئة السيلوليت بلا تغطية إعلانية منه على Meta وقت الرصد.',replace('اختبار الفراغ: اختبر لزيرا حضورًا على Meta مخصصًا لزاوية الشدّ والعناية بمظهر السيلوليت التي تركها المنافس بلا إعلان وقت الرصد، دون ادعاءات طبية ودون ذكر المنافس أو المقارنة باسمه في الإعلان، وقِس النتائج قبل التوسّع.\nاختبار العرض لا نسخه: جرّب A/B مبدأ عرض الكمية (باقة متعددة مقابل خصم على القطعة الثانية) بما يناسب سعر وهامش زيرا فقط، ولا تنسخ Buy 2 Get 1 أو −50% نسخًا أعمى.\nاختبار التوقيت الموسمي: جرّب عرضًا واضحًا مرتبطًا بموسم محدد بسقف خصم مدروس وموعد انتهاء معلن، بدل تحويل الخصم الكبير إلى سعر دائم.\nتجنّب الاعتماد على الخصم وحده: ادعم العرض برسالة منتج وروتين عناية ومحتوى تعليمي غير طبي، لأن التسجيل المنافس يوثّق منتجات وعروضًا فقط ولا يوثّق زاوية محتوى مميزة يمكن البناء عليها.\nالتتبّع قبل الحكم: كرّر الرصد المؤرّخ لعدد الإعلانات واستمراريتها وتغيّر العروض، ولا تعتبر بقاء الإعلان نشطًا وحده دليل مبيعات أو نجاح.','\n',char(10)),1795045337618);
INSERT INTO competitor_ad_analyses VALUES(6,5,'Alejon','مسجل: زاوية «الاستمرارية أولاً» للتعامل مع جلد الوزة وآثاره، عبر روتين ثنائي: غسول جسم + كريم يوريا، داخل إطار White Friday تحفيزي. مستنتج: الزاوية تبيع الالتزام بالروتين والباقة أكثر من منتج منفرد، مستندة إلى تموضع صيدلي عام مسجل للبراند: كريم يوريا 10% و20% للجلد الجاف الخشن وجلد الوزة.','«حل جلد الوزه واثار جلد الوزه قبل اي حاجه هو الاستمرار» — كما هو مسجل حرفياً؛ يضع الاستمرارية قبل أي حلّ أو منتج.','فيديو مباشر مسجل لجلد الوزة مدته 2:37 دقيقة، يذكر غسول جسم + كريم يوريا، وCTA: Get offer. غير مسجل: هوية/أسلوب المقدّم، النصوص على الشاشة، اللقطات، الشهادات، أو أي قبل/بعد؛ وباقي صيغ الـ~84 إعلاناً النشطة غير موصوفة في التسجيل.','نمط White Friday مسجل للبراند: Buy 2 Get 2 Free + هدية سرية Secret Gift (محتواها وقيمتها غير مسجلين) + شحن مجاني فوق 1,000 EGP. البروفايل المطابق: Urea Cream 10% — 200ml بسعر 380 EGP لدى AlFouad Pharmacies، وهو سعر بروفايل/صيدلية وليس سعراً مسجلاً لهذا الفيديو تحديداً. سعر باقة الغسول + الكريم في الفيديو وتركيز الكريم المستخدم فيه: غير مسجل.','الفيديو: بدء مسجل في 4 نوفمبر 2026 وكان ضمن النشط عند الرصد في 18 نوفمبر 2026؛ مدة تشغيل صريحة له غير مسجلة، و2:37 هي مدة الفيديو لا مدة التشغيل. تنبيه استمرارية: أقدم إعلانات البراند من 19 أغسطس 2026 (91 يوماً كما هو مسجل) تخص كريمات اليد والقدم والوجه، وليست دليلاً على عمر فيديو جلد الوزة. الـ~84 إعلاناً هي إجمالي نشاط البراند النشط عند الرصد، لا عدد إعلانات هذا المنتج.','استنتاج محتمل فقط — لا أرقام أداء مسجلة (لا CTR ولا مبيعات ولا ROAS): 1) الهوك يخاطب سبباً شائعاً لفشل الروتين وهو التوقف، فيبني توقعاً أكثر واقعية من وعد فوري، 2) pairing الغسول + الكريم يجعل الباقة منطقية ويرفع قيمة السلة، 3) حافز White Friday الكمي والشحن المجاني يخلق إلحاحاً موسمياً، 4) التموضع الصيدلي المسجل قد يدعم الثقة. بقاؤه نشطاً من 4 نوفمبر حتى الرصد مؤشر استمرار فقط، لا إثبات نجاح.','الأوضح من التسجيل: الرسالة عامة وقابلة للنسخ — «الاستمرار» دون تفاصيل مسجلة عن مدة الروتين أو خطواته أو ما يميز هذا الكريم، ودون توضيح مسجل إن كان كريم الفيديو 10% أم 20%. كذلك الهدية السرية غامضة القيمة، وعتبة الشحن المجاني 1,000 EGP (مستنتج حسابياً) بعيدة عن سعر العبوة المسجل 380 EGP، فالعرض يضغط نحو شراء كميات بدل تجربة أولى سهلة.',replace('اختبر/تبنَّ: زاوية الاستمرارية كروتين واضح الخطوات والتكرار لزيرا، لكن بصياغة استخدام واقعية وبلا وعد علاجي أو ضمان نتيجة؛ وقارنها بهوك فائدة يومية ملموسة.\nاختبر: نسخة فيديو تعليمية أطول مقابل نسخة مختصرة بنفس الروتين والـCTA، مع تثبيت العرض أثناء الاختبار حتى تُعرف نتيجة الصيغة لا العرض.\nتبنَّ بحذر: منطق الباقة الثنائية (تنظيف + كريم) كروتين واحد بدل منتج منفرد، مع إعلان السعر والحجم والتركيز بوضوح منذ البداية.\nتجنب النسخ الأعمى: لا تنسخ Buy 2 Get 2 Free + Secret Gift قبل حساب الهامش وسلة الشراء؛ اختبر هدية معلنة القيمة وعتبة شحن متناسبة مع سعر منتج زيرا بدل هدية غامضة.\nتجنب: أي مقارنة باسم Alejon وأي ادعاءات طبية أو علاجية لجلد الوزة؛ ميّز زيرا فقط بمواصفات موثقة خاصة بها (التركيز، الحجم، القوام، طريقة الاستخدام) دون ادعاء غير مسجل.','\n',char(10)),1795045379399);
INSERT INTO competitor_ad_analyses VALUES(7,6,'Soralone','مسجل: منتجات يوريا لجلد الوزة بأسعار منخفضة — Urea 15% Cream Gel + Urea 5% Shower Gel. مستنتج: الزاوية سعرية-موسمية بالأساس: دفعة Black Friday + دفع العميل لباقة/روتين من منتجين وشراء 3 منتجات، وليست زاوية نتيجة أو ادعاء طبياً موصوفاً في التسجيل.','غير مسجل: لا يوجد نص هوك أو جملة افتتاحية أو سكريبت أو وصف للمشاهد الأولى في التسجيل، فلا يمكن اختراع هوك محدد أو نسبته لهذه الدفعة.','مسجل في البروفايل العام: اعتماد على ريلز صانعي المحتوى وقمع شراء عبر واتساب، ونشاط على Meta Ads Library مصر بنحو ~56 إعلاناً نشطاً. غير مسجل: فورمات كل إعلان بعينه، مدة الفيديو، النص الإعلاني، الـCTA، أو كيفية تقسيم الـ~56 إعلاناً.','مسجل: خصم 50% عند شراء 3 منتجات + شحن مجاني فوق 1,500 EGP. سعر مخفض مسجل لـUrea 15% Gel: ~125 EGP (مسح 2026-11-18). سعر Urea 5% Shower Gel والسعر قبل الخصم: غير مسجل.','مسجل: كل الإعلانات بدأت بين 3–18 نوفمبر 2026 ورُصدت نشطة بتاريخ 2026-11-18، ولا يوجد إعلان عمره 30+ يوماً في الصفحة الأولى — دفعة Black Friday جديدة بالكامل. استمرارية أو مدة تشغيل مثبتة بعد تاريخ الرصد: غير مسجلة، فلا يُستنتج وجود إعلان رابح طويل العمر.','أداء فعلي مثبت: غير مسجل — لا توجد أرقام CTR أو مبيعات أو ROAS. مستنتج كفرضية فقط: إطلاق ~56 إعلاناً دفعة واحدة في Black Friday قد يتيح اختبار نسخ كثيرة بسرعة، بينما وضوح حافز الباقة والسعر المنخفض وتكامل الكريم والشاور وريلز الصانعين وواتساب قد يقلل احتكاك الشراء. هذه أسباب محتملة للانتشار، لا دليل نجاح.','الأوضح مسجلاً: غياب أي إعلان بعمر 30+ يوماً في الصفحة الأولى، أي لا دليل على استمرارية أو Winner دائم خارج حداثة الدفعة. مستنتج: الجاذبية تبدو معتمدة على الخصم والسعر أكثر من تمايز موصوف، وشرط شراء 3 منتجات وعتبة 1,500 EGP للشحن المجاني قد يرفعان حاجز إكمال السلة مقارنة بسعر الوحدة المخفض المسجل ~125 EGP.',replace('تختبر زيرا: إطلاق دفعة متنوعة ومنظمة في موسم شرائي بريلز صانعي محتوى ومسار شراء واضح، مع تتبع أي نسخة تستمر 30+ يوماً — دون افتراض أن كثرة الإعلانات وحدها دليل نجاح.\nتختبر زيرا: عرض روتين/باقة من منتجين مكملين وخصماً عند تعدد الوحدات مقابل عرض المنتج الواحد، مع قياس حجم السلة والهامش — دون نسخ 50% أو عتبة 1,500 EGP بشكل أعمى.\nتتبنى زيرا: توضيح التركيزات والروتين والسعر كما هي موثقة على منتجاتها وصفحاتها، دون ادعاءات طبية أو وعود بالعلاج أو الاختفاء، ودون ذكر Soralone أو المقارنة باسمه في الإعلان.\nتتجنب زيرا: الاعتماد الكلي على خصم موسمي عميق وعتبة شحن مرتفعة؛ تُختبر عتبة متناسبة مع سلة زيرا الفعلية وتُعرض شروط العرض بشفافية من البداية.\nتختبر زيرا: إبقاء إعلان Evergreen ثابت خارج الموسم ومراقبة استمراريته، للتمييز بين طلب حقيقي مستدام واندفاع موسمي مؤقت.','\n',char(10)),1795048153463);
INSERT INTO competitor_ad_analyses VALUES(8,7,'Centevia — براند مصري للعناية بالجسم بتركيز على الترطيب وباقات العرائس، منافس من جانب السيلوليت؛ وسم الأدلة: VERIFIED، والمصدر: Meta Ads Library — مصر.','المسجل: فيديو يتناول «جلد الوزة» ضمن فئة الترطيب والشدّ، ويرتبط بعرض Black Friday. المستنتج: زاوية مشكلة محددة مرتبطة بالترطيب ومظهر/ملمس الجلد، مع دافع شراء موسمي للتخزين — لا توجد في التسجيل صياغة حل أو ادعاء نتيجة محددة لهذا الإعلان.','غير مسجل نصياً أو بصرياً: التسجيل يذكر فقط أن الفيديو عن «جلد الوزة»، ولا يصف الجملة الافتتاحية أو المشهد الأول أو أول الثواني؛ لذلك لا يمكن الجزم بهوك محدد سوى أن موضوع المشكلة نفسه هو عنصر الجذب الموصوف.','المسجل: إعلان فيديو على Meta، ضمن نحو 7 إعلانات نشطة، وCTA: Send message. غير مسجل: مدة الفيديو بالثواني، أبعاده، نصه، وهل يظهر فيه صانع محتوى أو عرض بجهاز قياس الترطيب؛ فجهاز القياس ورد في تموضع البراند عامةً، لا في تفاصيل هذا الفيديو تحديداً.','المسجل في الإعلان: Black Friday — Buy 2 Get 2، دون ذكر منتج أو سعر محدد داخل تفاصيل الإعلان المسجلة. سياق منفصل من بروفايل المنافس بمسح 2026-11-18: Nourish-30 Lotion بسعر 400 EGP وباقة Bridal Bundle بسعر 888 EGP؛ لا يثبت التسجيل أن أيّاً منهما هو منتج هذا الفيديو أو أساس حساب عرضه.','المسجل: بدأ الإعلان في 15 أكتوبر 2026، ورُصد نشطاً في 18 نوفمبر 2026، والمدة المذكورة في التسجيل 34 يوماً حتى تاريخ الرصد. غير مسجل: أي استمرار أو توقف بعد 18 نوفمبر 2026.','استنتاج مرجّح لا نجاح مثبت: بقاؤه 34 يوماً حتى الرصد، ضمن نحو 7 إعلانات نشطة، مؤشر استمرارية فقط. يُرجّح أنه يعمل لثلاثة أسباب: مشكلة محددة وسهلة الفهم، عرض عددي بسيط في موسم Black Friday، وCTA محادثة منخفض الاحتكاك نسبياً للاستفسار والطلب. على مستوى البراند فقط سُجل توزيع قوي عبر صانعي المحتوى، لكن غير مسجل أن هذا الفيديو تحديداً من إنتاجهم. لا توجد أرقام CTR أو تكلفة أو مبيعات مسجلة، فلا يمكن تأكيد الأداء التجاري.','الأوضح من التسجيل: غموض قيمة العرض داخل تفاصيل الإعلان؛ فـBuy 2 Get 2 مذكور بلا منتج أو سعر أو إجمالي نهائي محدد، وبلا عنصر إثبات موصوف داخل هذا الفيديو تحديداً، بينما يضيف CTA المحادثة خطوة قبل الشراء ويتطلب العرض التزاماً بكمية أكبر قبل التجربة.',replace('اختبر ولا تنسخ: فيديو يفتتح بمشكلة بصرية واحدة محددة — مظهر الخشونة/جلد الوزة لغرض تجميلي — مقابل فيديو ترطيب عام، بنفس الجمهور والميزانية، وقارن بدء المحادثات المؤهلة ومعدل إتمام الطلب.\nتبنَّ الوضوح لا الصيغة حرفياً: اعرض ميكانيكية أي حزمة بصياغة وسعر خاصين بزيرا مع الإجمالي النهائي والشحن من أول رسالة، واختبر حزمة تجربة أصغر مقابل حزمة كمية أكبر لقياس حاجز الالتزام عند أول شراء.\nاختبر مسار الاستجابة: Send message مقابل مسار طلب مباشر لفترة محددة، واحكم بتكلفة المحادثة المؤهلة ونسبة تحويل المحادثة إلى طلب مؤكد، لا بعدد الرسائل فقط.\nأضف إثباتاً بصرياً خاصاً بزيرا بشروط تصوير وقياس موحدة لتوضيح الترطيب والملمس، دون ادعاء علاج أو نتيجة مضمونة؛ ولا تفترض أن هذا الإعلان المنافس استخدم إثباتاً بجهاز قياس، لأنه غير مسجل في تفاصيله.\nتجنب الاعتماد على خصم موسمي فقط: اختبر نسخة «عرض + قيمة/روتين استخدام» مقابل نسخة «عرض فقط»، وتابع الأداء الداخلي الفعلي بعد انتهاء الموسم قبل اعتبار أي صيغة رابحة.','\n',char(10)),1795048205535);
INSERT INTO competitor_ad_analyses VALUES(9,8,'Nefertari — المنافس المطابق (عناية جسم طبيعية، تشابه 68/100)؛ الرصد نفسه شمل أيضًا Tetavara وEra Care وKolagra وكلهم بصفر إعلانات نشطة','غير مسجلة — لا توجد زاوية إعلانية: صفر إعلانات نشطة لـNefertari على ميتا في مصر بتاريخ الرصد 2026-11-18 (VERIFIED، Meta Ads Library، ضمن رصد شمل أيضًا Tetavara وEra Care وKolagra). ما هو مسجل من البروفايل فقط — لا من إعلان — هو تموضع عناية جسم طبيعية 100% مصنوعة يدويًا منذ 1998 وروتينات خطوتين (سكراب + كريم)، ولا يجوز نسبته لإعلان غير موجود.','غير مسجل — لا يوجد هوك إعلاني، لأنه لا يوجد إعلان نشط مسجل لـNefertari يمكن استخراج أول سطر أو مشهد أو رسالة جذب منه.','غير مسجل — لا يوجد فورمات إعلاني لفحصه (لا فيديو أو صورة أو كاروسيل أو نص إعلان موصوف في التسجيل) لعدم وجود أي إعلان نشط مسجل؛ مصدر الرصد فقط هو Meta Ads Library.','عرض إعلاني غير مسجل لعدم وجود إعلان. العرض المسجل من موقع Nefertari الرسمي وردود البراند فقط — وليس من إعلان ميتا — هو: The Secret Scrub وروتينات خطوتين (سكراب/كريم)، بأسعار سكراب 465-535 EGP، زبدة شيا 455 EGP، كريم/سكراب قدم 465-535 EGP. ملحوظة سياقية مسجلة منفصلة: Tetavara كان مظلمًا على ميتا رغم عرض Pink Friday على موقعه (كريم Buy 1 Get 1 بسعر 350 EGP)، وهذا عرض Tetavara لا Nefertari.','غير مسجلة — لا يوجد تاريخ بدء إعلان ولا مدة تشغيل ولا استمرارية مسجلة. التاريخ الوحيد المسجل هو تاريخ الرصد 2026-11-18 الذي أظهر صفر إعلانات نشطة، ولا يمكن استنتاج مدة الغياب أو سببه من رصد واحد.','لا يمكن القول إنه شغال أو ناجح: غير مسجل أي إعلان أصلًا وغير مسجلة أي أرقام أداء أو مبيعات أو تفاعل في التسجيل. المستنتج فقط — كفرضية غير مثبتة — أن صفر إعلانات للأربعة براندات في لقطة 2026-11-18 قد يترك مساحة ظهور أقل ازدحامًا على ميتا، وهذا يحتاج اختبارًا وقياسًا فعليًا من حملات زيرا ولا يُقدَّم كنتيجة مسجلة عن Nefertari.','الضعف الأوضح المسجل: غياب كامل عن إعلانات ميتا النشطة في مصر وقت الرصد، رغم أن Nefertari يبيع أونلاين وله فروع في مصر ومنتجات وروتينات قابلة للترويج المدفوع؛ أي لا توجد رسالة مدفوعة مسجلة لالتقاط الطلب على هذه القناة في ذلك التاريخ. سبب الغياب (إيقاف مقصود أو الاعتماد على قنوات أخرى) غير مسجل.',replace('اختبر: حضورًا مدفوعًا منتظمًا لزيرا على ميتا لاستغلال فراغ اللقطة المسجلة 2026-11-18، مع إعادة فحص Meta Ads Library قبل الإطلاق مباشرة لأن الرصد لقطة يوم واحد وليس دليل غياب دائم.\nاختبر: محتوى روتين خطوتين (سكراب ثم كريم) بصياغة ومنتجات زيرا الخاصة، دون نسخ اسم The Secret Scrub أو أي ادعاء خاص بالمنافس.\nتبنَّ فقط ما هو مثبت لزيرا: لا تستخدم طبيعي 100% أو مصنوع يدويًا أو منذ 1998 في رسائل زيرا إلا إذا كانت صحيحة وموثقة لزيرا نفسها.\nتجنب: الادعاءات الطبية أو العلاجية مثل مضاد للسيلوليت أو الشد أو العلاج؛ اكتفِ بوصف تجميلي غير علاجي ومتوافق مع مستندات المنتج.\nاختبر: وضوح السعر والباقة في الإعلان مستخدمًا نطاق المنافس المسجل 465-535 EGP كمرجع سوقي داخلي فقط، دون ذكر اسم أي براند منافس أو عمل مقارنة باسم براند في الإعلان.','\n',char(10)),1795061570566);
INSERT INTO competitor_ad_analyses VALUES(10,9,'Alejon','زاوية مسجّلة موقعياً لا إعلانياً: يوريا 10% عامة للجلد الجاف الخشن مع تقشير لطيف يحسّن مظهر جلد الوزة/KP، داخل تموضع كوزميسيوتيكالز من تصميم صيدلانيات مصريات وتوزيع صيدلي. لا يوجد منتج مخصص لجلد الوزة؛ ذكرها المسجل في 4 صفحات فقط على الموقع كله. ملحوظة تناقض: بروفايل المنافس يذكر يوريا 10% و20%، لكن التصفح المسجل لم يُظهر للجسم إلا 10%، و30% لكريم القدم فقط.','غير مسجل: لا هوك إعلاني أو افتتاحية كرييتيف موصوفة. أقرب عنصر جذب مسجل على الموقع هو بانر White Friday: Buy 2 Get 2 + Secret Gift، ولا يجوز نسبته كهوك لحملة إعلانية غير موصوفة.','غير مسجل كفورمات إعلاني: لا نص أو فيديو أو صورة إعلان موصوفة في التسجيل. المسجل تصفح مباشر موثّق VERIFIED لموقع alejon.com بتاريخ 2026-11-18، يشمل كتالوجاً وصفحات منتجات وبانر White Friday.','مسجل موقعياً: Urea Cream 10% + Salicylic 2% + Shea بسعر 380 EGP/200ml و660 EGP/500ml (جديد)؛ Urea Body Wash 10% بسعر 390 EGP/500ml؛ Foot Cream 30% بسعر 295 EGP/75ml للقدم/الكالو فقط؛ Whitening Body Milk بسعر 360 EGP/200ml؛ Post-Laser Cream بسعر 240 EGP/75ml. العروض: Buy 2 Get 2 على أغلب الفردي، واشترِ 4 واحصل على الأرخصين مجاناً + هدية + شحن مجاني فوق 1,000 EGP. الباقة القريبة الوحيدة القابلة للشراء: Drink Your Water Box من 1,275 إلى 890 EGP؛ وكل الباقات الـ14 نفدت مخزوناً.','غير مسجلة: لا تاريخ بدء إعلان ولا مدة تشغيل ولا استمرارية مسجلة. المسجل فقط تاريخ رصد وتصفح واحد هو 2026-11-18، فلا يمكن استنتاج أن هذا إعلان مستمر أو طويل التشغيل.','لا نجاح أو أداء مثبت في التسجيل: لا مبيعات أو CTR أو تحويلات أو مدة تشغيل مسجلة. على الأرجح فقط، عوامل الجذب هي انخفاض السعر الفعلي عبر B2G2/شراء 4، وقيمة الحجم الأكبر (500ml بـ660 مقابل 200ml بـ380)، والثقة الصيدلية وادعاء التصميم بواسطة صيدلانيات مصريات، وتوفر منتجات فردية مكملة للغسول والترطيب؛ وهذا استنتاج من بنية العرض والتوزيع، لا نتيجة موثقة.','الأوضح: فجوة تخصص وتوفر وشفافية. لا منتج مخصص لجلد الوزة وتركيز الجسم المسجل 10% فقط، وكل الباقات الـ14 نفدت رغم قوة العروض، وقوائم INCI مقصوصة على الصفحات، وبعض المقاسات مستمدة من محتويات البوكسات لا صفحات المنتجات؛ فيتشتت مسار الشراء داخل كتالوج واسع بنحو 110 منتجات.',replace('تتبنّى/تختبر: منتج وصفحة واضحَين ومخصصَين لمشكلة واحدة بصياغة تحسين المظهر غير الطبية، وقياس أثر وضوح التخصص على التحويل مقابل تقديم منتج عام متعدد الاستخدامات.\nتختبر: سلّم أحجام بقيمة أوضح للملّيليتر وحجم أكبر أوفر، مع قياس متوسط قيمة الطلب وحجم السلة، دون نسخ أسعار المنافس أو عروضه حرفياً.\nتتجنّب: الترويج لباقات غير متوفرة؛ اختبر باقة واحدة ذات صلة ومتوفرة فعلياً، مع إظهار التوفر والشحن والعتبة بوضوح قبل أي حملة.\nتتبنّى: شفافية كاملة بنشر قوائم INCI غير مقصوصة، والتركيز ومنطقة الاستخدام لكل منتج للفصل بين استخدام الجسم والقدم، وقياس أثر ذلك على الأسئلة والمرتجعات.\nتختبر منفصلاً A/B: رسالة ثقة صيدلية/تركيبية، وهدية، وشحن مجاني فوق عتبة شراء، لمعرفة المحرك الحقيقي للشراء، دون ادعاءات علاج أو شفاء ودون مقارنات باسم أي براند في المحتوى العام.','\n',char(10)),1795061606215);
INSERT INTO competitor_ad_analyses VALUES(11,9,'Alejon — خط اليوريا / جلد الوزة (بيانات موقع موثقة VERIFIED من alejon.com)','مسجل: تموضع صيدلي «كوزميسيوتيكالز من تصميم صيدلانيات مصريات» حول يوريا 10% للعناية بالجلد الجاف الخشن وتحسين مظهر جلد الوزة بتقشير لطيف — كريم 10% + ساليسيليك 2% + شيا — وليس منتجاً مخصصاً لجلد الوزة. مستنتج: الزاوية قائمة على اللطف والثقة الصيدلية ودفع الشراء بالعروض، أكثر من التخصص في مشكلة واحدة.','الهوك الإعلاني (نص أو مشهد إعلان) غير مسجل — لا محتوى إعلان موصوفاً في التسجيل. أقرب عناصر جذب مسجلة على الموقع فقط: بانر White Friday ‏(Buy 2 Get 2 + Secret Gift)، وادعاء كريم اليوريا 10% المسجل: تقشير لطيف يحسّن مظهر جلد الوزة.','الفورمات الإعلاني غير مسجل. المسجل فقط: تصفح مباشر لموقع alejon.com في 2026-11-18 — صفحات منتجات فردية وكتالوج (~110 منتجات: 85 فردياً + 14 باقة + 11 بوكس) وبانرات عروض موقع، دون أي فيديو أو نص إعلان أو منصة إعلانية موصوفة في التسجيل.','مسجل: Urea Cream 10% ‏200ml بـ380 EGP و500ml بـ660 EGP (جديد)؛ Urea Body Wash 10% ‏500ml بـ390 EGP؛ Foot Cream 30% ‏75ml بـ295 EGP (قدم/كالو فقط)؛ Whitening Body Milk ‏200ml بـ360 EGP؛ Post-Laser Cream ‏75ml بـ240 EGP. عروض الموقع: Buy 2 Get 2 على أغلب الفردي + اشترِ 4 وخد الأرخصين مجاناً + هدية + شحن مجاني فوق 1,000 EGP. كل الـ14 باقة نفدت؛ أقرب باقة قابلة للشراء لجلد الوزة: Drink Your Water Box من 1,275 إلى 890 EGP.','غير مسجلة: لا تاريخ بدء ولا مدة تشغيل ولا استمرارية ولا أرقام أداء في التسجيل. المسجل فقط تاريخ رصد وتصفح واحد: 2026-11-18، مصدره alejon.com عبر جهاز المالك — ولا يجوز الاستنتاج منه مدة عرض أو نجاح.','الأداء/النجاح غير مسجل — لا أرقام أداء في التسجيل، والتالي مستنتج لا مسجل: على الأرجح الجاذبية من (1) ثقة التموضع الصيدلي وادعاء تصميم صيدلانيات مصريات والتوزيع الصيدلي الوارد في البروفايل المطابق، (2) عرض قيمة قوي: Buy 2 Get 2 وهدية وشحن مجاني فوق 1,000 EGP يخفض سعر الوحدة الفعلي، (3) مرساة حجم كبير 500ml بـ660 EGP مقابل 200ml بـ380 EGP، (4) تركيبة مفهومة للمستهلك: يوريا 10% + ساليسيليك 2% + شيا. يقابل ذلك تشتت كتالوج واسع ~110 منتجات.','أوضح نقطة ضعف مسجلة: غياب التخصص وانكسار مسار الشراء معاً — لا منتج مخصص لجلد الوزة وذكرها في 4 صفحات فقط على الموقع كله، وتركيز الجسم المسجل 10% فقط (30% للقدم/الكالو فقط)، وفي الوقت نفسه كل الـ14 باقة نفدت رغم دفع عروض وهدايا، مع قوائم INCI مقصوصة تضعف الشفافية. تنبيه تسجيلي: البروفايل المطابق يذكر يوريا 20% أيضاً، لكن التصفح الموثق لم يرصد للجسم إلا 10%.',replace('تتبنّى/تختبر: منتج وصفحة روتين مخصصين بوضوح لمشكلة واحدة بدل خط عام — اختبار A/B لصفحة متخصصة مقابل صفحة منتج عام بقياس التحويل وإتمام الشراء، دون أي ادعاء طبي.\nتختبر: مرساة حجم/قيمة واضحة (حجم أكبر بسعر أوضح لكل مل) وعتبة شحن مجاني محددة — بقياس متوسط قيمة السلة، دون نسخ الأسعار أو عرض Buy 2 Get 2 حرفياً.\nتتجنّب: تكديس عروض متداخلة والترويج لباقات غير متوفرة — اختبار عرض واحد واضح وباقة واحدة متوفرة فعلياً مقابل تعدد العروض، بقياس التخلي عن السلة.\nتتبنّى: شفافية كاملة — نشر قوائم INCI كاملة والمقاسات من صفحات المنتجات نفسها لا من محتويات البوكسات، واختبار أثر ذلك على أسئلة العملاء والتحويل.\nتختبر: محتوى ثقة قائم على خبرة فريق التطوير وروتين استعمال واضح (كيف ومتى ولأي منطقة) بصياغة تجميلية فقط، دون ادعاءات علاجية ودون مقارنات باسم أي براند.','\n',char(10)),1795061639748);
INSERT INTO competitor_ad_analyses VALUES(12,10,'غير محدد من التسجيل','مسجل: إعلان فيديو للعناية بالجسم ظهر ضمن بحث «جلد الوزة» (آخر 180 يومًا)، وظهرت نفس العبوة البيضاء بمضخة ضمن بحث «كريم يوريا». مستنتج بحذر فقط: الزاوية مرتبطة باهتمام جلد الوزة والعناية بالجسم؛ لا نص إعلاني أو وعد أو ادعاء مسجل في التسجيل.','غير مسجل: لا وصف في التسجيل للثواني الأولى أو لأي نص أو حوار أو عبارة افتتاحية لهذا الإعلان؛ المسجل فقط الصورة المصغرة لعبوة بيضاء بمضخة واسم غير مقروء.','مسجل: إعلان فيديو على TikTok Top Ads (مصر)، بصورة مصغرة تُظهر عبوة بيضاء بمضخة. غير مسجل: مدة الفيديو وأسلوب التصوير لهذا الإعلان؛ أسلوب صانع المحتوى مسجل لفيديو آخر بأنبوب أخضر مزرق ولا يُنسب لهذا الإعلان.','غير مسجل: لا سعر أو خصم أو حزمة أو ضمان مذكور في التسجيل؛ المسجل فقط هدف الحملة Traffic وميزانية عالية.','غير مسجلة: لا تاريخ بدء ولا مدة تشغيل للإعلان نفسه مسجلة؛ المسجل فقط تاريخ الرصد 2026-11-18 ونوافذ البحث — غائب في آخر 30 يومًا وظاهر في آخر 180 يومًا — وهذه النوافذ لا تثبت مدة تشغيل.','مسجل: ضمن أول 4 نتائج معروضة مجانًا لـ«جلد الوزة» كان الأعلى إعجابًا (12K)، مع وسم CTR أعلى 25% وميزانية عالية وهدف Traffic، وظهرت نفس العبوة في بحث «كريم يوريا» (9K إعجاب، CTR أعلى 22%)، وTop Ads عرض منتقى للأعلى أداءً. مستنتج: نجاحه الأرجح داخل هذا العرض هو جذب النقر والإعجاب عبر كلمتين مرتبطتين؛ لا مبيعات أو تحويلات مسجلة لإثبات أثر تجاري.','الأوضح مسجلًا: اسم البراند غير مقروء في الصورة المصغرة رغم الميزانية العالية وعدد الإعجاب الأعلى بين المعروض — جذب وإنفاق دون هوية واضحة قابلة للتمييز أو التذكر من التسجيل.',replace('اختبر: موضوع «جلد الوزة» على TikTok مصر بميزانية اختبار محدودة — المسجل صفر نتائج في آخر 30 يومًا و4 فقط في آخر 180 يومًا في العرض المجاني — وقِس CTR والإعجاب، دون اعتبار الغياب دليلًا على غياب كل المنافسة.\nتبنَّ: وضوح هوية زيرا واسمها مقروءًا في الصورة المصغرة وإطار الفيديو الأول، وتجنَّب هوية غير مقروءة كما في ضعف الإعلان المسجل؛ اختبر نسختين وقارن النقر والتذكر.\nتجنَّب: النسخ الأعمى للعبوة البيضاء بمضخة أو افتراض هوك أو أسلوب غير مسجل؛ اختبر فورمات فيديو عناية بالجسم خاصًا بزيرا بعرض عبوة واضح وسياق استخدام دون أي ادعاء طبي.\nاختبر: هدف Traffic بميزانية محدودة مقابل هدف حملة أعمق، وقارن جودة الزيارة والإجراء اللاحق لا الإعجاب وحده — فالمسجل للمنافس هو Traffic وميزانية عالية دون بيانات مبيعات.\nتجنَّب: بناء قرار إنفاق كبير على Top Ads وحده؛ وسّع الرصد قبل التوسع لأن العرض المجاني يُظهر أول 4 نتائج فقط وهو عرض منتقى للأعلى أداءً وليس مكتبة كاملة.','\n',char(10)),1795061696366);
INSERT INTO competitor_ad_analyses VALUES(13,25,'غير محدد من التسجيل','مستنتجة من العبارة المسجلة فقط: تخصيص نية «علاج جلد الوزة» بمنطقة محددة هي الوجه — صياغة [حل/علاج + المشكلة + الموضع]. ليست زاوية إعلان منافس موصوفة في التسجيل.','غير مسجل — لا يوجد هوك أو نص إعلاني موصوف؛ المسجل فقط عبارة الاقتراح نفسها: «علاج جلد الوزة في الوجه».','غير مسجل كفورمات إعلان — المصدر المسجل فقط هو اقتراح Google Egypt autocomplete بوسم SEARCH-LANGUAGE، ولا يوجد وصف لإعلان نصي أو بصري أو فيديو.','غير مسجل — لا يوجد منتج أو سعر أو خصم أو ضمان أو دعوة لاتخاذ إجراء في التسجيل.','غير مسجلة — لا يوجد تاريخ بدء تشغيل إعلان أو مدته؛ المسجل فقط تاريخ الرصد 2026-11-19 وأول ظهور الاقتراح في مسح 03:11 EET مقارنة بمسح 02:49 EET، وهذا لا يثبت استمرارية.','غير مسجل أي نجاح أو أرقام أداء. المستنتج على الأرجح فقط: ظهور الصياغة الجديدة كإشارة لغة بحث قد يدل على اهتمام بصياغة تجمع نية الحل مع تحديد الوجه، ما قد يرفع صلة المحتوى المطابق لعبارة المستخدم — دون إثبات نقرات أو تحويلات أو نجاح إعلان.','الأوضح: هشاشة الإشارة وتقلبها — اقتراح واحد ظهر واقتراح «علاج جلد الوزة في منطقة البكيني» اختفى بين مسحين متقاربين وباقي الكلمات الـ11 ثابتة، بلا منافس أو عرض أو أداء مسجل، فلا يمكن الجزم باتجاه حقيقي مقابل تذبذب عابر في autocomplete.',replace('اختبر: استخدام عبارة البحث المسجلة كسؤال/عنوان محتوى خاص بالوجه مقابل المحتوى العام عن جلد الوزة، مع قياس الظهور والنقر — دون وعد علاجي أو نتيجة مضمونة.\nتبنَّ: تقسيم الرسائل والمحتوى حسب منطقة الجسم ونية البحث بدل صياغة عامة واحدة، بشرط تأكد الإشارة بتكرار الرصد.\nاختبر بالمراقبة: إعادة مسح autocomplete في مواعيد وأيام متعددة قبل أي قرار؛ لا تُبنى استراتيجية على ظهور واحد في مسح 03:11 EET.\nتجنب: حذف أو إيقاف محتوى منطقة البكيني بناءً على اختفائه في مسح واحد فقط، وتجنب النسخ الأعمى لتقلب الاقتراحات.\nتجنب: أي ادعاءات طبية قاطعة خاصة بالوجه أو مقارنات باسم براند؛ استخدم لغة معلوماتية حذرة وأحِل الحالات الحساسة لمختص.','\n',char(10)),1795062502332);
INSERT INTO competitor_ad_analyses VALUES(14,24,'غير محدد من التسجيل','زاوية مسجلة كاقتراح بحث/محتوى محتمل، لا كزاوية إعلان موصوفة: ربط علاج جلد الوزة (KP) بالشعر تحت الجلد، مع شرح العلاقة بين التقشير/اليوريا والشعر تحت الجلد ضمن روتين KP.','غير مسجل كخطاف إعلاني؛ العبارة المسجلة الوحيدة هي اقتراح الإكمال التلقائي «علاج جلد الوزة والشعر تحت الجلد».','غير مسجل كفورمات إعلان؛ نوع الدليل المسجل هو SEARCH من Google Egypt autocomplete (suggestqueries.google.com، hl=ar، gl=eg) لكلمة «علاج جلد الوزة»، بتاريخ رصد 2026-11-19.','غير مسجل — لا يوجد عرض أو سعر أو خصم أو منتج أو دعوة لاتخاذ إجراء مذكورة في التسجيل.','غير مسجلة — لا توجد مدة تشغيل أو استمرارية مسجلة؛ المسجل فقط أول ظهور في مسح 2026-11-19 الساعة 02:30 EET، وحلوله محل «علاج جلد الوزة في المنزل» الذي خرج من القائمة.','لا يوجد نجاح إعلاني أو أرقام أداء مسجلة؛ المستنتج فقط أن الإشارة قد تكون قيّمة كدليل اهتمام بحثي، لأن الباحثين جمعوا مشكلتي جلد الوزة والشعر تحت الجلد في استعلام واحد وفق التسجيل، ما قد يطابق نية بحث مركّبة — وهذا استنتاج لا إثبات فعالية.','أوضح نقطة ضعف: الدليل نقطة رصد واحدة لاقتراح إكمال تلقائي متقلب، بلا منافس أو محتوى إعلان أو عرض أو أداء مسجل، فلا يثبت وحده حجم الطلب أو استمراريته أو نية الشراء.',replace('اختبر: محتوى تعليمي لزيرا يجيب عن الاستعلام المركّب ويشرح صلة التقشير/اليوريا بالشعر تحت الجلد بلغة عناية وصفية غير علاجية، وقارن تفاعله بمحتوى KP العام.\nتبنّى: إعادة مسح اقتراحات Google Egypt لنفس الكلمة في مسوح لاحقة للتحقق من بقاء الاقتراح قبل اعتباره اتجاهاً ثابتاً.\nاختبر: قسم أسئلة/إجابة مباشرة يطابق صياغة «علاج جلد الوزة والشعر تحت الجلد»، دون ادعاءات طبية أو مقارنات باسم براند.\nتجنّب: تحويل رصد واحد إلى ادعاء بحجم بحث أو نجاح منافس أو أساس لحملة واسعة؛ لا منافس ولا أداء مسجل هنا.\nتجنّب: النسخ الأعمى للزاوية كوعد بالعلاج أو الشفاء، وأخضع أي صياغة مختبرة لمراجعة الادعاءات أولاً.','\n',char(10)),1795062513427);
INSERT INTO competitor_ad_analyses VALUES(15,25,'غير محدد من التسجيل','مسجل: زاوية لغة بحث علاجية محددة بالموضع — «علاج جلد الوزة في الوجه» ضمن مجموعة «علاج جلد الوزة». مستنتج فقط: وجود اهتمام بصياغة مخصصة للوجه بدل الصياغة العامة. لا توجد زاوية إعلان لمنافس مسجلة.','غير مسجل — لا يوجد هوك إعلان في التسجيل. العبارة الظاهرة «علاج جلد الوزة في الوجه» هي اقتراح بحث فقط، ولا يمكن اعتبارها هوكاً إعلانياً لمنافس.','غير مسجل كفورمات إعلان — المصدر المسجل هو Google Egypt autocomplete (suggestqueries.google.com, hl=ar, gl=eg) بوسم الأدلة SEARCH-LANGUAGE. لا يوجد وصف لنص أو صورة أو فيديو أو قالب إعلان.','غير مسجل — لا يوجد منتج أو سعر أو خصم أو ضمان أو باقة أو دعوة لاتخاذ إجراء مذكورة في التسجيل.','غير مسجلة — لا توجد مدة تشغيل أو استمرارية لإعلان. المسجل فقط: تاريخ الرصد 2026-11-19، وظهور الاقتراح لأول مرة في مسح 03:11 EET مقابل مسح سابق في 02:49 EET من اليوم نفسه؛ هذا توقيت رصد لاقتراح بحث، وليس تاريخ بدء إعلان أو مدته.','لا يوجد دليل مسجل على أن إعلاناً ناجح أو على أي أرقام أداء. المستنتج المحتمل كإشارة طلب فقط: التحديد بالموضع في «في الوجه» قد يعكس نية بحث أدق من البحث العام عن علاج جلد الوزة، لكن ظهوره في مسح واحد لا يثبت حجم الطلب أو استمراره أو ارتباطه بأي منافس.','أوضح ضعف: الإشارة غير منسوبة وربما عابرة؛ ظهر اقتراح واحد في مسح واحد بينما اختفى «علاج جلد الوزة في منطقة البكيني» وبقيت الكلمات الـ11 الأخرى دون تغيير، ولا يوجد منافس أو محتوى أو عرض أو أداء يمكن تقييمه، لذا لا تصلح وحدها أساساً لاستنتاج تنافسي.',replace('اختبر: محتوى تعليمياً بصيغة سؤال وجواب موجز يطابق لغة البحث «جلد الوزة في الوجه»، مع توضيح الفرق بين احتياجات الوجه والجسم ودون وعد بالعلاج أو الشفاء.\nتبنَّ: الرصد المتكرر لاقتراحات البحث عبر مسوح متعددة قبل اتخاذ قرار؛ لا تبنِ حملة على ظهور واحد في مسح 03:11 EET.\nاختبر: صفحة أو قسم أسئلة شائعة بالعربية المصرية يستخدم عبارة البحث نفسها في العنوان والسؤال، ثم قِس الطلب الفعلي من الاستفسارات وبيانات البحث قبل توسيع المحتوى.\nتجنب: استخدام كلمة «علاج» كادعاء طبي لمنتج زيرا، وتجنب أي مقارنات باسم براند منافس؛ استخدم لغة تعليمية حذرة ومراجعة مختص عند الحاجة.\nاختبر: ما إذا كان التخصيص بالموضع (الوجه) يحقق تفاعلاً أعلى من المحتوى العام عن جلد الوزة، مع مقارنة النتائج داخلياً فقط ودون ادعاء تفوق غير موثق.','\n',char(10)),1795062519766);
